L["idTip conflicts with EllesmereUI's tooltip systems. Disable the idTip addon to stay compatible."] = "idTip choca con los sistemas de descripciones de EllesmereUI. Desactiva el addon idTip para que sean compatibles."
L["EllesmereUI WonderBar was renamed to EllesmereUI DataBars. The old WonderBar addon is still installed and both create the same bar. Please disable or delete the EllesmereUIWonderBar addon."] = "EllesmereUI WonderBar ahora se llama EllesmereUI DataBars. El addon WonderBar antiguo sigue instalado y los dos crean la misma barra. Desactiva o borra el addon EllesmereUIWonderBar."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "El gestor de perjuicios personalizado de este grupo solo se puede activar o editar mientras juegas con una de sus especializaciones."
L["Another override group already provides the custom Debuff Manager for your current spec."] = "Otro grupo de ajustes ya da el gestor de perjuicios personalizado a tu especialización actual."
L["Your current spec has its own custom Debuff Manager, so conditional Debuff Managers never apply to it."] = "Tu especialización actual tiene su propio gestor de perjuicios personalizado, así que los gestores condicionales nunca se le aplican."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Esto creará un gestor de perjuicios totalmente propio para este grupo de ajustes. Se copia tu gestor de perjuicios actual como punto de partida, y lo que cambies en tu gestor predeterminado ya no afectará a estas especializaciones."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Esto creará un gestor de perjuicios totalmente propio para este grupo condicional. Se copia tu gestor de perjuicios actual como punto de partida, y lo que cambies en tu gestor predeterminado ya no le afectará."
L["Debuff Manager changes on this page apply only to this override."] = "Los cambios del gestor de perjuicios en esta página solo se aplican a este ajuste."
L["%s Override Active"] = "Ajuste propio de %s activo"
L["The active override's custom %s is bound to this page. Leave the %s tab to switch to another override."] = "El %s personalizado del ajuste activo está ligado a esta página. Sal de la pestaña %s para cambiar a otro ajuste."
L["Delete Custom Debuff Manager"] = "Eliminar el gestor de perjuicios personalizado"
L["Delete the custom Debuff Manager for '%s'? Its specs return to your default Debuff Manager."] = "¿Eliminar el gestor de perjuicios personalizado de «%s»? Sus especializaciones vuelven a tu gestor de perjuicios predeterminado."
L["Delete the custom Debuff Manager for '%s'? Its conditions return to your default Debuff Manager."] = "¿Eliminar el gestor de perjuicios personalizado de «%s»? Sus condiciones vuelven a tu gestor de perjuicios predeterminado."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Estas especializaciones tienen valores de ajustes a los que ya no llega el modo de edición de ningún grupo (se quedaron por cambios en los miembros). Siguen aplicándose. Quita uno para devolver esa especialización al valor común."
