L["Cast Color Settings"] = "Ajustes del color del lanzamiento"
L["DPS: Show Special \"No Aggro\" Color"] = "DPS: mostrar el color especial «Sin aggro»"
L["EXTRA AURA OPTIONS"] = "OPCIONES DE AURAS ADICIONALES"
L["Full Sized (Health + Cast Bar)"] = "Completo (salud + hechizos)"
L["Fixed Position"] = "Posición fija"
L["Highlight Color"] = "Color de resaltado"
L["Highlight Opacity"] = "Opacidad del resaltado"
L["Icon on Right"] = "Icono a la derecha"
L["Important Cast"] = "Lanzamiento importante"
L["Important Cast Color"] = "Color importante"
L["Interrupt Ready Mid-Cast"] = "Interrupción lista a mitad del lanzamiento"
L["Interrupted Flash Colour"] = "Color del destello de interrupción"
L["Kick Ready Mid-Cast Hint"] = "Aviso interrupción lista"
L["More Effects"] = "Más efectos"
L["Quest Objective"] = "Objetivo de misión"
L["Replace Quest Icon with Objective"] = "Objetivo en lugar de icono misión"
L["Show Interrupted Flash Effect"] = "Destello al interrumpir"
L["Show Kick Ready Mid-Cast Bar"] = "Barra de interrupción lista"
L["Show Kick Ready Mid-Cast Tick"] = "Marca de interrupción lista"
L["Show Shield Icon"] = "Mostrar el icono de escudo"
L["Tank: Show Special \"Has Aggro\" Color"] = "Tanque: color especial «Tiene aggro»"
L["Tank: Show Special \"Off-Tank\" Color"] = "Tanque: color «Segundo tanque»"
L["Tick"] = "Marca"
L["Tick + Bar"] = "Marca + barra"
L["Uninterruptible Cast"] = "Lanzamiento no interrumpible"
L["Hide Items if Missing"] = "Ocultar si no tienes"
L["Rare/Quest Indicator"] = "Indicador de raro/misión"
L["Stripes"] = "Franjas"
L["Target Arrows"] = "Flechas del objetivo"
L["Target Glow Style"] = "Estilo del brillo del objetivo"
L["Target Highlight"] = "Resaltado del objetivo"
L["Target Texture"] = "Textura del objetivo"
L["Top Text"] = "Texto superior"
L["Wide Stripes"] = "Franjas anchas"
L["Shows a single Blood Plague debuff on enemy nameplates instead of one per copy (Blood Boil from weapon copies)."] = "Muestra una sola vez el perjuicio Peste de sangre en las placas de nombre enemigas en lugar de una por cada copia (Hervor de sangre de las copias del arma)."
L["Size of the level in the border's plate. 0 follows the bar height."] = "Tamaño del nivel en la placa del borde. 0 sigue la altura de la barra."
L["Size of the icon that replaces the level on a boss. 0 follows the bar height."] = "Tamaño del icono que sustituye al nivel en un jefe. 0 sigue la altura de la barra."
L["Disabled when the Name/Level text is centered on the health bar due to overlapping text"] = "Desactivado cuando el texto de nombre/nivel está centrado en la barra de salud porque los textos se solapan"
L["Hide the 1-pixel border around the cast bar spell icon."] = "Oculta el borde de 1 píxel alrededor del icono del hechizo de la barra de hechizos."
L["Adjusts the size of friendly player names shown in Name Only mode. Default is 15."] = "Ajusta el tamaño de los nombres de los jugadores amistosos en el modo solo nombre. Por defecto, 15."
L["Adjusts the vertical spacing between stacked nameplates. 100% = default, lower = tighter, higher = more spread."] = "Ajusta el espacio vertical entre las placas de nombre apiladas. 100 % = predeterminado; menos, más juntas; más, más separadas."
L["Choose which nameplates stack vertically instead of overlapping."] = "Elige qué placas de nombre se apilan en vertical en lugar de solaparse."
L["Colors enemy nameplates for quest mobs you still need to kill."] = "Colorea las placas de nombre enemigas de las criaturas de misión que aún tienes que matar."
L["Display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. This is the same setting as in the FocusKick bar options. Disabled for specs with no kick."] = "Muestra la palabra «FOCUS» bajo los lanzadores de hechizos y minijefes en M+ si no has fijado tu foco. Es el mismo ajuste que en las opciones de la barra FocusKick. Desactivado en las especializaciones sin interrupción."
L["Draws a white letter F on your current focus target's nameplate."] = "Dibuja una letra F blanca en la placa de nombre de tu foco actual."
L["Enables a three-tier tank aggro system: has aggro, losing aggro, and no aggro colors override all mob-type colors."] = "Activa un sistema de aggro de tanque de tres niveles: los colores de tener el aggro, perder el aggro y no tenerlo sustituyen a todos los colores por tipo de criatura."
L["Flash the enemy's cast bar and show \"Interrupted\" for a moment when their cast is interrupted. Use the swatch to change the flash colour."] = "Hace parpadear la barra de hechizos del enemigo y muestra «Interrumpido» un momento cuando se interrumpe su lanzamiento. Usa la muestra para cambiar el color del destello."
L["Forces all casts to be shown in front of nameplates for visual clarity"] = "Fuerza a que todos los lanzamientos se muestren por delante de las placas de nombre para que se vean mejor"
L["Full alpha on empty part of bar"] = "Alfa completo en la parte vacía"
L["Has Aggro"] = "Tiene el aggro"
L["Hide consumable items (potions, healthstone) from the bar when you have none in your bags, instead of showing them dimmed. They reappear automatically once you have the item again."] = "Oculta de la barra los consumibles (pociones, piedra de salud) cuando no tienes ninguno en las bolsas, en lugar de mostrarlos atenuados. Vuelven a aparecer automáticamente en cuanto tienes el objeto otra vez."
L["Hide friendly player health bars and instead only see their names.\n\nRequires 'Simplified Friendly Nameplates' to be disabled in Blizzard's Nameplate settings (Esc > Options > Nameplates)."] = "Oculta las barras de salud de los jugadores amistosos y muestra solo sus nombres.\n\nNecesita que «Placas de nombre amistosas simplificadas» esté desactivado en los ajustes de placas de nombre de Blizzard (Esc > Opciones > Placas de nombre)."
L["Hide the enemy name text while that nameplate's cast bar is visible."] = "Oculta el nombre del enemigo mientras se ve la barra de hechizos de esa placa de nombre."
L["Increases the cast bar height on your focus target's nameplate. 100% = normal height."] = "Aumenta la altura de la barra de hechizos en la placa de nombre de tu foco. 100 % = altura normal."
L["Increases the clickable hitbox height of enemy nameplates. 100% = matches bar height. Increase to make nameplates easier to click."] = "Aumenta la altura de la zona de clic de las placas de nombre enemigas. 100 % = igual que la altura de la barra. Súbela para que sea más fácil hacer clic en ellas."
L["Interrupt on CD"] = "Interrupción en tiempo de reutilización"
L["Interruptible Cast"] = "Lanzamiento interrumpible"
L["Losing Aggro"] = "Perdiendo el aggro"
L["Make friendly player and NPC nameplates click-through so their names never block your mouse or cause accidental friendly targeting.\n\nUse this when friendly names get in the way of clicking the world or the enemy nameplates behind them."] = "Hace que las placas de nombre de jugadores y PNJ amistosos dejen pasar los clics, para que sus nombres nunca tapen el ratón ni hagan que selecciones a un aliado sin querer.\n\nÚsalo cuando los nombres amistosos te estorben al hacer clic en el mundo o en las placas de nombre enemigas de detrás."
L["Make the spell icon a large square the combined height of the health bar plus the cast bar, flush with the top of the health bar and the bottom of the cast bar."] = "Hace que el icono del hechizo sea un cuadrado grande del alto de la barra de salud más la barra de hechizos, alineado con el borde superior de la barra de salud y el inferior de la barra de hechizos."
L["Maximum number of debuff icons shown on enemy nameplates."] = "Número máximo de iconos de perjuicio en las placas de nombre enemigas."
L["Mini-Bosses"] = "Minijefes"
L["Mini Enemies"] = "Enemigos menores"
L["Mini Coloring M+ Only"] = "Colores menores solo M+"
L["Nameplates opacity for units that are out of line of sight. 0 = fully transparent, 1 = fully opaque."] = "Opacidad de las placas de nombre de las unidades fuera de la línea de visión. 0 = totalmente transparente, 1 = totalmente opaco."
L["Near Aggro"] = "Cerca del aggro"
L["No Aggro"] = "Sin aggro"
L["Nudge the cast bar up or down from its default spot under the health bar."] = "Mueve un poco hacia arriba o hacia abajo la barra de hechizos desde su sitio predeterminado bajo la barra de salud."
L["On quest mobs in the open world, replaces the quest icon with the objective progress (ex: kill quests show 0/6, percentage objectives show 50%)."] = "En las criaturas de misión del mundo abierto, sustituye el icono de misión por el progreso del objetivo (p. ej., las misiones de matar muestran 0/6 y los objetivos por porcentaje, 50 %)."
L["Pixel-perfect border around the cast bar. Set to 0 for no border."] = "Borde perfecto al píxel alrededor de la barra de hechizos. Pon 0 para no tener borde."
L["Place the cast bar spell icon on the right side of the bars instead of the left."] = "Coloca el icono del hechizo de la barra de hechizos a la derecha de las barras en lugar de a la izquierda."
L["Raise Strata"] = "Subir nivel de capa"
L["Requires Name Only mode"] = "Necesita el modo solo nombre"
L["Requires Name Only setting to be disabled"] = "Necesita que el ajuste solo nombre esté desactivado"
L["Requires Show Friendly NPC Nameplates to be enabled"] = "Necesita activar «Mostrar las placas de nombre de los PNJ amistosos»"
L["Scales enemy nameplates while they are casting. 100% = no change."] = "Agranda las placas de nombre enemigas mientras lanzan. 100 % = sin cambios."
L["Scales your current target's nameplate. 100% = no change."] = "Agranda la placa de nombre de tu objetivo actual. 100 % = sin cambios."
L["Show a glow on the cast bar when the enemy is casting a spell Blizzard marks as important."] = "Muestra un brillo en la barra de hechizos cuando el enemigo lanza un hechizo que Blizzard marca como importante."
L["Show a shield icon on the cast bar when an enemy's cast cannot be interrupted."] = "Muestra un icono de escudo en la barra de hechizos cuando no se puede interrumpir el lanzamiento de un enemigo."
L["Show EUI Friendly Player Nameplates"] = "Ver placas EUI de jugadores amigos"
L["Show Hash Line on Target at Percent"] = "Línea en el objetivo al porcentaje"
L["Show/Hide Hitbox Overlay"] = "Mostrar/ocultar la capa de la zona de clic"
L["Show successful interrupt lockouts in the crowd-control icon slot.\n\nDue to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "Muestra los bloqueos por interrupción con éxito en la casilla del icono de control de masas.\n\nPor las restricciones a los addons, la duración que se muestra es de 4 segundos para todas las clases, así que no es exacta al 100 %."
L["Show/Hide on Preview"] = "Mostrar/ocultar en la vista previa"
L["Shows the target marker directly before the enemy name text. Uses its own size and does not use the Core Positions raid marker slot."] = "Muestra la marca del objetivo justo antes del nombre del enemigo. Usa su propio tamaño y no la casilla de marca de banda de las posiciones principales."
L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "Muestra una pequeña marca blanca en la barra de hechizos en el punto donde irá el lanzamiento cuando tu interrupción esté lista."
L["Shows a special color for nameplates that another tank in your raid has aggro on."] = "Muestra un color especial en las placas de nombre de los enemigos que tienen el aggro en otro tanque de tu banda."
L["Shows a special color for non caster/mini-boss enemies when you do not have aggro on them."] = "Muestra un color especial en los enemigos que no son lanzadores ni minijefes cuando no tienes su aggro."
L["Shows a special color for non caster/mini-boss enemies when you have aggro on them."] = "Muestra un color especial en los enemigos que no son lanzadores ni minijefes cuando tienes su aggro."
L["Shows where your interrupt will be ready during an enemy cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Muestra cuándo estará lista tu interrupción durante un lanzamiento enemigo. «Marca» señala el punto exacto en la barra de hechizos; «Marca + barra» también colorea el tramo en el que tendrás la interrupción disponible."
L["Spell Casters"] = "Lanzadores de hechizos"
L["Spell Icon"] = "Icono de hechizo"
L["This option is only used by the Basic border."] = "Esta opción solo la usa el borde Básico."
L["This option requires a text to be assigned"] = "Esta opción necesita que haya un texto asignado"
L["This option requires an aura or indicator to be assigned"] = "Esta opción necesita que haya un aura o un indicador asignado"
L["Tint the cast bar with the Important colour when the enemy casts a spell the game flags as important. Overrides the Interruptible Cast colour; your interrupt being on cooldown still takes priority."] = "Tiñe la barra de hechizos con el color Importante cuando el enemigo lanza un hechizo que el juego marca como importante. Sustituye al color de lanzamiento interrumpible; si tu interrupción está en tiempo de reutilización, eso sigue teniendo prioridad."
L["Toggle visibility of enemy pet nameplates."] = "Muestra u oculta las placas de nombre de las mascotas enemigas."
L["Uses the Hover Effect color and opacity. Set to None for the flat hover highlight."] = "Usa el color y la opacidad del efecto al pasar el ratón. Pon Ninguno para un resaltado plano."
L["Wrap"] = "Ajuste de línea"
L["Width %"] = "Anchura %"
L["When disabled, EUI relinquishes full control of friendly player nameplates to Blizzard. Use Blizzard's own Nameplate settings (Esc > Options > Nameplates) to control them."] = "Si está desactivado, EUI deja a Blizzard el control total de las placas de nombre de los jugadores amistosos. Usa los ajustes de placas de nombre de Blizzard (Esc > Opciones > Placas de nombre) para controlarlas."
L["When your interrupt is on cooldown now but will be ready before the enemy cast finishes, color the part of the cast bar during which your interrupt will be available. The color clears the instant your interrupt comes off cooldown."] = "Si tu interrupción está ahora en tiempo de reutilización pero estará lista antes de que termine el lanzamiento enemigo, colorea la parte de la barra de hechizos en la que tendrás la interrupción disponible. El color desaparece en cuanto tu interrupción está lista."
L["Widens the clickable hitbox of enemy nameplates. 100% = matches bar width. Increase to make nameplates easier to click."] = "Ensancha la zona de clic de las placas de nombre enemigas. 100 % = igual que la anchura de la barra. Súbela para que sea más fácil hacer clic en ellas."
L["Changing Max Debuffs requires a UI reload to take effect."] = "Cambiar el máximo de perjuicios necesita recargar la interfaz."
L["%1$s Slot Settings"] = "Ajustes de la casilla %1$s"
L["Level %d"] = "Nivel %d"
L["Dispel Glow"] = "Brillo de disipación"
L["Lets long text wrap onto a second line instead of being cut off."] = "Permite que el texto largo pase a una segunda línea en lugar de cortarse."
L["Maximum width the text can fill before it truncates, as a percentage of the bar."] = "Anchura máxima que puede ocupar el texto antes de cortarse, en porcentaje de la barra."
L["NPC Bar & Name Color"] = "Color de la barra y del nombre de los PNJ"
L["Renders this slot's element above the rest of the nameplate."] = "Dibuja el elemento de esta casilla por encima del resto de la placa de nombre."
L["Requires Name Only mode to be disabled"] = "Necesita que el modo solo nombre esté desactivado"
L["Show All Enemy Buffs"] = "Ver benef. enemigos"
L["White"] = "Blanco"
L["Distance Text"] = "Texto de distancia"
L["Distance to Target Text (Range)"] = "Texto de distancia al objetivo (alcance)"
L["Shows the approximate distance to your current target on its nameplate as a range bracket, e.g. 15+ when the target is 15-20 yards away."] = "Muestra la distancia aproximada a tu objetivo actual en su placa de nombre como un tramo de alcance; p. ej., 15+ cuando el objetivo está a entre 15 y 20 m."
L["TARGET AND FOCUS EFFECTS"] = "EFECTOS DEL OBJETIVO Y DEL FOCO"
L["Appearance"] = "Apariencia"
L["circle"] = "círculo"
L["Combine Spell Name and Target"] = "Juntar hechizo y objetivo"
L["cropped"] = "recortado"
L["Debuff Filter"] = "Filtro de perjuicios"
L["Debuffs + CC"] = "Perjuicios + CC"
L["diamond"] = "rombo"
L["Don't tint (keep bar's own color)"] = "No teñir (mantener el color de la barra)"
L["Due to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "Por las restricciones a los addons, la duración que se muestra es de 4 segundos para todas las clases, así que no es exacta al 100 %."
L["Dynamic"] = "Dinámico"
L["Execute Pulse Glow"] = "Brillo de ejecución"
L["Filters"] = "Filtros"
L["Flash"] = "Destello"
L["hexagon"] = "hexágono"
L["instances"] = "estancias"
L["Keep Focus Full Opacity"] = "Foco totalmente opaco"
L["portrait"] = "retrato"
L["Pulses a red glow on enemy nameplates below 30% health."] = "Hace latir un brillo rojo en las placas de nombre enemigas con la salud por debajo del 30 %."
L["Set to None for the flat hover highlight."] = "Pon Ninguno para un resaltado plano."
L["Show successful interrupt lockouts in the crowd-control icon slot."] = "Muestra los bloqueos por interrupción con éxito en la casilla del icono de control de masas."
L["square"] = "cuadrado"
L["Target Border Color"] = "Color del borde del objetivo"
L["Tints the pattern with the bar's current color instead of the custom overlay color."] = "Tiñe el dibujo con el color actual de la barra en lugar del color de la capa personalizada."
L["Uses the Hover Effect color and opacity."] = "Usa el color y la opacidad del efecto al pasar el ratón."
L["NAMEPLATE AURA FILTERS"] = "FILTROS DE AURAS DE LAS PLACAS DE NOMBRE"
L["Enter the spell ID to exclude from nameplates."] = "Escribe el ID del hechizo que quieres quitar de las placas de nombre."
L["This option requires Subtitle Text to include the Guild Name"] = "Esta opción necesita que el texto del subtítulo incluya el nombre de la hermandad"
L["Subtitle Text Settings"] = "Ajustes del subtítulo"
L["Show <> Around Guild"] = "Ver <> en hermandad"
L["Show the player's title inline with their name, and/or their guild on a line below it, on friendly nameplates."] = "En las placas de nombre amistosas, muestra el título del jugador junto a su nombre y/o su hermandad en una línea debajo."
L["Your focus target's nameplate never fades with the non-target opacity."] = "La placa de nombre de tu foco nunca se atenúa con la opacidad de los que no son tu objetivo."
L["INCLUDED DEBUFFS"] = "PERJUICIOS INCLUIDOS"
L["Debuff Custom Spell IDs"] = "ID de hechizos personalizados de perjuicios"
L["CC Custom Spell IDs"] = "ID de hechizos personalizados de CC"
L["Debuffs + CC Custom Spell IDs"] = "ID de hechizos personalizados de perjuicios + CC"
L["Enter the spell ID to always show on nameplates."] = "Escribe el ID del hechizo que quieres mostrar siempre en las placas de nombre."
L["Enter the spell ID to always show."] = "Escribe el ID del hechizo que quieres mostrar siempre."
L["Enter the spell ID to exclude."] = "Escribe el ID del hechizo que quieres quitar."
L["Enter the spell ID to always show on this frame."] = "Escribe el ID del hechizo que quieres mostrar siempre en este marco."
L["Enter the spell ID to exclude from this frame."] = "Escribe el ID del hechizo que quieres quitar de este marco."
L["MINE"] = "MÍOS"
L["Showing this aura from any caster; click for your casts only."] = "Se muestra esta aura de cualquier lanzador; haz clic para ver solo las tuyas."
L["Showing this aura from your casts only; click for any caster."] = "Se muestra esta aura solo de tus lanzamientos; haz clic para ver las de cualquier lanzador."
L["Range Check"] = "Comprobación de alcance"
L["Auto (Class/Spec)"] = "Automático (clase/especialización)"
L["Disabled runs no nameplate range checks. Auto uses your class and specialization's normal attack range. Custom uses the range set in the cog beside this option."] = "Desactivado no comprueba el alcance de las placas de nombre. Automático usa el alcance normal de ataque de tu clase y especialización. Personalizado usa el alcance que pongas en el engranaje junto a esta opción."
L["Out of Range Opacity"] = "Opacidad fuera de alcance"
L["Opacity used for enemy nameplates outside the selected attack range."] = "Opacidad de las placas de nombre enemigas que están fuera del alcance de ataque elegido."
L["Range Check: Auto or Custom"] = "Comprobación de alcance: automática o personalizada"
L["Range Check: Custom"] = "Comprobación de alcance: personalizada"
L["This feature runs continuous range checks against every visible enemy nameplate. It is one of the more expensive features in EllesmereUI and can measurably increase CPU usage in crowded areas."] = "Esta función comprueba sin parar el alcance de cada placa de nombre enemiga visible. Es de las funciones más pesadas de EllesmereUI y puede subir de forma notable el uso de CPU en zonas con mucha gente."
L["Custom Range"] = "Alcance personalizado"
L["Attack-range cutoff used by Out of Range Opacity. Five-yard steps match the available fallback range checks."] = "Límite de alcance de ataque que usa la opacidad fuera de alcance. Los pasos de cinco metros coinciden con las comprobaciones de alcance alternativas disponibles."
L["Hide Enemy Nameplates out of Combat"] = "Ocultar placas enemigas sin combate"
L["Hide enemy nameplates while you are out of combat; they return the moment combat starts. Drives the same game setting as the Show Enemy Name Plates keybind."] = "Oculta las placas de nombre enemigas mientras estás fuera de combate; vuelven en cuanto empieza el combate. Usa el mismo ajuste del juego que el atajo de mostrar las placas de nombre enemigas."
L["Adds a steady red glow around the nameplate while the Near Aggro color is active."] = "Añade un brillo rojo fijo alrededor de la placa de nombre mientras está activo el color «Cerca del aggro»."
L["Out of Combat Color"] = "Color fuera de combate"
L["Glow Nameplate When Near Aggro"] = "Brillo placa cerca del aggro"
L["Edit Tracked Auras"] = "Editar auras seguidas"
L["Edit Tracked CC"] = "Editar CC seguidos"
L["Enemy Buff Filter"] = "Filtro benef. enem."
L["Enemy Buff Filter Settings"] = "Ajustes filtro benef. enem."
L["Show Glow"] = "Mostrar brillo"

