L["Recolors the frame border in the dispel type color while a debuff of that type is shown."] = "Cambia el color del borde del marco al color del tipo de disipación mientras se muestra un perjuicio de ese tipo."
L["Highest group size that uses this layout."] = "Tamaño de grupo más grande que usa esta disposición."
