L["Group size at which this layout takes over from the 30 Man layout."] = "Tamaño de grupo a partir del cual esta disposición sustituye a la de 30 jugadores."
L["FrameSort sets the order while Sort By is FrameSort."] = "FrameSort decide el orden cuando Ordenar por está en FrameSort."
