L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n"] = "EllesmereUI no ha podido guardar este cambio en tu diseño del modo edición, así que hay que ponerlo a mano. El gestor de reutilizaciones tiene que estar desactivado mientras lo haces, porque oculta los visores de reutilizaciones de Blizzard y un visor oculto no se puede seleccionar en el modo edición.\n\n"
L["This will keep appearing each login until the layout is correct."] = "Esto seguirá saliendo cada vez que entres hasta que el diseño esté bien."
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "Esta barra tiene un desplazamiento adicional (X %1$s, Y %2$s) en sus opciones. El modo desbloqueo muestra la posición base; el desplazamiento se vuelve a aplicar al salir."
L["Show a tracked buff in this slot while it is active."] = "Muestra en este hueco un beneficio seguido mientras esté activo."
L["You're on this spec."] = "Estás en esta especialización."
L["This spec doesn't have this spell."] = "Esta especialización no tiene este hechizo."
L["This is the spec you're syncing from -- it's always included."] = "Es la especialización desde la que sincronizas: siempre está incluida."
L["How extra columns grow when the second column appears or disappears. Grow Right keeps the left column in place, Grow Left keeps the right column in place, Grow Centered keeps the bar centered."] = "Cómo crecen las columnas extra cuando aparece o desaparece la segunda columna. Crecer a la derecha deja la columna izquierda en su sitio, Crecer a la izquierda deja la columna derecha en su sitio y Crecer centrado mantiene la barra centrada."
L["Not available while a spell on this bar uses a Cooldown State Shift Icons setting"] = "No disponible mientras un hechizo de esta barra use el ajuste de estado de reutilización Mover iconos"
L["When the current spec has no bars in this group, keeps elements anchored to the group in place and shifts them up or down by one bar height (tune with the cog's Extra Y Offset) to cover its empty slot."] = "Cuando la especialización actual no tiene barras en este grupo, deja en su sitio los elementos anclados al grupo y los mueve arriba o abajo la altura de una barra (ajústalo con Desplazamiento Y extra en el engranaje) para tapar el hueco vacío."
L["This replaces %d existing value(s) for this setting across your specs."] = "Esto sustituye %d valor(es) que ya tenía este ajuste en tus especializaciones."
L["This replaces %d existing value(s) for this setting on this bar."] = "Esto sustituye %d valor(es) que ya tenía este ajuste en esta barra."
