L["EllesmereUI has updated your CDM Edit Mode settings to ensure cooldown tracking works correctly.\n\nA UI reload is required for the changes to take effect."] = "EllesmereUI ha actualizado los ajustes del modo edición del CDM para que el seguimiento de reutilizaciones funcione bien.\n\nHay que recargar la interfaz para aplicar los cambios."
