L["Cannot work for pet/totem summon bars (Call Dreadstalkers, etc.) -- they expose no readable timer."] = "No funciona en las barras de invocaciones de mascotas o tótems (Llamar a terracechadores, etc.): no dan un temporizador que se pueda leer."
L["Change buff"] = "Cambiar beneficio"
L["Copies this custom spell and its settings to the same bar on the specs you pick. Specs that already have it are skipped."] = "Copia este hechizo personalizado y sus ajustes en la misma barra de las especializaciones que elijas. Se saltan las que ya lo tienen."
L["Decimal Threshold"] = "Umbral de decimales"
L["Decimals"] = "Decimales"
