L["Missing Buffs?"] = "¿Faltan beneficios?"
L["Remove from All"] = "Quitar de todas"
L["Rename Preset"] = "Cambiar el nombre de la plantilla"
L["Seconds left when threshold text starts (0 = off)"] = "Segundos restantes cuando empieza el texto del umbral (0 = desactivado)"
L["Share this group's name, layout, and position across all specs."] = "Comparte el nombre, la disposición y la posición de este grupo en todas las especializaciones."
L["Thickness of the Pixel Glow applied to this bar's buff icons."] = "Grosor del brillo de píxeles de los iconos de beneficios de esta barra."
L["This bar will always be attached to your current target's nameplate"] = "Esta barra siempre estará unida a la placa de nombre de tu objetivo actual"
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Spells you added yourself (presets, custom IDs and racials) are kept. Continue?"] = "Esto restablece todos los hechizos asignados a las barras predeterminadas de la especialización actual para que coincidan con el diseño del CDM de Blizzard. Se conservan los hechizos que añadiste tú (plantillas, ID personalizados y raciales). ¿Continuar?"
L["Tracking Bars: %1$s"] = "Barras de seguimiento: %1$s"
L["Uncheck a spec to keep it. Confirm removes this custom spell and its settings from the checked specs."] = "Desmarca una especialización para conservarla. Al confirmar, se quita este hechizo personalizado y sus ajustes de las especializaciones marcadas."
L["Uncheck a spec to remove it from the sync. Removed specs keep their current trinkets, pots, racials & buff presets."] = "Desmarca una especialización para quitarla de la sincronización. Las que quites mantienen sus abalorios, pociones, raciales y plantillas de beneficios actuales."
L["Vertical bars fill upward; flipping a grouped bar flips its whole group."] = "Las barras verticales se llenan hacia arriba; si das la vuelta a una barra agrupada, se da la vuelta a todo su grupo."
