L["Maximum of 5 thresholds."] = "Máximo de 5 umbrales."
L["Slot ID"] = "ID del hueco"
L["Syncing generic CDs/buffs across %d specs. Icon order is not synced -- each spec keeps its own arrangement."] = "Sincronizando reutilizaciones y beneficios genéricos en %d especializaciones. El orden de los iconos no se sincroniza: cada especialización mantiene el suyo."
L["The single stack threshold is off while Multiple Thresholds is on."] = "El umbral de acumulaciones único está desactivado mientras Varios umbrales está activado."
L["This setting's active Apply to Bar (All Specs) value will be replaced."] = "Se sustituirá el valor activo de Aplicar a la barra (todas las especializaciones) de este ajuste."
L["This setting's active Apply to Bar value will be replaced."] = "Se sustituirá el valor activo de Aplicar a la barra de este ajuste."
L["Use Multiple Thresholds"] = "Usar varios umbrales"
L["Fill Up"] = "Llenar hacia arriba"
L["Mirrors which end of the bar the fill is anchored to. It does not change the direction the bar travels: use Fill Up for that."] = "Cambia el extremo de la barra desde el que sale el relleno. No cambia la dirección en la que avanza la barra: para eso, usa Llenar hacia arriba."
L["Fills the bar as the cooldown recovers instead of draining it as the cooldown runs down."] = "Llena la barra según se recupera la reutilización en lugar de vaciarla según pasa."
L["Adjust Crop"] = "Ajustar recorte"
L["How much is trimmed from the icon's top and bottom, as a percentage per side. 10% is the classic cropped look."] = "Cuánto se recorta arriba y abajo del icono, en porcentaje por cada lado. Un 10% imita el aspecto recortado clásico."
