L["Adds a strip down the left edge of a loot toast in the item's quality color. The flat skin drops Blizzard's quality ring around the icon, so this puts that rarity cue back."] = "Añade una franja en el borde izquierdo del aviso de botín con el color de la calidad del objeto. El aspecto plano quita el anillo de calidad de Blizzard alrededor del icono, así que esto devuelve esa pista de rareza."
L["Also show the strip on gold toasts, in the header's gold color. Gold has no rarity to signal, so this is off by default."] = "Muestra la franja también en los avisos de oro, con el color dorado del título. El oro no tiene rareza que indicar, así que está desactivado de forma predeterminada."
