L["Enter a new name:"] = "Escribe un nombre nuevo:"
L["Enter amount in gold:"] = "Escribe la cantidad de oro:"
L["OneBag sorting will physically reorganize items in your bags. The changes persist even if you disable EllesmereUI Bags."] = "El orden de OneBag cambia de sitio de verdad los objetos de tus bolsas. Los cambios se mantienen aunque desactives las bolsas de EllesmereUI."
L["Main Bags (%d / %d)"] = "Bolsas principales (%d / %d)"
L["Reagent Bag (%d / %d)"] = "Bolsa de componentes (%d / %d)"
L["Bag %d"] = "Bolsa %d"
L["Crops the border of every item icon in bags and bank. 0 shows the full icon."] = "Recorta el borde de todos los iconos de objetos de las bolsas y el banco. Con 0 se ve el icono entero."
L["Edit Tab Settings"] = "Editar los ajustes de la pestaña"
L["Show BoE / Warbound Text"] = "Ver texto BoE/banda"
L["Sort Options"] = "Opciones de orden"
L["Sort to Bottom"] = "Ordenar hacia abajo"
L["Ungroup %1$s"] = "Separar %1$s"
L["Bank (%1$d / %2$d)"] = "Banco (%1$d / %2$d)"
L["Warband Bank (%1$d / %2$d)"] = "Banco de la banda guerrera (%1$d / %2$d)"
L["Sorting normally packs your items into the first free slots, at the top of the grid. Turn this on to pack them into the last slots instead, so the empty slots end up at the top. The item order itself does not change. This affects the OneBag, MultiBag and bank views -- category views fill their own grid with no gaps, so there is nothing to move. MultiBag and the bank use Blizzard's own sorting, so while this is on it also flips Blizzard's cleanup direction; turning it back off restores the direction you had."] = "Al ordenar, los objetos van normalmente a los primeros huecos libres, arriba de la cuadrícula. Activa esto para que vayan a los últimos, y así los huecos vacíos quedan arriba. El orden de los objetos no cambia. Afecta a las vistas OneBag, MultiBag y banco (las vistas por categoría llenan su propia cuadrícula sin huecos, así que no hay nada que mover). MultiBag y el banco usan el orden de Blizzard, así que mientras esté activado también invierte el sentido de la limpieza de Blizzard; al desactivarlo vuelve el sentido que tenías."
L["Containers received from the mailbox are held until you close the mailbox, so opening them cannot collide with mail still delivering items."] = "Los contenedores que llegan del buzón se guardan hasta que cierras el buzón, para que abrirlos no choque con el correo que aún está entregando objetos."
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags.\n\nContainers received from the mailbox are held until you close the mailbox, so opening them cannot collide with mail still delivering items."] = "Abre automáticamente las bolsas, cajas y paquetes cuando entran en tus bolsas.\n\nLos contenedores que llegan del buzón se guardan hasta que cierras el buzón, para que abrirlos no choque con el correo que aún está entregando objetos."
L["1H"] = "1M"
L["2H"] = "2M"
L["OH"] = "MI"
L["Ranged"] = "A distancia"
L["Cosmetic"] = "Cosmético"
L["In The Armory and the Weapons / Trinkets, Armor, and Item Set Gear category views, group items under equip-slot sub-headers (Head, Shoulders, Chest, Cosmetic, ...). Does not add sidebar views."] = "En El Arsenal y en las vistas de categoría Armas / abalorios, Armadura y Equipo de conjunto, agrupa los objetos bajo subtítulos por hueco (cabeza, hombros, torso, cosmético...). No añade vistas a la barra lateral."
L["Set Name Text Options"] = "Opciones nombre conjunto"
L["Show copies of the same item in separate bag slots as one icon or row, with their counts added together. Gear is never merged, and OneBag and MultiBag always show every slot. Merging pauses while the mail, trade, auction house, vendor, bank or guild bank window is open."] = "Muestra las copias del mismo objeto que están en huecos distintos como un solo icono o fila, con sus cantidades sumadas. El equipo nunca se junta, y OneBag y MultiBag siempre muestran todos los huecos. Se deja de juntar mientras están abiertas las ventanas de correo, comercio, casa de subastas, mercader, banco o banco de hermandad."
L["Split by Type"] = "Separar por tipo"

