L["Hides the master header and its minimize button at the top of the tracker."] = "Oculta el título general y su botón de minimizar de la parte de arriba del seguimiento."
L["Always: hide the tracker the whole time you are in a raid.\nBoss Combat: keep it visible and only hide during boss encounters."] = "Siempre: oculta el seguimiento todo el tiempo que estás en una banda.\nCombate con jefes: lo deja visible y solo lo oculta en los encuentros con jefes."
