L["Show Blizzard's native quest type icons/buttons on the right instead of EllesmereUI's custom icons. Requires a UI reload."] = "Muestra a la derecha los iconos y botones de tipo de misión propios de Blizzard en lugar de los iconos de EllesmereUI. Hay que recargar la interfaz."
