L["EllesmereUI restyles Blizzard's chat bubbles and turns on the switches it needs. Party and Raid keep your current setting, and everything is put back when you turn this off."] = "EllesmereUI cambia el aspecto de los bocadillos de chat de Blizzard y activa los interruptores que necesita. Grupo y Banda mantienen tu ajuste actual, y todo vuelve a como estaba al desactivarlo."
