L["Hides the resize handle on the main chat frame, preventing accidental resizing."] = "Oculta el tirador para cambiar el tamaño de la ventana de chat principal, para que no lo cambies sin querer."
L["Saves the most recent lines per chat tab (per character), except Blizzard's combat log window, so they reappear after /reload or relog. Stored separately from layout profiles."] = "Guarda las últimas líneas de cada pestaña del chat (por personaje), menos la ventana del registro de combate de Blizzard, para que vuelvan a salir tras /reload o al volver a entrar. Se guardan aparte de los perfiles de disposición."
L["Scroll to Bottom"] = "Ir abajo del todo"
