L["When enabled, Shift+Click any sidebar icon to drag it to a custom position."] = "Si lo activas, haz Mayús + clic en cualquier icono de la barra lateral para arrastrarlo a donde quieras."
L["Texture drawn over the chat background color."] = "Textura que se dibuja sobre el color de fondo del chat."
L["Texture drawn over the tab background colors."] = "Textura que se dibuja sobre los colores de fondo de las pestañas."
L["Gives the selected tab its own border color."] = "Da a la pestaña elegida su propio color de borde."
L["Places the tabs inside one continuous chat panel background, including the sidebar when visible."] = "Pone las pestañas dentro de un mismo fondo continuo del panel del chat, también la barra lateral cuando se ve."
L["Outline mode changed. A UI reload is needed to apply."] = "Modo de contorno cambiado. Hay que recargar la interfaz para aplicarlo."
L["Tab Background"] = "Fondo de las pestañas"
