L["Shortened Channel Names"] = "Nombres de canal cortos"
L["Colors group and raid member names by their class when they appear in the text of Say, Yell, Party, and Raid messages."] = "Pone el color de clase a los nombres de los miembros del grupo y de la banda cuando salen en el texto de los mensajes de decir, gritar, grupo y banda."
L["For tabs outside the chat panel, uses the chat panel's border style and color instead of separate tab border settings."] = "En las pestañas que están fuera del panel del chat, usa el estilo y el color del borde del panel en lugar de los ajustes de borde propios de las pestañas."
L["Timestamp All Messages"] = "Hora en todos los mensajes"
