L["The active override's Buff Manager is bound to the open page. Leave the Buff Manager tab to switch overrides."] = "El gestor de beneficios del ajuste propio activo está unido a la página abierta. Sal de la pestaña del gestor de beneficios para cambiar de ajuste propio."
L["This condition is coming in a future update."] = "Esta condición llegará en una próxima actualización."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Esta condición no está activa ahora. Cumple antes una de sus condiciones (por ejemplo, entra en la mazmorra) para colocar la disposición en su sitio real."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "El gestor de beneficios personalizado de este grupo solo se puede activar o editar mientras juegas con una de sus especializaciones."
L["This module is excluded from Spec Overrides."] = "Este módulo no entra en los ajustes por especialización."
