L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Esto crea un modo desbloqueo totalmente propio para este grupo condicional. Los cambios en tu modo desbloqueo predeterminado ya no le afectarán."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Esto crea un modo desbloqueo totalmente propio para este grupo de ajustes. Los cambios en tu modo desbloqueo predeterminado ya no afectarán a estas especializaciones."
