L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "Tu especialización actual tiene su propio modo desbloqueo personalizado, así que los modos desbloqueo condicionales nunca se le aplican. Cambia a una especialización sin él para personalizar esto."
