L["Rescue tool for a profile built inside an override: the selected group's settings and layouts become this profile's own baseline, then ALL spec override groups are deleted. Conditional overrides are not affected."] = "Herramienta de rescate para un perfil creado dentro de un ajuste propio: los ajustes y las disposiciones del grupo elegido pasan a ser la base de este perfil y luego se borran TODOS los grupos de ajustes por especialización. Los ajustes condicionales no cambian."
