L["Include your Blizzard Skins+ settings from the Window Skins and Tooltips & Menus tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "Incluye tus ajustes de Blizzard Skins+ de las pestañas Aspecto de las ventanas y Descripciones y menús. Son para toda la cuenta: si quien importa lo acepta, sobrescriben sus ajustes en TODOS sus perfiles."
L["Override to Promote"] = "Ajuste propio que pasar al perfil"
L["Overwrite Window & Tooltip Settings?"] = "¿Sobrescribir los ajustes de ventanas y descripciones?"
L["Presets"] = "Plantillas"
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Esto no se puede deshacer. Plantéate exportar antes este perfil como copia de seguridad."
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Esta exportación incluye ajustes comunes a todos los perfiles que sobrescribirán los de quien la importe, como Calidad de vida, Hovercast y más, que normalmente no se comparten con los perfiles normales. NO SE RECOMIENDA para compartir perfiles en público."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Esto sobrescribe para siempre los ajustes de este perfil con el ajuste propio «%s»: sus ajustes guardados y sus disposiciones del modo desbloqueo y del gestor de beneficios (si los tiene) pasan a ser la base del perfil para todas las especializaciones. Después se borran TODOS los grupos de ajustes por especialización de este perfil y se recarga la interfaz. Los ajustes condicionales no cambian."
L["Type \"%s\" to enable:"] = "Escribe «%s» para activarlo:"
