L["Match Scale"] = "Igualar la escala"
L["Keep Mine"] = "Mantener la mía"
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Este perfil se hizo con una escala de interfaz del %1$d%%; la tuya es del %2$d%%. ¿Cambiar tu escala de interfaz para que coincida con el perfil importado? Todos los perfiles se verán con esta escala, porque la escala de la interfaz no va por perfil, pero puedes volver a tu valor original cuando quieras."
L["Include Overrides"] = "Incluir los ajustes propios"
L["Import the sharer's complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. This replaces ALL of your own overrides. Off = keep yours untouched."] = "Importa todos los ajustes propios de quien comparte: los valores por especialización y condicionales, los grupos, sus disposiciones del modo desbloqueo y los ajustes del gestor de beneficios. Sustituye TODOS tus ajustes propios. Desactivado = no tocar los tuyos."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Este texto de perfil no trae ningún ajuste de aspecto de ventanas y descripciones."
L["Could not build the export string."] = "No se ha podido crear el texto de exportación."
L["Export Failed"] = "Error al exportar"
L["Import & Reload"] = "Importar y recargar"
L["Import Full Account Data"] = "Importar todos los datos de la cuenta"
L["This cannot be undone. Export your own profile as a backup first."] = "Esto no se puede deshacer. Exporta antes tu perfil como copia de seguridad."
L["This profile string does not carry any override data."] = "Este texto de perfil no trae ningún ajuste propio."
L["This will replace YOUR Blizzard Skins+ settings (the Window Skins and Tooltips & Menus tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Esto sustituirá TUS ajustes de Blizzard Skins+ (las pestañas Aspecto de las ventanas y Descripciones y menús) por los de quien comparte, en TODOS tus perfiles. Después no podrás recuperar tus ajustes actuales de esas dos pestañas."
L["Window skins changed for this profile. A UI reload is needed to apply them."] = "Aspecto de las ventanas cambiado en este perfil. Hay que recargar la interfaz para aplicarlo."
L["\"%1$s\" was saved but cannot be loaded because this spec has an assigned profile."] = "«%1$s» se ha guardado, pero no se puede cargar porque esta especialización tiene un perfil asignado."

