L["Abbreviate Amount"] = "Abreviar la cantidad"
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Muestra las cantidades grandes con K/M (284,208g pasa a 284.2Kg) en lugar del número entero. La descripción siempre muestra la cantidad exacta."
L["Show Description"] = "Mostrar descripción"
L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Muestra en la descripción el texto que explica la moneda. Desactívalo para una descripción compacta con solo el nombre y la cantidad."
