L["Replaces the spendable amount with the crests you have earned this season, out of the season cap. The tooltip lists both numbers side by side."] = "Sustituye la cantidad que puedes gastar por los blasones que has ganado esta temporada, sobre el límite de la temporada. La descripción muestra los dos números juntos."
L["Show Season Progress"] = "Mostrar el progreso de la temporada"
L["Drops crests you own none of, keeping the block short early in a season. They stay listed in the tooltip."] = "Quita los blasones de los que no tienes ninguno, para que el bloque sea corto al principio de la temporada. Siguen saliendo en la descripción."
L["Hide Empty Crests"] = "Ocultar los blasones vacíos"
