L["How many decimal places the number carries."] = "Cuántos decimales lleva el número."
L["not loaded"] = "sin cargar"
L["Characters"] = "Personajes"
L["Which audio channel the block's volume bar adjusts."] = "Qué canal de sonido ajusta la barra de volumen del bloque."
L["Automatic follows the zone name. Manual holds the block at a fixed width and clips longer names, so it never shifts the blocks beside it."] = "Automático sigue el nombre de la zona. Manual deja el bloque con una anchura fija y corta los nombres más largos, para que nunca mueva los bloques de al lado."
L["Max Width"] = "Anchura máxima"
L["How wide the block stays, whatever the zone is called."] = "Qué ancho tiene el bloque, se llame como se llame la zona."
L["How precise the coordinates read. More decimals make the block wider."] = "Qué precisión tienen las coordenadas. Más decimales hacen el bloque más ancho."
L["Show Tooltip Data"] = "Datos en descripción"
L["Which sections the gold tooltip shows."] = "Qué secciones muestra la descripción del oro."
L["Which latency to show: home, world, or both side by side."] = "Qué latencia mostrar: casa, mundo o las dos juntas."
L["Shows a house or globe icon marking which latency each value is."] = "Muestra un icono de casa o de globo para saber qué latencia es cada valor."
L["Which hearthstone the left click uses. Random Hearthstone picks a random owned variant each cast. Right click always rolls a random one."] = "Qué piedra de hogar usa el clic izquierdo. Piedra de hogar al azar elige una variante tuya al azar cada vez. El clic derecho siempre elige una al azar."
L["Background texture for this bar, tinted by the bar's color and opacity."] = "Textura de fondo de esta barra, teñida con el color y la opacidad de la barra."
