L["Shows the audio icon next to the volume bar."] = "Muestra el icono de sonido junto a la barra de volumen."
L["Shows the profession icons next to the text."] = "Muestra los iconos de las profesiones junto al texto."
L["Uses Blizzard's coin textures instead of the letter suffixes."] = "Usa las texturas de monedas de Blizzard en lugar de las letras."
