L["ADDITIONAL BAR OFFSET"] = "DESPLAZAMIENTO ADICIONAL DE LA BARRA"
L["Extra horizontal shift stacked on top of this bar's normal position. Unlock mode shows the base position; the offset re-applies when you exit."] = "Desplazamiento horizontal extra que se suma a la posición normal de esta barra. El modo desbloqueo muestra la posición base; el desplazamiento se vuelve a aplicar al salir."
L["Extra vertical shift stacked on top of this bar's normal position. Unlock mode shows the base position; the offset re-applies when you exit."] = "Desplazamiento vertical extra que se suma a la posición normal de esta barra. El modo desbloqueo muestra la posición base; el desplazamiento se vuelve a aplicar al salir."
L["All Buffs or Has Duration is selected, so every buff already shows. Use the red Hide box to exclude these instead."] = "Está elegido Todos los beneficios o Con duración, así que ya se muestran todos. Usa la casilla roja Ocultar para excluir estos."
L["Copy from %1$s Buff Manager"] = "Copiar del gestor de beneficios de %1$s"
L["Copy from main Buff Manager"] = "Copiar del gestor de beneficios principal"
L["Create Custom Buff Manager"] = "Crear gestor de beneficios personalizado"
L["Only show this bar while the tracked buff/cooldown is active. Unchecked keeps an empty bar on screen at all times."] = "Muestra esta barra solo mientras el beneficio o la reutilización seguidos estén activos. Si lo desmarcas, la barra vacía se queda siempre en pantalla."
L["Precise Below (minutes, 0 = off)"] = "Exacto por debajo (min, 0 = no)"
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Esto crea un gestor de beneficios totalmente propio para este grupo condicional. Los cambios en tu gestor de beneficios predeterminado ya no le afectarán."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Esto crea un gestor de beneficios totalmente propio para este grupo de ajustes. Los cambios en tu gestor de beneficios predeterminado ya no afectarán a estas especializaciones."
L["%1$s Specialization Ability"] = "Facultad de especialización de %1$s"
L["Dashed"] = "Discontinuo"
L["Indicators added here show on every spec in this group. The Base Icons grid lives in %1$s."] = "Los indicadores que añadas aquí se ven en todas las especializaciones de este grupo. La cuadrícula de iconos base está en %1$s."
L["No indicator selected"] = "Ningún indicador elegido"
L["Start From"] = "Empezar desde"
L["This override has no indicators for this spec, so nothing shows here until you add some."] = "Este ajuste propio no tiene indicadores para esta especialización, así que aquí no sale nada hasta que añadas alguno."
L["Hide Loot Rolls Window"] = "Ocultar tiradas botín"
L["Hides Blizzard's \"Loot Rolls\" window -- the running list of dropped items showing who rolled what and who won. Use the cog to let it appear briefly and close itself instead. The Need/Greed roll popups themselves are not affected."] = "Oculta la ventana «Tiradas de botín» de Blizzard, la lista de objetos que han caído con quién ha tirado qué y quién ha ganado. Usa el engranaje para que salga un momento y se cierre automáticamente. Las ventanas de tirada de necesidad/codicia no cambian."
L["Loot Rolls Window Settings"] = "Ajustes ventana tiradas"
L["Hide Completely"] = "Ocultar del todo"
L["Close After Delay"] = "Cerrar tras un tiempo"
L["Close After (sec)"] = "Cerrar tras (s)"
L["A spec override owns this setting, so this conditional value never applies outside an editing session. Remove the spec override to let it through."] = "Un ajuste por especialización manda sobre este ajuste, así que este valor condicional nunca se aplica fuera de la edición. Quita el ajuste por especialización para que se aplique."
L["Changes here edit the shared default; overrides keep their own values."] = "Lo que cambies aquí edita lo predeterminado compartido; los ajustes propios mantienen sus valores."
L["Default Preset"] = "Plantilla predeterminada"
L["Empty Preset"] = "Plantilla vacía"
L["Hide when Skyriding Mounted"] = "Ocultar en montura de surcacielos"
L["Overridden by:"] = "Cambiado por:"
L["Support Team"] = "Equipo de asistencia"
L["The panel the minimap Group Finder eye shows on hover: queue titles, role icons and counts, and time in queue."] = "El panel que muestra el ojo del buscador de grupos del minimapa al pasar el ratón: nombres de las colas, iconos y cantidades de funciones y tiempo en cola."
L["Delve Tier Picker"] = "Nivel profundidad"
L["The delve difficulty window: tier dropdown, reward list and Enter button. The Map Properties row is left stock -- it is a Blizzard widget display and is not safe to restyle."] = "La ventana de dificultad de las profundidades: lista de niveles, lista de recompensas y botón Entrar. La fila de propiedades del mapa se deja como está: es un elemento de Blizzard y no es seguro cambiar su aspecto."
L["Choice Windows"] = "Ventanas de elección"
L["Weekly and event choice windows such as Abundance harvests and \"how will you aid...\" pickers: option plates, headers, reward icons and buttons. Option artwork stays."] = "Ventanas de elección semanales y de eventos, como las cosechas de Abundancia y las de «¿cómo ayudarás...?»: placas de opciones, títulos, iconos de recompensa y botones. El dibujo de las opciones se queda igual."
L["Trade"] = "Comercio"
L["The player-to-player trade window: frame, both item columns, the enchant slots, money rows and buttons. Item icons are squared and carry a rarity border. Both portraits are removed, as on every other window."] = "La ventana de comercio entre jugadores: marco, las dos columnas de objetos, los huecos de encantamiento, las filas de dinero y los botones. Los iconos de los objetos son cuadrados y llevan un borde de rareza. Se quitan los dos retratos, como en todas las demás ventanas."
L["Armory Slot Group Options"] = "Opciones grupos Arsenal"
L["Compact Slot Groups"] = "Grupos de huecos compactos"
L["Frame Footer"] = "Pie del marco"
L["Place smaller Armory slot groups beside each other and fill the unused end of each row with empty-slot blocks. Large groups still use full rows."] = "Pone los grupos de huecos pequeños de El Arsenal uno al lado de otro y llena el final de cada fila con huecos vacíos. Los grupos grandes siguen usando filas enteras."
L["Prefix the durability percent with \"Durability:\"."] = "Pone «Durabilidad:» delante del porcentaje de durabilidad."
L["Show Item Durability"] = "Ver durabilidad"
L["Show Label"] = "Mostrar etiqueta"
L["Show total equipped durability above the character model, colored from green to red."] = "Muestra la durabilidad total del equipo puesto encima del modelo del personaje, con color de verde a rojo."
L["Stats Header"] = "Título de estadísticas"
L["Reskin Widget Bars"] = "Aspecto indicadores"
L["Reskin Extra Action Buttons"] = "Aspecto botones extra"
L["Show Set Name on Gear"] = "Ver nombre de conjunto"
L["Display the equipment set's name at the bottom of bag items that belong to one of your equipment sets."] = "Muestra el nombre del conjunto de equipamiento abajo de los objetos de las bolsas que son de uno de tus conjuntos."
