L["Party Frames in Small Raids"] = "Marcos de grupo en bandas pequeñas"
L["Shows the ping mark on a member's frame when someone pings them (needs Blizzard's Show Pings on Raid Frames setting on)."] = "Muestra la marca de aviso en el marco de un miembro cuando alguien le hace un aviso (necesita el ajuste de Blizzard Mostrar avisos en los marcos de banda activado)."
L["Only show debuffs whose full duration is at most this many seconds. Combines with the filters; Unlimited applies no cap."] = "Solo muestra los perjuicios cuya duración total es como mucho estos segundos. Se combina con los filtros; Sin límite no pone tope."
L["Debuffs caused by any player or player pet. The opposite of Non-Player Auras; checking one clears the other."] = "Perjuicios causados por cualquier jugador o su mascota. Lo contrario de Auras de no jugadores; al marcar uno se desmarca el otro."
L["Debuffs applied by you or your pet."] = "Perjuicios que aplicas tú o tu mascota."
L["Debuffs with the Magic dispel type."] = "Perjuicios de tipo de disipación Magia."
