L["Debuffs with the Disease dispel type."] = "Perjuicios de tipo de disipación Enfermedad."
L["Debuffs with the Bleed dispel type."] = "Perjuicios de tipo de disipación Sangrado."
L["Debuffs your own class is able to apply."] = "Perjuicios que puede aplicar tu propia clase."
L["In raid groups under 10 players, show group 1 as party frames and hide everyone else."] = "En grupos de banda de menos de 10 jugadores, muestra el grupo 1 como marcos de grupo y oculta a los demás."
L["Skyriding (Airborne)"] = "Surcacielos (en el aire)"
L["Skyriding Mount"] = "Montura de surcacielos"
L["Mounted"] = "Con montura"
L["Enemy Target"] = "Objetivo enemigo"
L["While you are inside a house or plot."] = "Mientras estás dentro de una casa o una parcela."
L["A target you can attack."] = "Un objetivo al que puedes atacar."
L["Hide while this condition is true"] = "Ocultar mientras se cumpla esta condición"
L["Reveal on hover only. Combines with the conditions below: hover-reveals while they all pass, stays hidden while any fails."] = "Mostrar solo al pasar el ratón. Se combina con las condiciones de abajo: se muestra al pasar el ratón mientras se cumplen todas y se queda oculto mientras falle alguna."
L["Only while AIRBORNE on a glide-capable mount or flight form. For the mount itself, ground included, use Skyriding Mount."] = "Solo mientras estás EN EL AIRE en una montura que puede planear o en forma de vuelo. Para la montura en sí, también en el suelo, usa Montura de surcacielos."
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "Mientras vas en una montura que puede planear, también en el suelo, donde Blizzard muestra su indicador de vigor. Surcacielos (en el aire) además exige que estés volando."
L["Dungeons, raids, scenarios, arenas and battlegrounds. Garrisons do not count."] = "Mazmorras, bandas, gestas, arenas y campos de batalla. Las ciudadelas no cuentan."
L["Druid travel, aquatic and flight forms count as mounted."] = "Las formas de viaje, acuática y de vuelo del druida cuentan como montura."
L["Five-player dungeons, Mythic+ included. Delves, raids and scenarios do not count."] = "Mazmorras de cinco jugadores, también mítica+. Las profundidades, las bandas y las gestas no cuentan."
L["While Party Mode is active. Party Mode can start in combat (Bloodlust); secure elements such as action bars then keep their current visibility until combat ends."] = "Mientras está activo el modo fiesta. El modo fiesta puede empezar en combate (Ansia de sangre); los elementos protegidos, como las barras de acción, mantienen entonces su visibilidad hasta que acaba el combate."
L["Glow Ring"] = "Anillo de brillo"
L["Button Overlay"] = "Capa sobre el botón"
L["Ring + Overlay"] = "Anillo + capa"
L["How Blizzard's next-spell suggestion is drawn on the button. Button Overlay replaces the blue ring with a flat tint, leaving the button edge free for the proc glow."] = "Cómo se dibuja en el botón la sugerencia de Blizzard del siguiente hechizo. Capa sobre el botón cambia el anillo azul por un tinte plano y deja libre el borde del botón para el brillo de proc."
L["Opacity of the Button Overlay tint."] = "Opacidad del tinte de Capa sobre el botón."
L["Button Overlay Color"] = "Color de la capa sobre el botón"
L["This option requires the Button Overlay style"] = "Esta opción necesita el estilo Capa sobre el botón"
L["Moves the blue Assisted Highlight ring outward (or inward at negative values) so it no longer overlaps the proc glow on the same button. With Ring + Overlay the tint resizes along with it, so the two stay flush."] = "Mueve hacia fuera (o hacia dentro con valores negativos) el anillo azul de Ayuda resaltada para que no tape el brillo de proc del mismo botón. Con Anillo + capa el tinte cambia de tamaño con él, para que vayan a ras."
L["Fit Ring to Cropped Buttons"] = "Anillo a botones recortados"
L["On Cropped bars, shapes the Assisted Highlight ring to the button instead of a square."] = "En las barras recortadas, da al anillo de Ayuda resaltada la forma del botón en lugar de un cuadrado."
L["Hide Border"] = "Ocultar el borde"
L["Only Dispellable"] = "Solo disipables"
L["Color by Type"] = "Color según el tipo"
L["This option requires Blizzard's Assisted Highlight to be enabled"] = "Esta opción necesita que la Ayuda resaltada de Blizzard esté activada"
L["Assisted Highlight"] = "Ayuda resaltada"
L["Assisted Highlight Outset"] = "Separación de la Ayuda resaltada"
L["This option requires a style that draws the glow ring"] = "Esta opción necesita un estilo que dibuje el anillo de brillo"
L["Queue Timer Style"] = "Estilo del tiempo en cola"
L["Text Offset Y"] = "Desplazamiento Y del texto"
L["Not Skyriding (Airborne)"] = "Sin surcacielos (en el aire)"
L["Countdown Text Color"] = "Color del texto de la cuenta atrás"
L["Resting"] = "Descansando"
L["In Vehicle"] = "En un vehículo"
L["While seated in a vehicle."] = "Mientras vas sentado en un vehículo."
L["While resting, in a city or at an inn."] = "Mientras descansas, en una ciudad o en una posada."
L["Moves the countdown number up or down relative to the bar."] = "Mueve el número de la cuenta atrás arriba o abajo respecto a la barra."
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Este elemento se muestra en cuanto se cumple UNA condición de Mostrar. Ocultar significa lo mismo en los dos modos: un Ocultar marcado siempre oculta, en todas las filas."
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "Lo contrario exacto de Surcacielos (en el aire): todo lo que no sea estar en el aire en una montura que puede planear o en forma de vuelo, también estar en el suelo."
L["Hide Trailing Zeros"] = "Ocultar los ceros finales"
L["Frame Source & Visibility"] = "Origen y visibilidad del marco"
L["Show When Health Missing"] = "Mostrar cuando falta salud"
L["Shows the frame while this unit is below full health; while enabled, a frame hidden by its visibility setting can still be clicked."] = "Muestra el marco mientras a esta unidad le falta salud; si está activado, se puede hacer clic en un marco oculto por su ajuste de visibilidad."
L["Change health visibility out of combat"] = "Cambiar la visibilidad de la salud fuera de combate"
L["the Frame Source to be EllesmereUI"] = "que el origen del marco sea EllesmereUI"
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Esto sobrescribe los ajustes actuales de este marco. La posición, la visibilidad y si está activado no cambian."
L["Dark Mode drives a Dark Mode override condition and can't be changed while editing an override"] = "El modo oscuro controla una condición de ajuste propio del modo oscuro y no se puede cambiar mientras editas un ajuste propio"
L["Apply Border Size to all Frames"] = "Aplicar el tamaño del borde a todos los marcos"
L["Focus Tracked Auras"] = "Auras seguidas del foco"
L["Boss Tracked Auras"] = "Auras seguidas de los jefes"
L["Tracked Auras"] = "Auras seguidas"
L["Included debuffs show in addition to your Debuff Filter selection (unless it is set to Only Tracked Auras)."] = "Los perjuicios incluidos se muestran además de lo que elijas en Filtro de perjuicios (salvo que esté en Solo auras seguidas)."
L["You are displaying NO debuffs at all."] = "No estás mostrando NINGÚN perjuicio."
L["You are displaying NO buffs at all."] = "No estás mostrando NINGÚN beneficio."
L["Blizz Colored Target Header"] = "Título objetivo color Blizz"
L["Colors the strip behind the target's name by its reaction."] = "Pone color a la franja de detrás del nombre del objetivo según su reacción."
L["Custom Colors"] = "Colores personalizados"
L["Class Reactive"] = "Reactivo a la clase"
L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Pone color a la barra de salud según la salud que queda, en lugar de un color plano. Clásico va del verde con la salud llena al amarillo y al rojo cuando está vacía. Colores personalizados mezcla los tres colores de esta fila: llena (100%), a la mitad (50%) y vacía (0%). Reactivo a la clase muestra el color de clase con la salud llena y va pasando a los colores de la mitad y de vacía según la unidad recibe daño. Desactivado deja mandar a los colores planos de Color de relleno; en todos los casos el Degradado de abajo se sigue aplicando, empezando por el color que elija esto."
L["Level Text: Difficulty Color"] = "Texto de nivel: color de dificultad"
L["Colors level text by difficulty, from grey (trivial) through green, yellow and orange to red (5+ levels above you)."] = "Pone color al texto de nivel según la dificultad, del gris (trivial) al verde, amarillo, naranja y rojo (5 niveles o más por encima de ti)."
L["Level Text: Include Friendly"] = "Texto de nivel: incluir amistosos"
L["Friendly units get their level's color too, instead of gold."] = "Las unidades amistosas también llevan el color de su nivel en lugar de dorado."
L["Difficulty Color"] = "Color de dificultad"
L["Colors an attackable unit's level by difficulty, as the default UI does."] = "Pone color al nivel de una unidad atacable según la dificultad, como la interfaz predeterminada."
L["This option does not apply to the player frame."] = "Esta opción no se aplica al marco del jugador."
L["Power Border Options"] = "Opciones borde poder"
L["Spell Cost Prediction"] = "Previsión de coste"
L["While you cast, shows on the bar the mana the spell will cost."] = "Mientras lanzas, muestra en la barra el maná que costará el hechizo."
L["Spell Cost Color"] = "Color del coste"
L["Show spell cost preview"] = "Mostrar la vista previa del coste del hechizo"
L["Hide spell cost preview"] = "Ocultar la vista previa del coste del hechizo"
L["Apply Show Cast Bar and Cast Color to Target and Focus"] = "Aplicar Mostrar barra de hechizos y el color de hechizo al objetivo y al foco"
L["This option can't be used while Blizzard Class Resource Art is enabled in Resource Bars."] = "Esta opción no se puede usar mientras esté activado Dibujo del recurso de clase de Blizzard en Barras de recursos."
L["Buffs join the debuff stack as its first rows; debuffs continue on the next row and move as buff rows change."] = "Los beneficios se unen al montón de perjuicios como sus primeras filas; los perjuicios siguen en la fila siguiente y se mueven cuando cambian las filas de beneficios."
L["This option is not available on the player frame"] = "Esta opción no está disponible en el marco del jugador"
L["This option requires Blizzard Style to be disabled"] = "Esta opción necesita que Estilo de Blizzard esté desactivado"
L["Blizzard Border"] = "Borde de Blizzard"
L["Purgeable Buffs"] = "Beneficios purgables"
L["Glow the buffs you can purge or spellsteal"] = "Hacer brillar los beneficios que puedes purgar o robar"
L["Glow Style"] = "Estilo del brillo"
L["Glows the buffs you can purge or spellsteal. Glowing buffs lead the row and have their own Max Buffs count."] = "Hace brillar los beneficios que puedes purgar o robar. Los beneficios que brillan van los primeros de la fila y tienen su propio máximo de beneficios."
L["a Glow Style"] = "un estilo de brillo"
L["Uncheck All Debuffs to choose how the Show filters combine."] = "Desmarca Todos los perjuicios para elegir cómo se combinan los filtros de Mostrar."
L["Match Any Filter"] = "Cumplir algún filtro"
L["Shows debuffs that match any checked Show filter (the default)."] = "Muestra los perjuicios que cumplen algún filtro de Mostrar marcado (lo predeterminado)."
L["Match All Filters"] = "Cumplir todos los filtros"
L["Shows only debuffs that match every checked Show filter (dispel types count as one); opposites like Non-Player Auras with Cast By You show nothing."] = "Solo muestra los perjuicios que cumplen todos los filtros de Mostrar marcados (los tipos de disipación cuentan como uno); los opuestos, como Auras de no jugadores con Lanzados por ti, no muestran nada."
L["From Top Edge"] = "Desde el borde de arriba"
L["From Bottom Edge"] = "Desde el borde de abajo"
L["Hide heal absorb preview"] = "Ocultar la vista previa de la absorción de sanación"
L["Above Absorb Bar"] = "Encima de la barra de absorción"
L["Shows incoming heals past the health bar: yours, then other players'."] = "Muestra las sanaciones que llegan más allá de la barra de salud: las tuyas y luego las de otros jugadores."
L["Show heal prediction preview"] = "Mostrar la vista previa de la predicción de sanación"
L["Hide heal prediction preview"] = "Ocultar la vista previa de la predicción de sanación"
L["Your heals"] = "Tus sanaciones"
L["Other players' heals"] = "Sanaciones de otros jugadores"
L["Flat"] = "Plano"
L["Overheal"] = "Sobresanación"
L["How far incoming heals can extend past the end of the health bar, as a percent of its length. 0 keeps them inside the bar."] = "Cuánto pueden pasar las sanaciones que llegan del final de la barra de salud, en porcentaje de su largo. Con 0 se quedan dentro de la barra."
L["Heal Prediction Texture"] = "Textura previsión sanación"
L["The Combat Indicator is not available for the Focus frame."] = "El indicador de combate no está disponible en el marco del foco."
L["Apply Leader Indicator to all Frames"] = "Aplicar el indicador de líder a todos los marcos"
L["Apply Leader Icon Size to all Frames"] = "Aplicar el tamaño del icono de líder a todos los marcos"
