L["Target Tracked Auras"] = "Auras seguidas del objetivo"
L["Copy Included/Excluded Spells From:"] = "Copiar los hechizos incluidos/excluidos de:"
L["Fill Color Settings"] = "Ajustes color relleno"
L["Dynamic Color"] = "Color dinámico"
