L["Important Only"] = "Solo importantes"
L["Important and Own"] = "Importantes y míos"
L["Important or Own"] = "Importantes o míos"
L["Not overridable"] = "No se puede cambiar"
L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "Solo muestra las auras seguidas de este marco; añádelas con Editar auras seguidas arriba de este menú."
L["Shows every debuff on this frame."] = "Muestra todos los perjuicios de este marco."
L["Shows only the debuffs you apply."] = "Solo muestra los perjuicios que aplicas tú."
L["Shows only debuffs Blizzard flags as important."] = "Solo muestra los perjuicios que Blizzard marca como importantes."
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "Solo muestra los perjuicios que aplicas tú y que Blizzard también marca como importantes."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "Muestra los perjuicios que aplicas tú y los importantes de cualquiera."
L["Combines with the conditions below: shows outright once at least one passes, otherwise still reveals on hover. A checked Hide state still hides it, hover included."] = "Se combina con las condiciones de abajo: se muestra directamente en cuanto se cumple al menos una; si no, sigue saliendo al pasar el ratón. Un estado Ocultar marcado lo sigue ocultando, también al pasar el ratón."
L["Makes this the override. It replaces the whole Visibility setting, so the conditions below no longer apply while it does. Click it again to remove the override."] = "Lo convierte en el ajuste propio. Sustituye todo el ajuste de visibilidad, así que las condiciones de abajo dejan de aplicarse mientras tanto. Vuelve a hacer clic para quitar el ajuste propio."
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies."] = "No se puede cambiar. Estas condiciones son compartidas y solo se pueden cambiar cuando no estás editando ningún ajuste propio. Un ajuste propio sustituye por completo el ajuste de visibilidad (nunca, siempre o al pasar el ratón) y no tiene en cuenta nada de lo que hay aquí mientras se aplica."
L["Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = "Al pasar el ratón también está bloqueado aquí para este elemento: su forma de mostrarse al pasar el ratón sigue el ajuste compartido, así que un ajuste propio solo podría dejarlo visible."
L["ARCANE SOUL (SUNFURY)"] = "ARCANE SOUL (SUNFURY)"
