L["Rotation Assist Thickness"] = "Grosor de la ayuda de rotación"
L["Rotation Assist Color"] = "Color ayuda rotación"
L["Rotation Assist Outset"] = "Separación ayuda rot."
L["Hide every Cooldown Manager glow out of combat and bring them all back the moment you enter combat."] = "Oculta todos los brillos del gestor de reutilizaciones fuera de combate y los vuelve a mostrar en cuanto entras en combate."
L["Replaces Buff Glow: the icon glows when its stack count matches the comparison below, using this spell's Buff Glow style (Modern WoW Glow if none is set)."] = "Sustituye a Brillo del beneficio: el icono brilla cuando su número de acumulaciones cumple la comparación de abajo, con el estilo de Brillo del beneficio de este hechizo (Brillo de WoW moderno si no hay ninguno)."
L["Only glow once the buff's stack count matches the comparison set via the gear."] = "Solo brilla cuando el número de acumulaciones del beneficio cumple la comparación del engranaje."
L["How many pixels the custom effect extends beyond the icon."] = "Cuántos píxeles sobresale el efecto personalizado del icono."
L["Thickness in physical pixels for Solid Border and Pixel Glow."] = "Grosor en píxeles físicos del borde sólido y del brillo de píxeles."
L["Choose the profile-wide border or glow used for Blizzard's Assisted Combat suggestion."] = "Elige el borde o brillo de todo el perfil para la sugerencia de combate asistido de Blizzard."
L["Sense Power (Ally)"] = "Detectar poder (aliado)"
L["Guardian of Ancient Kings (Glyph of the Queen)"] = "Guardian of Ancient Kings (Glyph of the Queen)"
L["All Debuffs is selected, so every debuff already shows. Use the red Hide box to exclude these instead."] = "Está elegido Todos los perjuicios, así que ya se muestran todos. Usa la casilla roja Ocultar para excluir estos."
L["House"] = "Casa"
