L["Felhunter"] = "Manáfago"
L["You have not learned %1$s."] = "No has aprendido %1$s."
L["Show Icon when Sated"] = "Ver icono si saciado"
L["Show Icon with Ready Text"] = "Ver icono con «Listo»"
L["Ready Size"] = "Tamaño de «Listo»"
L["Enter the maximum debuff duration in seconds:"] = "Escribe la duración máxima del perjuicio en segundos:"
L["Show the Sated/Exhaustion lockout countdown on the icon."] = "Muestra en el icono la cuenta atrás del bloqueo de Saciado/Agotamiento."
L["Once the lockout expires, show a Ready label on the icon in place of the countdown. The visibility rule above still applies."] = "Cuando termina el bloqueo, muestra en el icono «Listo» en lugar de la cuenta atrás. La regla de visibilidad de arriba se sigue aplicando."
L["QUICK FIRE"] = "DISPARO RÁPIDO"
L["Enable Quick Fire"] = "Activar disparo rápido"
L["Place World Marker"] = "Poner marca del mundo"
L["Undo Last Marker"] = "Deshacer la última marca"
L["Clear All Markers"] = "Quitar todas las marcas"
L["Keeps a saved signup note you can copy into the Sign Up dialog with the Copy button."] = "Guarda una nota de inscripción que puedes copiar en la ventana de Inscribirse con el botón Copiar."
L["Adds three optional world-marker keybinds that remain usable in combat. Place drops the first free marker at the cursor in Star to Skull order; Undo removes the last marker placed through Quick Fire; Clear removes all world markers. Every binding starts empty. Marker changes made elsewhere during combat are picked up afterward."] = "Añade tres atajos opcionales de marcas del mundo que se pueden usar en combate. Poner deja la primera marca libre en el cursor, en orden de Estrella a Calavera; Deshacer quita la última marca puesta con Disparo rápido; Quitar quita todas las marcas del mundo. Todos los atajos empiezan vacíos. Los cambios de marcas hechos de otra forma en combate se recogen después."
L["Shows the Role Check button in window layouts and enables Right Click: Role Check on Compact Band."] = "Muestra el botón Comprobación de función en las disposiciones de ventana y activa Clic derecho: Comprobación de función en Banda compacta."
L["Countdown length in seconds. Compact Band uses First with Ctrl + Left Click, Second with Shift + Left Click, Third with Left Click, and Right Click stops the timer. Set a timer to 0 to disable that shortcut."] = "Duración de la cuenta atrás en segundos. Banda compacta usa el primero con Ctrl + clic izquierdo, el segundo con Mayús + clic izquierdo, el tercero con clic izquierdo, y el clic derecho para el temporizador. Pon un temporizador en 0 para desactivar ese atajo."
L["Interface Panels"] = "Paneles de la interfaz"
L["Combat Status"] = "Estado de combate"
L["Broker Plugin"] = "Plugin de Broker"
L["Plugin"] = "Plugin"
L["Select a plugin"] = "Elige un plugin"
L["Strip Colors"] = "Quitar colores"
L["Match Mode"] = "Modo de coincidencia"
L["Match All Conditions"] = "Cumplir todas"
L["Match Any Condition"] = "Cumplir alguna condición"
L["Center Reticle"] = "Punto central"
L["Adds a small filled dot at the center of the cursor circle. Uses the same color and opacity as the circle."] = "Añade un punto relleno pequeño en el centro del círculo del cursor. Usa el mismo color y la misma opacidad que el círculo."
L["Every condition you set has to match. The default."] = "Tienen que cumplirse todas las condiciones que pongas. Es lo predeterminado."
L["Any LibDataBroker plugin registered right now. One block per plugin -- add the block again for a second one."] = "Cualquier plugin de LibDataBroker registrado ahora mismo. Un bloque por plugin: añade otra vez el bloque para tener un segundo."
L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "Muestra el texto del plugin. Si lo desactivas, el bloque queda solo con el icono y sigue teniendo la descripción y los clics del plugin."
L["Removes the color codes the plugin writes into its own text, so this block's Text Color applies. Off keeps the plugin's colors."] = "Quita los códigos de color que el plugin pone en su propio texto, para que se aplique el Color del texto de este bloque. Si lo desactivas, se mantienen los colores del plugin."
L["Holds the block at this width and clips longer text, so a plugin whose text keeps changing length never shifts the blocks beside it. Zero sizes the block to whatever the plugin currently says."] = "Deja el bloque con esta anchura y corta el texto más largo, para que un plugin cuyo texto cambia de largo nunca mueva los bloques de al lado. Con cero, el bloque tiene el tamaño de lo que diga el plugin en ese momento."
L["Prefixes the plugin's own name to its text."] = "Pone el nombre del plugin delante de su texto."
L["Shows the plugin's own icon next to its text."] = "Muestra el icono del plugin junto a su texto."
L["Friend Notifications"] = "Avisos de amigos"
L["The Battle.net popup when a friend comes online or goes offline, plus broadcasts and invites."] = "La ventana emergente de Battle.net cuando un amigo se conecta o se desconecta, además de los mensajes y las invitaciones."
L["Changing the Friend Notifications reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Para cambiar del todo entre el aspecto de Blizzard y el de Ellesmere en los avisos de amigos hay que recargar la interfaz."
L["The friends window backdrop, frame border, tabs, search boxes, bottom buttons and close button. Friend entries stay untouched; Blizz Default keeps the Friends List module's own flat look."] = "El fondo de la ventana de amigos, el borde del marco, las pestañas, los cuadros de búsqueda, los botones de abajo y el botón de cerrar. Las filas de los amigos no cambian; Predeterminado de Blizzard mantiene el aspecto plano del módulo de lista de amigos."
L["INTERRUPT AND VISIBILITY"] = "INTERRUPCIÓN Y VISIBILIDAD"
L["Cast Colors"] = "Colores de los hechizos"
L["Fade Out of Interrupt Range"] = "Atenuar sin alcance de corte"
