L["Combat data stayed restricted for this run"] = "Los datos de combate se quedaron restringidos en esta llave"
L["Current season score plus the gain from this run. Your own gain is the exact value the server reports; for party members it is their score before the key subtracted from their score after it."] = "Puntuación de la temporada actual más lo ganado en esta llave. Lo tuyo es el valor exacto que da el servidor; para los demás del grupo es su puntuación después de la llave menos la de antes."
L["Delete every recorded Mythic+ run for this character?"] = "¿Borrar todas las llaves de mítica+ guardadas de este personaje?"
L["Depleted"] = "Agotada"
L["No loot recorded for this player in this run."] = "No hay botín guardado de este jugador en esta llave."
L["No runs recorded yet"] = "Aún no hay llaves guardadas"
L["Open the overview once the end of run chest has been looted. With this off it opens as soon as the key ends. /ov reopens it at any time."] = "Abre el resumen cuando se haya despojado el cofre del final de la llave. Si lo desactivas, se abre en cuanto acaba la llave. /ov lo vuelve a abrir cuando quieras."
L["Records every finished Mythic+ key and shows an overview of the group when the run ends. Nothing is registered or created while this is off."] = "Guarda cada llave de mítica+ terminada y muestra un resumen del grupo al acabar. Si está desactivado, no se guarda ni se crea nada."
L["Run Summary is disabled in Mythic+ Tools."] = "El resumen de la llave está desactivado en Herramientas de mítica+."
L["Score"] = "Puntuación"
L["Shown in grey next to each name. Item levels are read by inspecting party members during the run, so a member who stayed out of range shows none."] = "Se ve en gris junto a cada nombre. Los niveles de objeto se leen inspeccionando al grupo durante la llave, así que quien se quedó fuera de alcance no tiene."
L["Size of the player rows. The title and column headers keep their own size."] = "Tamaño de las filas de jugadores. El título y los títulos de las columnas mantienen su tamaño."
L["Taken"] = "Recibido"
L["What each player looted. Your own chest reward always appears; other players' items only when the server announces the loot to the group, which it does not always do for the end of run chest."] = "Lo que despojó cada jugador. Tu recompensa del cofre sale siempre; los objetos de los demás solo cuando el servidor anuncia el botín al grupo, cosa que no siempre hace con el cofre del final de la llave."
L["Outfits"] = "Atuendos"
L["Show/Hide Windows Keybind"] = "Atajo ver/ocultar ventanas"
L["Keybind Scope"] = "Alcance del atajo"
L["Include Combat Timer"] = "Incluir tempor. combate"
L["Include Spell History"] = "Incluir historial"
L["Unsafe Refresh Rate"] = "Refresco arriesgado"
L["Hide and show every damage meter window at once. The state is not saved; a reload restores the configured visibility.\n\nThe bound key is taken over while it is set. Use the cog to include the combat timer and Spell History.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Oculta y muestra a la vez todas las ventanas del medidor de daño. El estado no se guarda; al recargar vuelve la visibilidad configurada.\n\nLa tecla asignada se usa solo para esto mientras esté puesta. Usa el engranaje para incluir el temporizador de combate y el historial de hechizos.\n\nClic izquierdo para asignar un atajo.\nClic derecho para quitarlo."
L["Blizzard damage meter is off"] = "El medidor de daño de Blizzard está desactivado"
L["Read from Blizzard's own damage meter. With that meter switched off this column, Damage Taken and Interrupts stay empty."] = "Se lee del propio medidor de daño de Blizzard. Si ese medidor está desactivado, esta columna, Daño recibido e Interrupciones se quedan vacías."
L["Faster than 0.5s makes the meters work much harder in combat and can cost you frames, especially with several windows open."] = "Por debajo de 0,5 s los medidores trabajan mucho más en combate y pueden quitarte fotogramas, sobre todo con varias ventanas abiertas."
L["Lets you set Refresh Rate faster than 0.5s. The meters update more often but work much harder in combat, which can cost you frames. Only turn this on if your PC has performance to spare."] = "Te deja poner la frecuencia de actualización por debajo de 0,5 s. Los medidores se actualizan más a menudo pero trabajan mucho más en combate, lo que puede quitarte fotogramas. Actívalo solo si tu PC va sobrado."
L["Only works outside of Instances"] = "Solo funciona fuera de instancias"
L["Enable Chat Bubbles Customization"] = "Activar la personalización de los bocadillos de chat"
L["Chat Bubbles"] = "Bocadillos"
L["Follow Blizzard Default Color"] = "Color predeterminado Blizzard"
L["Channels"] = "Canales"
L["Say"] = "Decir"
L["Yell"] = "Gritar"
L["NPCs"] = "PNJ"
L["Emotes"] = "Emociones"
L["Hide Chat Bubbles in Instances"] = "Ocultar bocadillos en instancias"
L["Padding"] = "Relleno"
L["Maximum Width"] = "Anchura máxima"
L["Vertical Offset"] = "Desplazamiento vertical"
L["Choose which channels get a bubble."] = "Elige qué canales llevan bocadillo."
L["Space between the text and the edge of the bubble."] = "Espacio entre el texto y el borde del bocadillo."
L["Show Clear Button"] = "Mostrar el botón de borrar"
L["GROUPING"] = "AGRUPACIÓN"
L["Group by Category"] = "Agrupar por categoría"
L["Category Sidebar"] = "Lateral categorías"
L["Hide Empty Slots When Grouped"] = "Ocultar los huecos vacíos al agrupar"
L["Hide Bank Tabs in Sidebar"] = "Ocultar pestañas banco"
L["Stack Splitter"] = "Dividir montones"
L["Auto Split"] = "División automática"
L["Split Stack"] = "Dividir montón"
L["Empty Slots"] = "Huecos vacíos"
L["No Items"] = "No hay objetos"
L["Turn on Category Sidebar first, or the sidebar would have nothing left to navigate with."] = "Activa antes Barra lateral de categorías, o la barra lateral se quedaría sin nada con lo que moverse."
L["Right-click a tab in the bank sidebar to rename it or set its deposit filters."] = "Clic derecho en una pestaña de la barra lateral del banco para cambiarle el nombre o elegir sus filtros de depósito."
L["Window scale, icon zoom and item level settings are shared with the Bags page."] = "La escala de la ventana, el zoom de los iconos y los ajustes de nivel de objeto se comparten con la página de Bolsas."
L["In the OneBank and OneWarbank views, split the grid under expansion headers, newest first. Per-tab views are unaffected."] = "En las vistas OneBank y OneWarbank, separa la cuadrícula con títulos de expansión, las más nuevas primero. Las vistas por pestaña no cambian."
L["List item categories in the bank sidebar the way the bags sidebar does -- groups such as The Armory with Weapons and Armor under them. Selecting one filters the grid to that category. Categories that split further list their parts as a third level while selected: Professions by profession, Armor by equipment slot, Trade Goods by material. Spans your character bank and warband together, so a category shows everything you own."] = "Muestra las categorías de objetos en la barra lateral del banco igual que en la de las bolsas: grupos como El Arsenal con Armas y Armadura debajo. Al elegir una, la cuadrícula muestra solo esa categoría. Las categorías que se dividen más muestran sus partes como tercer nivel al elegirlas: Profesiones por profesión, Armadura por hueco de equipo, Componentes comerciables por material. Abarca a la vez el banco del personaje y el de la banda guerrera, así que una categoría muestra todo lo que tienes."
L["Turn on Nest by Expansion or Group by Category first; the flat view has nowhere to move empty slots to."] = "Activa antes Agrupar por expansión o Agrupar por categoría; en la vista plana no hay adónde mover los huecos vacíos."
L["Split items by category -- Armor, Consumables, Professions and so on -- using the same category list, order and renames as the All Items bag view. Nests inside the expansion headers when Nest by Expansion is also on. Categories that split further do so automatically: gear by equipment slot, Professions and Trade Goods by profession and material type."] = "Separa los objetos por categoría (Armadura, Consumibles, Profesiones, etc.) con la misma lista, orden y nombres que la vista Todos los objetos de las bolsas. Va dentro de los títulos de expansión cuando también está activado Agrupar por expansión. Las categorías que se dividen más lo hacen automáticamente: el equipo por hueco, y Profesiones y Componentes comerciables por profesión y tipo de material."
L["Drop the individual Tab 1 / Tab 2 / Warbank Tab entries once the category list is doing the navigating. The consolidated views stay. Note that right-clicking a tab entry is the only way to rename a tab or change its deposit filters, so leave this off if you still need that."] = "Quita las entradas sueltas Pestaña 1 / Pestaña 2 / Pestaña del banco de la banda guerrera cuando la lista de categorías ya sirve para moverse. Las vistas juntas se mantienen. Ojo: el clic derecho en una pestaña es la única forma de cambiarle el nombre o los filtros de depósito, así que déjalo desactivado si aún lo necesitas."
L["While either grouping toggle is on, drop the trailing block of empty slots so the view only shows items. Turn this off to keep the free slots visible for depositing."] = "Mientras esté activada alguna forma de agrupar, quita el bloque de huecos vacíos del final para que la vista muestre solo objetos. Desactívalo para seguir viendo los huecos libres para depositar."
L["Fade a bar when the enemy is beyond your active interrupt spell's range. Has no effect for specs without an interrupt."] = "Atenúa una barra cuando el enemigo está más lejos que el alcance de tu hechizo de interrupción activo. No hace nada en especializaciones sin interrupción."
L["Show the enemy's raid target marker to the left of the spell name."] = "Muestra la marca de banda del enemigo a la izquierda del nombre del hechizo."
L["Glow the bar when the enemy casts a spell Blizzard flags as important."] = "Hace brillar la barra cuando el enemigo lanza un hechizo que Blizzard marca como importante."
L["Limit the bars to the selected content and combat states; nothing selected shows them everywhere."] = "Limita las barras al contenido y los estados de combate elegidos; si no eliges nada, se ven en todas partes."
