L["Screen layer this bar renders on. Raise it to draw over other frames, lower it to sit behind them."] = "Capa de la pantalla en la que se dibuja esta barra. Súbela para que se vea encima de otros marcos o bájala para que quede detrás."
L["Which part of the row stays in place as reminders appear and disappear."] = "Qué parte de la fila se queda en su sitio cuando aparecen y desaparecen recordatorios."
L["Sell Junk"] = "Vender chatarra"
L["Height of each row in the bag and bank lists. Icons shrink to fit short rows."] = "Altura de cada fila en las listas de bolsas y banco. Los iconos se encogen si las filas son bajas."
L["Remove the shading on every other row in the bag and bank lists."] = "Quita el sombreado de una de cada dos filas en las listas de bolsas y banco."
L["Draw a border in the item's quality color around item icons in the bags and bank. Round list icons have no border."] = "Dibuja un borde del color de la calidad del objeto alrededor de los iconos de las bolsas y el banco. Los iconos redondos de la lista no llevan borde."
L["Show the total vendor sell price of each section's items next to its count in the bag list."] = "Muestra junto al número de objetos de cada sección el precio total de venta al mercader en la lista de bolsas."
L["Adds Mana to the Attributes section."] = "Añade el maná a la sección Atributos."
L["Shows the item level and stat titles in Blizzard's yellow."] = "Muestra el nivel de objeto y los títulos de las estadísticas en el amarillo de Blizzard."
L["Character Sheet: Blizz Default"] = "Hoja del personaje: Predeterminado de Blizzard"
L["Choose what shows on each equipped item."] = "Elige qué se muestra en cada objeto equipado."
L["Choose which channels show the speaker."] = "Elige en qué canales se muestra quién habla."
L["Auto Size"] = "Tamaño automático"
L["Hide the arrows beside equipment slots on the Equipment tab. The slot flyouts remain usable."] = "Oculta las flechas junto a los huecos de equipo de la pestaña Equipo. Las listas de cada hueco se pueden seguir usando."
L["How enchants show beside each item."] = "Cómo se muestran los encantamientos junto a cada objeto."
L["Items below this quality are not shown."] = "No se muestran los objetos de calidad inferior a esta."
L["Show each item's main and secondary stat (or its armor) and each weapon's damage per second beside its slot."] = "Muestra junto a su hueco la estadística principal y la secundaria de cada objeto (o su armadura) y el daño por segundo de cada arma."
L["The dots at the two ends of the track."] = "Los puntos de los dos extremos del recorrido."
L["Threat Gap shows on your target's plate only."] = "La diferencia de amenaza solo se ve en la placa de tu objetivo."
L["Color by Threat"] = "Color según la amenaza"
L["Colors the number by threat status. Off shows it in white."] = "Pone color al número según la amenaza. Desactivado lo muestra en blanco."
L["Colors the number. Off shows it in white."] = "Pone color al número. Desactivado lo muestra en blanco."
L["Only show the meter while there is threat to list. Unchecked keeps the header and its buttons on screen."] = "Muestra el medidor solo mientras haya amenaza que mostrar. Si lo desmarcas, el título y sus botones se quedan en pantalla."
L["Percent of the end caps' normal size."] = "Porcentaje del tamaño normal de los remates."
L["Positive values move both end caps away from the bar."] = "Los valores positivos alejan los dos remates de la barra."
L["Pull % reaches 100 where a player would take aggro, Tank % where they match the tank's threat."] = "Para quitar el aggro (%) llega a 100 cuando un jugador quitaría el aggro; Del tanque (%), cuando iguala la amenaza del tanque."
L["This class has ten debuffs."] = "Esta clase tiene diez perjuicios."
L["Thickens the border by this many pixels while it shows a debuff color."] = "Engrosa el borde estos píxeles mientras muestra un color de perjuicio."
L["Where nameplates show threat colors."] = "Dónde muestran las placas de nombre los colores de amenaza."
L["Also applies the target Border Color and Border Size effects to friendly nameplates."] = "Aplica también los efectos de Color del borde y Tamaño del borde del objetivo a las placas de nombre amistosas."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Only Dispellable shows just the buffs that can be dispelled, purged or soothed; Show All shows every buff. With Show Glow on (in the cog), every dispellable buff shown gets a border."] = "Qué beneficios enemigos se ven en las placas de nombre. Importantes muestra los que Blizzard marca para las placas enemigas y todo lo que se pueda disipar; Solo disipables muestra solo los que se pueden disipar, purgar o calmar; Mostrar todo muestra todos. Con Mostrar brillo activado (en el engranaje), todos los beneficios disipables que se ven llevan un borde."
L["Choose this text's slot position."] = "Elige la posición de este texto."
L["Draws the border style's seam line between the health and cast bars."] = "Dibuja la línea de unión del estilo de borde entre la barra de salud y la de hechizos."
L["Gives debuff, buff and crowd control icons the custom border instead of the 1-pixel border."] = "Pone el borde personalizado a los iconos de perjuicios, beneficios y control de masas en lugar del borde de 1 píxel."
L["Gives the cast bar spell icon the custom border instead of its 1-pixel border."] = "Pone el borde personalizado al icono del hechizo de la barra de hechizos en lugar de su borde de 1 píxel."
L["Shows the level box right of the health bar; with it off, Left Text can show the level instead."] = "Muestra la caja del nivel a la derecha de la barra de salud; si la desactivas, el Texto izquierdo puede mostrar el nivel."
L["This option requires at least one aura type to show its border."] = "Esta opción necesita que al menos un tipo de aura muestre su borde."
L["This option requires two debuffs for the same class"] = "Esta opción necesita dos perjuicios de la misma clase"
L["This option requires a debuff to be selected"] = "Esta opción necesita elegir un perjuicio"
L["%1$d. Combo"] = "%1$d. Combinación"
L["%1$d. Debuff"] = "%1$d. Perjuicio"
L["%1$s Combo %2$d"] = "%1$s combinación %2$d"
L["%1$s Debuff %2$d"] = "%1$s perjuicio %2$d"
L["Pick at least two debuffs"] = "Elige al menos dos perjuicios"
L["Enter a valid debuff spell ID."] = "Escribe un ID de hechizo de perjuicio válido."
L["Shown by %1$s instead."] = "Lo muestra %1$s en su lugar."
L["Shown by %1$s, which comes first."] = "Lo muestra %1$s, que va antes."
L["Spell ID: %1$s"] = "ID del hechizo: %1$s"
L["Chooses which parts of the nameplate show the threat colors; with Health Bar off, the bar keeps its Enemy Types color."] = "Elige qué partes de la placa de nombre muestran los colores de amenaza; con Barra de salud desactivada, la barra mantiene el color de Tipos de enemigo."
L["Colors enemy health bars, or their borders, while the chosen debuffs are on them."] = "Pone color a las barras de salud enemigas, o a sus bordes, mientras tienen los perjuicios elegidos."
L["Colors your target's custom spell icon border, or a full-size wrapped 1-pixel one, with the target border color."] = "Pone el color del borde del objetivo al borde del icono del hechizo personalizado de tu objetivo, o a uno de 1 píxel a tamaño completo."
L["Combo Color"] = "Color de la combinación"
L["Counts only the debuffs you applied."] = "Solo cuenta los perjuicios que has aplicado tú."
L["Debuff Color"] = "Color del perjuicio"
L["Debuff Coloring"] = "Colores por perjuicios"
L["How enemy plates look while out of combat."] = "Cómo se ven las placas enemigas fuera de combate."
L["Show Threat % on Nameplates"] = "Ver amenaza (%) en placas"
L["Show Threat Colors"] = "Mostrar colores de amenaza"
L["Shows your threat percentage on each enemy nameplate while you are in combat with it."] = "Muestra tu porcentaje de amenaza en cada placa de nombre enemiga mientras estás en combate con ella."
L["10% Lines"] = "Líneas del 10%"
L["5% Ticks"] = "Marcas del 5%"
L["Toggles Blizzard's cooldown numbers setting."] = "Activa o desactiva el ajuste de Blizzard de los números de reutilización."
L["This option requires a bar set to Mouseover"] = "Esta opción necesita una barra puesta en Al pasar el ratón"
L["Where the bar text sits inside the bar; the offsets nudge it from there."] = "Dónde va el texto dentro de la barra; los desplazamientos lo mueven desde ahí."
L["Shows the XP from quests in your quest log ahead of the fill."] = "Muestra delante del relleno la experiencia de las misiones de tu registro."
L["This option requires Current %, Current or Current / Max"] = "Esta opción necesita Actual (%), Actual o Actual / máximo"
L["Draws this bar's button borders over proc glows, the assisted highlight and the cooldown swipe."] = "Dibuja los bordes de los botones de esta barra encima de los brillos de proc, la ayuda resaltada y el barrido de reutilización."
L["Hovering one Mouseover bar shows them all."] = "Al pasar el ratón por una barra de Al pasar el ratón se ven todas."
L["Keeps this bar on its page in any form."] = "Mantiene esta barra en su página en cualquier forma."
L["On bars with a textured border style, a press lights up the button's own border instead of drawing lines."] = "En las barras con estilo de borde con textura, al pulsar se ilumina el propio borde del botón en lugar de dibujar líneas."
L["On bars with a textured border style, hovering lights up the button's own border instead of drawing lines."] = "En las barras con estilo de borde con textura, al pasar el ratón se ilumina el propio borde del botón en lugar de dibujar líneas."
L["On bars with a textured border style, the active spell shows a colored border instead of the highlight fill."] = "En las barras con estilo de borde con textura, el hechizo activo muestra un borde de color en lugar del relleno de resaltado."
L["Shows Blizzard's slot art on empty slots."] = "Muestra el dibujo de los huecos de Blizzard en los huecos vacíos."
L["Draws boss aura icon borders over their cooldown swipes and glows. Duration and stack text stay above the borders."] = "Dibuja los bordes de los iconos de auras de los jefes encima de sus barridos de reutilización y brillos. El texto de duración y acumulaciones queda por encima de los bordes."
L["Draws the selected border style between the attached portrait and the bars."] = "Dibuja el estilo de borde elegido entre el retrato unido y las barras."
L["Mirrors playable-race portraits in 2D. Always flips class art horizontally."] = "Pone en espejo los retratos 2D de las razas jugables. El dibujo de clase siempre se da la vuelta en horizontal."
L["Pick what NPCs show in Class art instead of their 2D portrait."] = "Elige qué muestran los PNJ con Dibujo de clase en lugar de su retrato 2D."
L["Show the border style and size controls for the cast bar."] = "Muestra los controles de estilo y tamaño del borde de la barra de hechizos."
L["Text shown before the target's name."] = "Texto que va delante del nombre del objetivo."
L["This option only applies when Name > Target is selected."] = "Esta opción solo se aplica si está elegido Nombre > Objetivo."
L["This option only applies when Name > Target or Target is selected."] = "Esta opción solo se aplica si está elegido Nombre > Objetivo u Objetivo."
L["This option only applies when Target is selected."] = "Esta opción solo se aplica si está elegido Objetivo."
L["This option only applies when the text shows a name."] = "Esta opción solo se aplica cuando el texto muestra un nombre."
L["This option requires Custom Border Style, Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Esta opción necesita Estilo de borde personalizado, Mostrar icono e Integrar el icono en la barra, con el estilo de EllesmereUI."
L["This option requires Show Icon and the EllesmereUI style."] = "Esta opción necesita Mostrar icono y el estilo de EllesmereUI."
L["This option requires Show Icon beside the cast bar and the EllesmereUI style."] = "Esta opción necesita Mostrar icono junto a la barra de hechizos y el estilo de EllesmereUI."
L["This option requires a textured Aura Border with a size above 0, and its Show Behind and Behind Unit Frame options disabled."] = "Esta opción necesita un borde de aura con textura de tamaño mayor que 0, y sus opciones Mostrar detrás y Detrás del marco de unidad desactivadas."
L["Use the cast bar's border style, size and color around the icon."] = "Usa el estilo, el tamaño y el color del borde de la barra de hechizos alrededor del icono."
L["Adds a second ring around a round portrait; Match Frame Border follows your frame border style."] = "Añade un segundo anillo alrededor de un retrato redondo; Igual que el borde del marco sigue el estilo del borde de tu marco."
L["Adds a soft shadow inside a round portrait."] = "Añade una sombra suave dentro de un retrato redondo."
L["Apply Non-Player Portrait to all Frames"] = "Aplicar Retrato de quien no es jugador a todos los marcos"
L["Art used for the leader crown and the assistant icon."] = "Dibujo de la corona de líder y del icono de ayudante."
L["Badge shows a small icon; Pixels Dragon wraps the portrait in classification art."] = "Insignia muestra un icono pequeño; Dragón Pixels rodea el retrato con el dibujo de su clasificación."
L["Keeps the unit's class or reaction color on the ring in Dark Mode instead of your own class color."] = "Mantiene en el anillo el color de clase o de reacción de la unidad en modo oscuro, en lugar de tu propio color de clase."
L["Marks elite, rare elite and rare targets; the Pixels Dragon style also marks players."] = "Marca los objetivos de élite, élite raro y raro; el estilo Dragón Pixels también marca a los jugadores."
L["Match Frame draws the dragon with the portrait. A higher strata draws it over the rest of the frame, border included."] = "Igual que el marco dibuja el dragón con el retrato. Un nivel de capa más alto lo dibuja encima del resto del marco, también del borde."
L["Mirrors playable-race portraits in 2D and 3D. Always flips class art horizontally."] = "Pone en espejo los retratos 2D y 3D de las razas jugables. El dibujo de clase siempre se da la vuelta en horizontal."
L["Raises the dragon within its strata. Higher values draw it over more of the frame."] = "Sube el dragón dentro de su nivel de capa. Con valores más altos se dibuja encima de más partes del marco."
L["Shows your threat percentage on the target frame while you are in combat with it. The cog adds the focus frame."] = "Muestra tu porcentaje de amenaza en el marco del objetivo mientras estás en combate con él. El engranaje añade el marco del foco."
L["Size of the dragon, as a percent of its fit around the portrait."] = "Tamaño del dragón, en porcentaje de lo que ocupa alrededor del retrato."
L["Size of the outer ring relative to the portrait."] = "Tamaño del anillo exterior respecto al retrato."
L["This option requires a Circle or Pixels Circle Shape."] = "Esta opción necesita la forma Círculo o Círculo Pixels."
L["This option requires a border style with divider art and a Border Size above 0."] = "Esta opción necesita un estilo de borde con dibujo separador y un tamaño de borde mayor que 0."
L["This option requires the Class Colored Shape Border and Dark Mode."] = "Esta opción necesita el borde de forma con color de clase y el modo oscuro."
L["Turns the dragon to face the other way around the portrait."] = "Gira el dragón para que mire hacia el otro lado del retrato."
L["Adds the Blizzard shield glow line where the shield meets current health."] = "Añade la línea de brillo de escudo de Blizzard donde el escudo se junta con la salud actual."
L["Art used for the glow line and the overshield edge."] = "Dibujo de la línea de brillo y del borde del escudo sobrante."
L["Mana keeps the bar on Mana in Bear and Cat Form. Mana + Form Power also shows your Energy or Rage in a second bar."] = "Maná mantiene la barra en maná en forma de oso y felina. Maná + poder de la forma muestra además tu energía o tu ira en una segunda barra."
L["Requires Power Type: Mana + Form Power."] = "Necesita Tipo de poder: maná + poder de la forma."
L["Apply Important Cast Glow to Target and Focus"] = "Aplicar el brillo de hechizo importante al objetivo y al foco"
L["Colors the dispel type borders with your Dispel Colors instead of Blizzard's."] = "Pone a los bordes por tipo de disipación tus colores de disipación en lugar de los de Blizzard."
L["Only show buffs that have a duration, excluding permanent ones. Combines with the filters below."] = "Solo muestra los beneficios con duración, sin los permanentes. Se combina con los filtros de abajo."
L["Only show debuffs that have a duration, excluding permanent ones. Tracked Auras always show."] = "Solo muestra los perjuicios con duración, sin los permanentes. Las auras seguidas se muestran siempre."
L["Recolors the frame border, portrait outer ring and enabled power and portrait separators in the dispel type color while a debuff of that type is shown."] = "Cambia el color del borde del marco, del anillo exterior del retrato y de los separadores de poder y retrato activados al color del tipo de disipación mientras se muestra un perjuicio de ese tipo."
L["Show Icon on Portrait"] = "Icono en el retrato"
L["Shows the spell icon over the portrait while casting and lets the bar use the full width."] = "Muestra el icono del hechizo sobre el retrato mientras lanzas y deja que la barra use toda la anchura."
L["This option requires a Dispel Overlay, Color Custom Borders or Use Dispel Colors."] = "Esta opción necesita una capa de disipación, Colorear los bordes personalizados o Usar los colores de disipación."
L["This option requires an attached Power Bar, a Border Size above 0 and a border style with seam art."] = "Esta opción necesita una barra de poder unida, un tamaño de borde mayor que 0 y un estilo de borde con dibujo de unión."
L["Apply Cast Bar Border Style to all Frames"] = "Aplicar el estilo de borde de la barra de hechizos a todos los marcos"
L["Apply Cast Bar Border to all Frames"] = "Aplicar el borde de la barra de hechizos a todos los marcos"
L["Border art drawn around the boss frames. Inherit (Main Frames) uses the main frames' border."] = "Dibujo del borde alrededor de los marcos de jefe. Heredar (marcos principales) usa el borde de los marcos principales."
L["Border art drawn around the cast bar."] = "Dibujo del borde alrededor de la barra de hechizos."
L["Draw a divider between the integrated icon and the bar, using the cast bar's border appearance."] = "Dibuja un separador entre el icono integrado y la barra, con el aspecto del borde de la barra de hechizos."
L["Draw the custom cast bar border around the icon and the bar together. An icon with an offset keeps its own border."] = "Dibuja el borde personalizado de la barra de hechizos alrededor del icono y la barra juntos. Un icono con desplazamiento mantiene su propio borde."
L["Draws the border behind the cast bar instead of over it."] = "Dibuja el borde detrás de la barra de hechizos en lugar de encima."
L["Draws the border style's seam art between the health bar and an attached power bar."] = "Dibuja el dibujo de unión del estilo de borde entre la barra de salud y una barra de poder unida."
L["Draws the dispel-colored ring in this border style's shape instead of flat lines."] = "Dibuja el anillo con el color de disipación con la forma de este estilo de borde en lugar de con líneas planas."
L["Equipped items get a rarity color border."] = "Los objetos equipados llevan un borde del color de su rareza."
L["Hides the Unit Frames player cast bar while a controller is connected and gamepad mode is on. Blizzard's gamepad interface shows its own."] = "Oculta la barra de hechizos del jugador de los marcos de unidad mientras hay un mando conectado y el modo mando está activado. La interfaz de mando de Blizzard muestra la suya."
L["Overlay fills empty health first, then draws any excess over current health. Overlay Reverse draws the shield back over current health; a shield larger than current health spans from the bar's left end. From Right Edge and From Left Edge grow the whole shield from that end of the bar."] = "Capa llena primero la salud que falta y luego dibuja lo que sobra encima de la salud actual. Capa invertida dibuja el escudo hacia atrás sobre la salud actual; un escudo mayor que la salud actual va desde el extremo izquierdo de la barra. Desde el borde derecho y Desde el borde izquierdo hacen crecer todo el escudo desde ese extremo de la barra."
L["Requires a spell with a range"] = "Necesita un hechizo con alcance"
L["Right by default, or Bottom with Horizontal Frames. With Frame Style: Party Frames, the side holding the buffs is not available."] = "A la derecha de forma predeterminada, o abajo con Marcos en horizontal. Con Estilo de marco: Marcos de grupo, no está disponible el lado donde van los beneficios."
L["Scales the 3D character from the portrait's bottom edge, for use with the full-body 3D Zoom range above 300."] = "Cambia el tamaño del personaje 3D desde el borde de abajo del retrato, para usarlo con el zoom 3D de cuerpo entero por encima de 300."
L["Show a smaller secure target button beside each party frame. Left-click a button to target that party member's current target."] = "Muestra un botón de objetivo protegido más pequeño junto a cada marco de grupo. Clic izquierdo en un botón para seleccionar el objetivo actual de ese miembro del grupo."
L["Above 300 the camera pulls back to show the whole character."] = "Por encima de 300 la cámara se aleja para mostrar al personaje entero."
L["The bar fills with missing health, growing as the unit takes damage."] = "La barra se llena con la salud que falta y crece según la unidad recibe daño."
L["Adds your group's pets beside these frames, with their health, name, range and click-casting."] = "Añade las mascotas de tu grupo junto a estos marcos, con su salud, nombre, alcance y lanzamiento con clic."
L["Makes the pet frames taller or shorter relative to the frame size."] = "Hace los marcos de mascota más altos o más bajos en relación con el tamaño del marco."
L["Places the bar at the bottom of the frame instead of the top."] = "Pone la barra abajo del marco en lugar de arriba."
L["Widens or narrows the pet frames relative to the frame size."] = "Hace los marcos de mascota más anchos o más estrechos en relación con el tamaño del marco."
L["This option requires an Inside position"] = "Esta opción necesita una posición de dentro"
L["Also show your own target beside your frame."] = "Muestra también tu propio objetivo junto a tu marco."
L["Class Color uses the class color for players and the reaction color for NPCs."] = "Color de clase usa el color de clase en los jugadores y el color de reacción en los PNJ."
L["Shows Fortitude, Mark of the Wild, Spirit or Thorns on a member who is missing it, for the buffs you can cast yourself (choose which in the cog)."] = "Muestra Entereza, Marca de lo Salvaje, Espíritu o Thorns en un miembro al que le falte, de los beneficios que puedes lanzar tú (elige cuáles en el engranaje)."
L["Mana Colored"] = "Color de maná"
L["Mana keeps the bar on Mana in Bear and Cat Form."] = "Maná mantiene la barra en maná en forma de oso y felina."
L["On a vertical Power Bar, Below is the right side and Above is the left side."] = "En una barra de poder vertical, Debajo es el lado derecho y Encima el izquierdo."
L["Shows a thin mana bar with the Power Bar while in Bear and Cat Form."] = "Muestra una barra de maná fina junto a la barra de poder en forma de oso y felina."
L["This option requires Position to be Below or Above"] = "Esta opción necesita que la posición esté en Debajo o Encima"
L["This option requires Power Type to be set to Match Form"] = "Esta opción necesita que Tipo de poder esté en Igual que la forma"
L["Draws the icon divider in the border style's art instead of a solid line."] = "Dibuja el separador del icono con el dibujo del estilo de borde en lugar de con una línea sólida."
L["Grays the fill while your target is out of range of the spell being cast."] = "Pone en gris el relleno mientras tu objetivo está fuera del alcance del hechizo que lanzas."
L["Spell Text Color"] = "Color del texto del hechizo"
L["Draws a line in each gap between the pips."] = "Dibuja una línea en cada hueco entre los puntos."
L["Draws separator lines along the bar edge and between the pips."] = "Dibuja líneas separadoras por el borde de la barra y entre los puntos."
L["Draws the class resource background inside each pip so the gaps between pips stay clear."] = "Dibuja el fondo del recurso de clase dentro de cada punto para que los huecos entre puntos queden limpios."
L["Draws the class resource bar above the health, power and GCD bar borders."] = "Dibuja la barra del recurso de clase encima de los bordes de las barras de salud, poder y GCD."
L["Draws the line along the bar's bottom edge."] = "Dibuja la línea por el borde de abajo de la barra."
L["Separators"] = "Separadores"
L["This option can't be used while Border on individual pips is enabled."] = "Esta opción no se puede usar mientras Borde en cada punto esté activado."
L["Draws a separator line along the bar's bottom edge."] = "Dibuja una línea separadora por el borde de abajo de la barra."
L["Grows the border past the bar's bottom edge on screen without resizing the bar."] = "Alarga el borde por debajo del borde de abajo de la barra en pantalla sin cambiar el tamaño de la barra."
L["Grows the border past the bar's top edge on screen without resizing the bar."] = "Alarga el borde por encima del borde de arriba de la barra en pantalla sin cambiar el tamaño de la barra."
L["Draws the power bar's border above the GCD bar where the two overlap."] = "Dibuja el borde de la barra de poder encima de la barra de GCD donde se solapan."
L["Colors the bar while a chosen spell is ready."] = "Pone color a la barra mientras un hechizo elegido está listo."
L["Draws this bar's border in your own border style, size and color instead of the thin black line."] = "Dibuja el borde de esta barra con tu propio estilo, tamaño y color de borde en lugar de la línea negra fina."
L["How far the border reaches past the bar."] = "Cuánto sobresale el borde de la barra."
L["Runs the bar text along the bar."] = "Pone el texto de la barra a lo largo de la barra."
L["Runs the divider percentages along the bar."] = "Pone los porcentajes separadores a lo largo de la barra."
L["This option requires Custom Icon Shape to be set to Cropped"] = "Esta opción necesita que Forma de icono personalizada esté en Recortada"
L["Custom Spell..."] = "Hechizo personalizado..."
L["This option requires a Visibility other than Never"] = "Esta opción necesita una visibilidad distinta de Nunca"
L["Shows each guild or friend note on a second line under its row. The tooltip gets taller."] = "Muestra cada nota de hermandad o de amigo en una segunda línea debajo de su fila. La descripción es más alta."
L["Size of the icons on the map, such as group members, quest objectives and gathering nodes. The same setting as Blizzard's Edit Mode Icon Size."] = "Tamaño de los iconos del mapa, como los miembros del grupo, los objetivos de misión y los puntos de recolección. Es el mismo ajuste que Tamaño de los iconos del modo edición de Blizzard."
L["Fades the minimap while it is shown. Visibility still decides when it shows."] = "Atenúa el minimapa mientras se ve. La visibilidad sigue decidiendo cuándo se muestra."
L["Turns Dark Mode on or off for each module."] = "Activa o desactiva el modo oscuro en cada módulo."
L["Color and opacity behind Dark Mode bars."] = "Color y opacidad detrás de las barras del modo oscuro."
L["Darkens class, resource and power colors."] = "Oscurece los colores de clase, recurso y poder."
L["Fill color and opacity of Dark Mode bars."] = "Color y opacidad del relleno de las barras del modo oscuro."
L["Share this section's colors across profiles."] = "Comparte los colores de esta sección entre perfiles."
L["Shows your damage taken, healing, avoids and combat enter/leave above the player frame instead of Blizzard's combat text, whose other messages are hidden while this is on. Move it in Unlock Mode."] = "Muestra encima del marco del jugador el daño que recibes, la sanación, lo que evitas y la entrada/salida de combate en lugar del texto de combate de Blizzard, cuyos otros mensajes se ocultan mientras esto esté activado. Muévelo en el modo desbloqueo."
L["Self Combat Text"] = "Texto de combate propio"
L["Scroll Distance"] = "Distancia del recorrido"
L["Scroll Duration"] = "Duración del recorrido"
L["Crit Scale"] = "Escala de los críticos"
L["Stagger Hits"] = "Separar los golpes"
L["Spaces out hits that land together so none hides another."] = "Separa los golpes que llegan a la vez para que ninguno tape a otro."
L["Auto Select Single Gossip"] = "Elegir solo el único diálogo"
L["Auto Gossip Settings"] = "Ajustes diálogo auto."
L["Disable in Instances"] = "Desactivar en instancias"
L["Picks an NPC's only dialog option for you."] = "Elige por ti la única opción de diálogo de un PNJ."
L["Blizzard Default keeps the game's whisper sound. Any other sound replaces it, and None plays no sound."] = "Predeterminado de Blizzard mantiene el sonido de susurro del juego. Cualquier otro sonido lo sustituye, y Ninguno no hace ningún sonido."
L["Max rows per section in the Friends Online tooltip (0 = the 30-row max). The cog can show each note under its row."] = "Filas máximas por sección en la descripción de Amigos conectados (0 = el máximo de 30 filas). El engranaje puede mostrar cada nota debajo de su fila."
L["Colors the number when free slots drop below this many; the swatch picks the color. Zero turns it off."] = "Pone color al número cuando los huecos libres bajan de esta cantidad; la muestra de color elige el color. Con cero se desactiva."
L["Which slot count the block shows."] = "Qué número de huecos muestra el bloque."
L["Includes instance chat."] = "Incluye el chat de instancia."
L["Incomplete Color"] = "Color de incompleta"
L["Missing Buffs"] = "Beneficios que faltan"
L["Only counts quests in your current zone."] = "Solo cuenta las misiones de tu zona actual."
L["Only counts quests that are ready to turn in."] = "Solo cuenta las misiones que están listas para entregar."
L["Opacity of the row background."] = "Opacidad del fondo de la fila."
L["Rotated text reads from top to bottom."] = "El texto girado se lee de arriba abajo."
L["Sets the scale of the whole game UI. 0.53 = 0.5333 and 0.71 = 0.7111"] = "Pone la escala de toda la interfaz del juego. 0.53 = 0.5333 y 0.71 = 0.7111"
L["Show Names"] = "Mostrar nombres"
L["Restore My Graphics Settings"] = "Recuperar mis ajustes de gráficos"
L["Put back your graphics from before optimizing."] = "Vuelve a poner tus gráficos de antes de optimizar."
L["Tune graphics for higher FPS and clarity."] = "Ajusta los gráficos para más FPS y más nitidez."
L["What Does This Do?"] = "¿Qué hace esto?"
L["Graphics changed by Optimize My FPS and Graphics stay as they are. To undo them, click Restore My Graphics Settings first."] = "Los gráficos que cambie Optimizar mis FPS y gráficos se quedan así. Para deshacerlo, pulsa antes Recuperar mis ajustes de gráficos."
L["After optimizing, the button changes to 'Restore My Graphics Settings', which reverts every change."] = "Después de optimizar, el botón pasa a ser «Recuperar mis ajustes de gráficos», que deshace todos los cambios."
L["Width matched to %1$s. Unmatch to edit."] = "Anchura igualada a %1$s. Quita la igualación para editarla."
L["Height matched to %1$s. Unmatch to edit."] = "Altura igualada a %1$s. Quita la igualación para editarla."
L["Width matched to %1$s. Unmatch in Unlock Mode to edit."] = "Anchura igualada a %1$s. Quita la igualación en el modo desbloqueo para editarla."
L["Height matched to %1$s. Unmatch in Unlock Mode to edit."] = "Altura igualada a %1$s. Quita la igualación en el modo desbloqueo para editarla."
L["Elements cannot size match to\n%1$s"] = "Los elementos no pueden igualar su tamaño con\n%1$s"
L["Active while Dark Mode is on."] = "Activo mientras el modo oscuro esté activado."
L["Corner Radius"] = "Radio de las esquinas"
L["Rounded Corners"] = "Esquinas redondeadas"
L["This option requires the Solid, Glow or Shadow border style."] = "Esta opción necesita el estilo de borde Sólido, Brillo o Sombra."
L["Junk Marker"] = "Marcar chatarra"
L["Click items to mark or unmark them as junk."] = "Haz clic en los objetos para marcarlos o desmarcarlos como chatarra."
L["Pick up an item, then press the coin to mark it as junk"] = "Coge un objeto y pulsa la moneda para marcarlo como chatarra"
L["Sells all your junk items."] = "Vende toda tu chatarra."
L["Sold %1$d junk item(s)"] = "Vendido(s) %1$d objeto(s) de chatarra"
L["Show a coin on the corner of each junk item's icon."] = "Muestra una moneda en la esquina del icono de cada objeto de chatarra."
L["Choose how junk items look in the bags and bank."] = "Elige cómo se ve la chatarra en las bolsas y el banco."
L["Bank Display"] = "Vista del banco"
L["How items are arranged in the bank window."] = "Cómo se colocan los objetos en la ventana del banco."
L["Compact Display"] = "Vista compacta"
L["Compact"] = "Compacta"
L["Bag Top Bar Icons"] = "Iconos de arriba"
L["Bags Icon"] = "Icono de bolsas"
L["Junk Icon"] = "Icono de chatarra"
L["Sort Icon"] = "Icono de ordenar"
L["Choose which icons show in the bag window's top bar; the Junk Icon is the Junk Marker."] = "Elige qué iconos salen en la barra superior de la ventana de las bolsas; el icono de chatarra es Marcar chatarra."
L["Hide Sidebar Icons When Collapsed"] = "Ocultar iconos si está plegada"
L["Hides a collapsed sidebar; its expand arrow sits by the Inventory title."] = "Oculta la barra lateral plegada; su flecha para desplegarla está junto al título Inventario."
L["Window Lock"] = "Bloquear la ventana"
L["Categories can be dragged\nto reorder them."] = "Las categorías se pueden arrastrar\npara cambiar su orden."
L["Quality Item Border"] = "Borde de calidad"
L["Bag Bar Skin"] = "Aspecto de la barra de bolsas"
L["Micro Menu Skin"] = "Aspecto del micromenú"
L["Same setting as the Bag Bar card on Blizzard Skins+ > Window Skins."] = "Es el mismo ajuste que la tarjeta Barra de bolsas de Blizzard Skins+ > Aspecto de las ventanas."
L["Same setting as the Micro Menu card on Blizzard Skins+ > Window Skins."] = "Es el mismo ajuste que la tarjeta Micromenú de Blizzard Skins+ > Aspecto de las ventanas."
L["Which view bags open to by default."] = "En qué vista se abren las bolsas de forma predeterminada."
L["Hidden Outside Form/Stance"] = "Oculto fuera de la forma/actitud"
L["Type /cd to open Blizzard CDM"] = "/cd abre el CDM de Blizzard"
L["Lets /cd open or close Blizzard's Cooldown Manager settings."] = "Permite que /cd abra o cierre los ajustes del gestor de reutilizaciones de Blizzard."
L["The /cd change applies after a UI reload."] = "El cambio de /cd se aplica al recargar la interfaz."
L["+ Add Class"] = "+ Añadir clase"
L["COMBOS"] = "COMBINACIONES"
L["DEBUFFS"] = "PERJUICIOS"
L["Combos"] = "Combinaciones"
L["A combo holds up to four debuffs."] = "Una combinación tiene hasta cuatro perjuicios."
L["Show Buff / Debuff Tooltips"] = "Ver descr. benef./perj."
L["NAME FORMAT"] = "FORMATO DEL NOMBRE"
L["Name Format"] = "Formato del nombre"
L["Enemy nameplate names and their targets."] = "Nombres de las placas de nombre enemigas y sus objetivos."
L["Friendly player nameplates, in both modes."] = "Placas de nombre de jugadores amistosos, en los dos modos."
L["Raid and party frame names."] = "Nombres de los marcos de banda y de grupo."
L["Player names on the meter bars."] = "Nombres de los jugadores en las barras del medidor."
L["Player names on the threat meter, for all your characters."] = "Nombres de los jugadores en el medidor de amenaza, para todos tus personajes."
L["Every unit frame text that shows a name."] = "Todos los textos de los marcos de unidad que muestran un nombre."
L["Other players' names show in full during combat."] = "Los nombres de los demás jugadores se ven enteros en combate."
L["Checked modules show their first name. A module checked in both lists shows the full name."] = "Los módulos marcados muestran el nombre. Un módulo marcado en las dos listas muestra el nombre completo."
L["Checked modules show their last name. A module checked in both lists shows the full name."] = "Los módulos marcados muestran el apellido. Un módulo marcado en las dos listas muestra el nombre completo."
L["Choose where your combo points show."] = "Elige dónde se ven tus puntos de combo."
L["Class Resource must be set to Blizzard"] = "El recurso de clase tiene que estar en Blizzard"
L["Blizzard's combo points return to its target frame after a UI reload."] = "Los puntos de combo de Blizzard vuelven a su marco del objetivo al recargar la interfaz."
L["Dispel Type Icon"] = "Icono disipación"
L["Pet Frames"] = "Marcos de mascota"
L["Current / Max"] = "Actual / máximo"
L["Choose the specs this action menu works in."] = "Elige en qué especializaciones funciona este menú de acciones."
L["Two action menus can share a keybind when Assign to Spec keeps them from ever loading in the same spec."] = "Dos menús de acciones pueden compartir atajo si Asignar a especialización hace que nunca se carguen en la misma especialización."
L["%1$s now shares %2$s with %3$s."] = "%1$s ahora comparte %2$s con %3$s."
L["%1$s no longer shares the key of %2$s: they can now load in the same spec."] = "%1$s ya no comparte la tecla de %2$s: ahora pueden cargarse en la misma especialización."
L["%1$s share it and will lose it too."] = "%1$s la comparten y también la perderán."
L["%1$s shares it and will lose it too."] = "%1$s la comparte y también la perderá."
L["Shared with %1$s."] = "Compartido con %1$s."
L["and %1$s, which shared it"] = "y %1$s, que lo compartía"
L["Dim Unusable Actions"] = "Atenuar no usables"
L["Dims any actions you can't use right now."] = "Atenúa las acciones que no puedes usar ahora."
L["Hide Unavailable Actions"] = "Ocultar no disponibles"
L["Hides any actions not available to this character."] = "Oculta las acciones que este personaje no tiene."
L["Ignore Older Expansion Quests"] = "Ignorar misiones antiguas"
L["Blessings by Role"] = "Bendiciones por función"
L["Tank Blessing"] = "Bendición del tanque"
L["Healer Blessing"] = "Bendición del sanador"
L["DPS Blessing"] = "Bendición del DPS"
L["Thorns Only on Tank"] = "Thorns solo en el tanque"
L["Thorns shows on tanks only while the group has one, and on you while solo or without a tank."] = "Thorns sale en los tanques solo mientras el grupo tiene uno, y en ti cuando vas solo o sin tanque."
