L["Mini Patch"] = "Parche pequeño"
L["Friends List Tiles"] = "Casillas de amigos"
L["Combo Points Placement"] = "Lugar puntos de combo"

-- == Textos sueltos ========================================================
L["Interruptible While Kick Ready"] = "Interrumpible con interrupción lista"
L["While your interrupt is ready, important casts keep the Interruptible color."] = "Mientras tienes lista tu interrupción, los hechizos importantes mantienen el color de Interrumpible."
L["Cannot open options in combat"] = "No se pueden abrir las opciones en combate"
L["|cffff6060[EllesmereUI]|r Cannot rename to \"Default\"."] = "|cffff6060[EllesmereUI]|r No se puede cambiar el nombre a «Default»."
L["In-game countdown unavailable in combat; the boss mod pull timer still started."] = "La cuenta atrás del juego no está disponible en combate; el temporizador de pull del addon de jefes sí ha empezado."
L["Raid Tools cannot be toggled by slash command in combat -- use the keybind."] = "Las herramientas de banda no se pueden activar con comandos en combate: usa el atajo."
L["Raid Tools is disabled in the EllesmereUI options."] = "Las herramientas de banda están desactivadas en las opciones de EllesmereUI."
L["%d junk item(s) could not be sold."] = "No se ha(n) podido vender %d objeto(s) de chatarra."
L["A preset named \"%1$s\" already exists."] = "Ya hay una plantilla llamada «%1$s»."
L["|cffff6060[EllesmereUI]|r A profile named \"%1$s\" already exists."] = "|cffff6060[EllesmereUI]|r Ya hay un perfil llamado «%1$s»."
L["|cff00ff98EllesmereUI:|r Overrides intro reset. The announcement popup fires on your next /reload; the video guide fires on your next click of the overrides glyph."] = "|cff00ff98EllesmereUI:|r Introducción de los ajustes propios reiniciada. El aviso sale en tu próximo /reload; el vídeo guía, la próxima vez que hagas clic en el símbolo de ajustes propios."
L["|cff00ff98EllesmereUI:|r Video guides and tutorial tips reset. Badges are back; one-time popups will fire again."] = "|cff00ff98EllesmereUI:|r Vídeos guía y consejos reiniciados. Las insignias vuelven; los avisos de una sola vez saldrán otra vez."
L["|cffff6060[EllesmereUI]|r Spec changed: Unlock Mode closed, unsaved layout changes discarded."] = "|cffff6060[EllesmereUI]|r Has cambiado de especialización: se ha cerrado el modo desbloqueo y se han descartado los cambios de disposición sin guardar."
L["|cffff6060[EllesmereUI]|r Cannot enter Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r No se puede entrar en el modo desbloqueo en combate."
L["|cff00ff00[EllesmereUI]|r All hints reset. /reload to see them again."] = "|cff00ff00[EllesmereUI]|r Todos los consejos reiniciados. Haz /reload para volver a verlos."
L["|cff00ff00[EllesmereUI]|r UI scale reset. /reload to re-snapshot from your Blizzard scale."] = "|cff00ff00[EllesmereUI]|r Escala de la interfaz reiniciada. Haz /reload para volver a tomarla de tu escala de Blizzard."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat. Use /eui to view Patch Notes."] = "|cffff6060[EllesmereUI]|r No se pueden abrir las opciones en combate. Usa /eui para ver las notas de la versión."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat."] = "|cffff6060[EllesmereUI]|r No se pueden abrir las opciones en combate."
L["|cff0cd29fEllesmereUI CDM:|r Cooldown Viewer settings are managed by EllesmereUI. Edit Mode changes are disabled."] = "|cff0cd29fEllesmereUI CDM:|r Los ajustes del visor de reutilizaciones los controla EllesmereUI. Los cambios del modo edición están desactivados."
L["Raid Tools is hidden in a raid without leader or assist -- none of its buttons work there."] = "Las herramientas de banda se ocultan en una banda si no eres líder ni ayudante: allí no funciona ninguno de sus botones."
L["Instance has been reset - you can re-enter now!"] = "La instancia se ha reiniciado: ¡ya podéis volver a entrar!"
L["Reset failed - there are still players inside the instance."] = "No se ha podido reiniciar: todavía hay jugadores dentro de la instancia."
L["Apply End Caps to all Bars"] = "Aplicar los remates a todas las barras"
L["Apply Show Bar Background to all Bars"] = "Aplicar Mostrar el fondo de la barra a todas las barras"
L["Micro Menu End Caps"] = "Remates del micromenú"
L["End Caps"] = "Remates"
L["Left Endcap"] = "Remate izquierdo"
L["Right Endcap"] = "Remate derecho"
L["Bag Bar End Caps"] = "Remates de la barra de bolsas"
L["Show the frame and dividers behind the bar's buttons."] = "Muestra el marco y los separadores detrás de los botones de la barra."
L["Modern shows gryphons or wyverns by faction, Classic the vanilla gryphons, WoW Forever this client's own."] = "Moderno muestra grifos o dracoleones según la facción; Clásico, los grifos del juego original; WoW Forever, los propios de este cliente."
L["Rotation Assist Icon"] = "Icono de rotación"
L["ROTATION ASSIST ICON"] = "ICONO DE LA AYUDA DE ROTACIÓN"
L["Show Rotation Assist Icon"] = "Mostrar icono de rotación"
L["Only in Combat"] = "Solo en combate"
L["Show GCD"] = "Mostrar GCD"
L["Highlight Blizzard's next recommended ability on all CDM bars. Requires Assisted Highlight to be enabled in Blizzard's options. Disabling this hides only the CDM highlight.\n\nPress the normal ability's keybind yourself. This does not cast spells or use the Single-Button Assistant, so it does not add that assistant's global cooldown penalty. Only abilities present on your CDM bars can be highlighted."] = "Resalta en todas las barras del CDM la siguiente facultad que recomienda Blizzard. Necesita que la Ayuda resaltada esté activada en las opciones de Blizzard. Si lo desactivas, solo se oculta el resaltado del CDM.\n\nPulsa tú el atajo normal de la facultad. Esto no lanza hechizos ni usa el asistente de un botón, así que no añade el castigo de tiempo de reutilización global de ese asistente. Solo se pueden resaltar las facultades que están en tus barras del CDM."
L["Show Blizzard's current recommendation in a separate icon. Requires Assisted Highlight to be enabled in Blizzard's options. Press the spell's normal keybind; this display never casts spells. Blizzard supplies one recommendation, not a queue of future casts."] = "Muestra en un icono aparte la recomendación actual de Blizzard. Necesita que la Ayuda resaltada esté activada en las opciones de Blizzard. Pulsa el atajo normal del hechizo; esto nunca lanza hechizos. Blizzard da una sola recomendación, no una cola de los siguientes hechizos."
L["Show the global cooldown as a swipe over the recommended ability. The swipe shows when the GCD ends; casting, channeling and ability requirements can still delay your next action."] = "Muestra el tiempo de reutilización global como un barrido sobre la facultad recomendada. El barrido muestra cuándo acaba el GCD; lanzar, canalizar y lo que pide cada facultad pueden retrasar aún tu siguiente acción."
L["Hide outside combat. Unlock Mode shows a placeholder when no recommendation is available."] = "Oculto fuera de combate. El modo desbloqueo muestra un hueco cuando no hay recomendación."
L["Horizontal screen offset. You can also drag the Rotation Assist Icon in Unlock Mode."] = "Desplazamiento horizontal en pantalla. También puedes arrastrar el icono de la ayuda de rotación en el modo desbloqueo."
L["Vertical screen offset. You can also drag the Rotation Assist Icon in Unlock Mode."] = "Desplazamiento vertical en pantalla. También puedes arrastrar el icono de la ayuda de rotación en el modo desbloqueo."
L["Use the CDM keybind mapping. Configure the font, outline, position, background and border with the cog."] = "Usa los atajos del CDM. Configura la fuente, el contorno, la posición, el fondo y el borde con el engranaje."
L["Set opacity to 0% for text without a background."] = "Con la opacidad al 0% falta el fondo del texto."
L["Set opacity to 0% to hide the keybind badge border."] = "Pon la opacidad en 0% para ocultar el borde de la insignia del atajo."
L["Show this icon only while the talents you pick are taken, or not taken."] = "Muestra este icono solo mientras tienes, o no tienes, los talentos que elijas."
L["Click a talent to require it: Taken, then Not Taken, then cleared. Every condition must hold for the icon to show."] = "Haz clic en un talento para exigirlo: Lo tienes, luego No lo tienes y luego se quita. Todas las condiciones se tienen que cumplir para que se vea el icono."
L["Shown only while this talent is taken"] = "Solo se ve mientras tienes este talento"
L["Shown only while this talent is NOT taken"] = "Solo se ve mientras NO tienes este talento"
L["Conditions on talents not shown above (they still apply):"] = "Condiciones de talentos que no salen arriba (se siguen aplicando):"
L["Unknown talent"] = "Talento desconocido"
L["Talent data is not available right now."] = "Los datos de talentos no están disponibles ahora."
L["Include Reagent Bag"] = "Incluir la bolsa de componentes"
L["Open Bank Slots"] = "Huecos libres del banco"
L["Counts the reagent bag's slots along with your regular bags."] = "Cuenta los huecos de la bolsa de componentes junto con tus bolsas normales."
L["Shows the bag icon next to the slot count."] = "Muestra el icono de la bolsa junto al número de huecos."
L["Your base bank slots come with a free bank tab. Open it once to start using your bank."] = "Tus huecos básicos del banco vienen con una pestaña de banco gratis. Ábrela una vez para empezar a usar el banco."
L["Gamepad"] = "Mando"
L["Everything here applies only while a controller is connected and WoW's gamepad mode is on."] = "Todo lo de aquí solo se aplica mientras hay un mando conectado y el modo mando de WoW está activado."
L["Checked bars hide while a controller is connected and gamepad mode is on, the way Visibility set to Never hides them."] = "Las barras marcadas se ocultan mientras hay un mando conectado y el modo mando está activado, como si su visibilidad estuviera en Nunca."
L["Mouse and keyboard play is unaffected."] = "Jugar con ratón y teclado no cambia."
L["Hide Action Bars"] = "Ocultar barras de acción"
L["Hidden bars still show in Quick Keybind mode so you can bind them."] = "Las barras ocultas se siguen viendo en el modo de atajo de teclado rápido para poder asignarlas."
L["CAST BARS"] = "BARRAS DE HECHIZOS"
L["Hide Unit Frames Cast Bar"] = "Ocultar barra hech. marcos"
L["Hide Resource Bars Cast Bar"] = "Ocultar barra hech. recursos"
L["Hides the Resource & Cast Bars cast bar while a controller is connected and gamepad mode is on. Blizzard's gamepad interface shows its own."] = "Oculta la barra de hechizos de Barras de recursos y de hechizos mientras hay un mando conectado y el modo mando está activado. La interfaz de mando de Blizzard muestra la suya."
L["This option requires the cast bar in Resource & Cast Bars to be enabled"] = "Esta opción necesita que la barra de hechizos de Barras de recursos y de hechizos esté activada"
L["Elite Enemy Dragon"] = "Dragón de enemigos de élite"
