L["Dragon Frame Level"] = "Nivel del marco del dragón"
L["Curls a gold dragon around the portrait of elite and boss enemies, and a silver one around rares."] = "Enrosca un dragón dorado alrededor del retrato de los enemigos de élite y los jefes, y uno plateado alrededor de los raros."
L["Also show the dragon in dungeons and raids, where most enemies are elite."] = "Muestra el dragón también en mazmorras y bandas, donde casi todos los enemigos son de élite."
L["TIMER BAR"] = "BARRA DEL TEMPORIZADOR"
