L["Add a Great Vault button to the Season Panel."] = "Añade un botón de la gran cámara al panel de temporada."
L["Adds diminishing returns info to Secondary and Tertiary stat tooltips."] = "Añade información de rendimiento decreciente a las descripciones de las estadísticas secundarias y terciarias."
L["Hovering a Secondary or Tertiary stat highlights the gear that has it."] = "Al pasar el ratón por una estadística secundaria o terciaria se resalta el equipo que la tiene."
L["How Secondary and Tertiary stat values are shown."] = "Cómo se muestran los valores de las estadísticas secundarias y terciarias."
L["Secondary Stats or Tertiary Stats"] = "Estadísticas secundarias o terciarias"
L["Choose Stats..."] = "Elegir estadísticas..."
L["Reorder Shown Stats"] = "Ordenar estadísticas"
L["Keeps this bar on its page while skyriding."] = "Mantiene esta barra en su página mientras vas en surcacielos."
L["Shows a button next to the bar that lands you at the next flight point."] = "Muestra un botón junto a la barra que te hace aterrizar en el siguiente punto de vuelo."
L["Where the enemy forces percentage is shown: in the label text, in the bar or beside it."] = "Dónde se muestra el porcentaje de fuerzas enemigas: en el texto de la etiqueta, en la barra o a su lado."
L["Which side of each boss objective shows its split times and Split Compare text."] = "En qué lado de cada objetivo de jefe se muestran sus tiempos parciales y el texto de Comparar tiempos parciales."
L["Texture of the enemy forces bar. The swatches next to it set the Enemy Bar Color (theme accent or a custom color)."] = "Textura de la barra de fuerzas enemigas. Las muestras de color de al lado ponen el color de la barra de enemigos (el acento del tema o un color propio)."
L["Align the timer text to the left edge of the bar instead of centering it."] = "Alinea el texto del temporizador al borde izquierdo de la barra en lugar de centrarlo."
L["Fades the timer in at takeoff and out on landing."] = "Hace aparecer el temporizador al despegar y desaparecer al aterrizar."
L["Minimum height of the timer bar while the timer is inside it. The larger of this and Timer Bar Height is used."] = "Altura mínima de la barra del temporizador mientras el temporizador está dentro. Se usa la mayor entre esta y Altura de la barra del temporizador."
L["Opacity of the bar fill while the timer is inside it."] = "Opacidad del relleno de la barra mientras el temporizador está dentro."
L["Cannot open the Cooldown Manager during combat."] = "No se puede abrir el gestor de reutilizaciones en combate."
L["Cannot open the Cooldown Manager with the Gamepad interface style."] = "No se puede abrir el gestor de reutilizaciones con el estilo de interfaz de mando."
L["Disable the Cooldown State glow first"] = "Desactiva antes el brillo del estado de reutilización"
L["Glows on action bar and CDM buttons while a tracked buff is active (or missing), set per entry on the Bar Glows page. Counted for the current specialization; the template never changes them."] = "Brillos en los botones de las barras de acción y del CDM mientras un beneficio seguido está activo (o falta), configurados por entrada en la página Brillos de barras. Se cuentan para la especialización actual; la plantilla nunca los cambia."
L["Proc Glow, Active State Glow, Max Charges Glow, Buff Glow, CD Ready Glow and Glow Effect Color can be set per icon: right-click an icon in the CDM Bars preview. Counted for the current specialization; the template never changes them."] = "Brillo de proc, Brillo del estado activo, Brillo con cargas máximas, Brillo del beneficio, Brillo de reutilización lista y Color del efecto de brillo se pueden configurar por icono: clic derecho en un icono de la vista previa de las barras del CDM. Se cuentan para la especialización actual; la plantilla nunca los cambia."
L["Mythic raids allow only 20 players (groups 1-4), so hide groups 5-8 while inside one. Groups 1-4 still follow Show Groups, and Show Groups applies as normal everywhere else."] = "Las bandas míticas solo admiten 20 jugadores (grupos 1-4), así que oculta los grupos 5-8 mientras estás en una. Los grupos 1-4 siguen Mostrar grupos, y Mostrar grupos se aplica como siempre en todas las demás partes."
L["Environment Ping"] = "Aviso de entorno"
L["While held, left-clicking the world sends a ping that ignores units and only targets the environment.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Mientras lo mantienes, el clic izquierdo en el mundo envía un aviso que no tiene en cuenta las unidades y solo marca el entorno.\n\nClic izquierdo para asignar un atajo.\nClic derecho para quitarlo."
L["Swaps new spell ranks onto your action bars."] = "Pone los rangos nuevos de los hechizos en tus barras de acción."
L["Upranked %s on 1 action slot."] = "%s subido de rango en 1 hueco de acción."
L["Upranked %1$s on %2$d action slots."] = "%1$s subido de rango en %2$d huecos de acción."
L["5-Second Rule sweeps a spark across the bar for 5 seconds after you spend mana, until mana regen resumes. Regen Ticks then keeps sweeping every 2 seconds while mana regenerates."] = "La regla de los 5 segundos hace pasar una chispa por la barra durante 5 segundos después de gastar maná, hasta que vuelve la regeneración de maná. Marcas de regeneración sigue haciéndola pasar cada 2 segundos mientras se regenera el maná."
L["Shows Sunder Armor and its stacks on enemy nameplates, including stacks applied by other warriors."] = "Muestra Sunder Armor y sus acumulaciones en las placas de nombre enemigas, también las que ponen otros guerreros."
L["Loot Feed"] = "Lista de botín"
L["Shows what you loot and gain as short-lived rows that fade out."] = "Muestra lo que despojas y consigues en filas que duran poco y se van apagando."
L["0 hides the accent bar."] = "0 oculta la barra de acento."
L["0 hides the border."] = "0 oculta el borde."
L["Shows a sample row for every enabled source."] = "Muestra una fila de ejemplo por cada fuente activada."
L["Reskins Blizzard's call totem bar in this look and moves it with Unlock Mode instead of Edit Mode."] = "Cambia el aspecto de la barra de llamar tótems de Blizzard a este estilo y la mueve con el modo desbloqueo en lugar de con el modo edición."
