L["A bright, minimalist layout with a clean aesthetic. Crafted for any role with clear information and a calm but focused feel."] = "Una disposición clara y minimalista, con un aspecto limpio. Hecha para cualquier función, con información clara y una sensación tranquila pero centrada."
L["A clean minimal setup"] = "Una configuración limpia y mínima"
L["A dark, elegant healing setup built around raid frames and a clean display of information to help keep your team alive at a glance."] = "Una configuración de sanador oscura y elegante, pensada alrededor de los marcos de banda y con la información limpia para mantener a tu equipo con vida de un vistazo."
L["A new Use Modifier option makes the spell and item ID lines on tooltips appear only while you hold Shift, Control, or Alt."] = "Una opción nueva, Usar tecla modificadora, hace que las líneas de ID de hechizo y de objeto de las descripciones solo salgan mientras mantienes Mayús, Ctrl o Alt."
L["A simple Mythic+ timer with full tracking customizations."] = "Un temporizador de mítica+ sencillo con todas las opciones de seguimiento."
