L["Espanol (EU)"] = "Español (UE)"
L["Espanol (LatAm)"] = "Español (Latam)"
L["EUI Architect"] = "Arquitecto de EUI"
L["EUI: Combat Reload UI Warning:\nDrop combat to fix any layout issues"] = "EUI: aviso de recarga en combate:\nsal de combate para arreglar los problemas de disposición"
L["Export Full Profile"] = "Exportar perfil completo"
L["Export Selected Addons"] = "Exportar addons elegidos"
L["Export your current profile."] = "Exporta tu perfil actual."
L["Failed to encode import data."] = "No se han podido codificar los datos de importación."
L["Francais"] = "Français"
L["Invalid preset data."] = "Datos de plantilla no válidos."
L["Shows start as a small icon, and the keybind switches between the icon and the full windows. Turn off to show full windows and make the keybind hide and show them."] = "Empieza como un icono pequeño, y el atajo cambia entre el icono y las ventanas completas. Desactívalo para ver las ventanas completas y que el atajo las oculte y las muestre."
L["One Window combines everything into a single element; the Only choices show just that part."] = "Una ventana junta todo en un solo elemento; las opciones «Solo» muestran solo esa parte."
L["Vanilla WoW art joins EllesmereUI Style and Blizzard Style as a third look, keeping EllesmereUI's features. Raid Frames, Chat, Quest Tracker, Friends List and the Character Sheet gain the stock looks too; pick per module or for the whole UI under Global Settings > Style."] = "El dibujo de WoW clásico se suma al estilo de EllesmereUI y al de Blizzard como tercer aspecto, con las funciones de EllesmereUI. Los marcos de banda, el chat, el seguimiento de misiones, la lista de amigos y la hoja del personaje también tienen el aspecto original; elígelo por módulo o para toda la interfaz en Ajustes globales > Estilo."
L["Border Size is now an exact pixel slider across the suite, so Shadow, Glow and Blizzard borders take any size. Width and Height Match now line up by the visible border edge, so an existing match to a textured border may resize slightly."] = "El tamaño del borde ahora es un control exacto en píxeles en todo el addon, así que los bordes de sombra, brillo y Blizzard admiten cualquier tamaño. Igualar anchura y altura ahora alinean por el borde visible, así que una igualación que ya tengas con un borde con textura puede cambiar un poco de tamaño."
L["Party frames can show a 2D or 3D portrait or class art in seven sets, attached beside the bars or detached from the frame. Off by default on the Party tab and works with every style; Detached adds seven shapes, and 3D can also sit inside the frame."] = "Los marcos de grupo pueden mostrar un retrato 2D o 3D o dibujo de clase en siete juegos, unido junto a las barras o separado del marco. Desactivado de forma predeterminada en la pestaña Grupo y funciona con todos los estilos; Separado añade siete formas, y el 3D también puede ir dentro del marco."
L["A flight path bar that names your destination and counts down the time left, from the route's length, Frequent Flier and a flight speed refined by each flight. Off by default on the new Travel tab, with size, texture, border, fill colour, text and font options plus Unlock Mode placement."] = "Una barra de ruta de vuelo que dice tu destino y cuenta atrás el tiempo que falta, según el largo de la ruta, Viajero frecuente y una velocidad de vuelo que se afina en cada vuelo. Desactivada de forma predeterminada en la pestaña nueva Viaje, con opciones de tamaño, textura, borde, color de relleno, texto y fuente, y se coloca en el modo desbloqueo."
L["Everything from retail, ported to WoW Forever and tuned for the vanilla client, with a clean base layout the moment you log in. One EllesmereUI: the same install runs on either game."] = "Todo lo de retail, llevado a WoW Forever y ajustado para el cliente clásico, con una disposición base limpia nada más entrar. Un solo EllesmereUI: la misma instalación funciona en los dos juegos."
L["Give any module the default Blizzard look while keeping EllesmereUI features and customization: Unit Frames, Auras, Nameplates, CDM, Resource Bars, Minimap and Damage Meters all join the Action Bars, each with its own switch under Global Settings > Style."] = "Da a cualquier módulo el aspecto predeterminado de Blizzard sin perder las funciones ni la personalización de EllesmereUI: marcos de unidad, auras, placas de nombre, CDM, barras de recursos, minimapa y medidores de daño se unen a las barras de acción, cada uno con su propio interruptor en Ajustes globales > Estilo."
L["An end-of-key overview of your group with one row per member: spec, item level, score and score gain, loot, damage, damage taken, interrupts and deaths, sortable by column. Off by default; a per-character run history keeps your recent keys, and /ov reopens the panel."] = "Un resumen del grupo al terminar la llave, con una fila por miembro: especialización, nivel de objeto, puntuación y lo ganado, botín, daño, daño recibido, interrupciones y muertes, que se puede ordenar por columna. Desactivado de forma predeterminada; un historial por personaje guarda tus últimas llaves, y /ov vuelve a abrir el panel."
L["Restyle the chat bubbles over players' and NPCs' heads with your own background, border, font and colors for the channels you pick. Inside instances the game's own bubbles stay, with an option to hide them there; the whole feature is off by default."] = "Cambia el estilo de los bocadillos de chat sobre las cabezas de jugadores y PNJ con tu propio fondo, borde, fuente y colores en los canales que elijas. Dentro de instancias se quedan los bocadillos del juego, con opción de ocultarlos allí; toda la función está desactivada de forma predeterminada."
L["Shift-clicking a stack in All Items / Category views lets you split it up or even Auto Split to keep splitting into empty slots until only the amount you chose remains. Split stacks in All Items / Category views re-merge once the bags close and reopen (they stay split in OneBag/MultiBag)."] = "Mayús + clic en un montón en las vistas Todos los objetos / por categoría te deja dividirlo, o incluso usar División automática para ir dividiéndolo en huecos vacíos hasta que solo quede la cantidad que elijas. Los montones divididos en esas vistas se vuelven a juntar al cerrar y abrir las bolsas (en OneBag/MultiBag siguen divididos)."
L["A cooldown icon can show a tracked buff in its slot while that buff is active, then return to the cooldown when it ends. Pick the buff from the icon's right-click menu on any cooldown or utility bar."] = "Un icono de reutilización puede mostrar un beneficio seguido en su hueco mientras está activo, y volver a la reutilización cuando acaba. Elige el beneficio en el menú del clic derecho del icono en cualquier barra de reutilizaciones o de utilidad."
L["Debuff filters on Player Aura Bars, Raid Frames and the player frame gain a Less Common Filters section: Cast By Me, Any Player, Magic, Curse, Poison, Disease, Bleed and Can Apply. A new Max Duration dropdown beside Filters keeps long debuffs off Player Aura Bars and Raid Frames."] = "Los filtros de perjuicios de las barras de auras del jugador, los marcos de banda y el marco del jugador ganan una sección de filtros menos habituales: Lanzados por mí, Cualquier jugador, Magia, Maldición, Veneno, Enfermedad, Sangrado y Puedes aplicarlo. Una lista nueva de Duración máxima junto a Filtros deja los perjuicios largos fuera de las barras de auras del jugador y de los marcos de banda."
L["Bank Organization"] = "Organización del banco"
L["The bank window catches up to the bags: nest OneBank and OneWarbank by expansion, group items by your bag categories with automatic splits by equipment slot, profession and material, and browse a category sidebar that spans your character bank and warband together."] = "La ventana del banco se pone al día con las bolsas: agrupa OneBank y OneWarbank por expansión, agrupa los objetos por tus categorías de bolsas con divisiones automáticas por hueco de equipo, profesión y material, y recorre una barra lateral de categorías que abarca a la vez el banco del personaje y el de la banda guerrera."
L["Handcrafted UI setups ready to import."] = "Configuraciones de interfaz hechas a mano listas para importar."
L["Import 1080p"] = "Importar 1080p"
L["Import 2K (1440p)"] = "Importar 2K (1440p)"
L["Modern Icons"] = "Iconos modernos"
L["Not Available Yet"] = "Aún no disponible"
L["Per-Addon Export"] = "Exportar por addon"
L["Portugues (BR)"] = "Português (BR)"
L["Position/size data cannot be synced across profiles due to Unlock Mode systems like anchoring, width/height matching and growth direction. This addon's sync is purely for settings that do not impact position, sizing or anchors."] = "Los datos de posición y tamaño no se pueden sincronizar entre perfiles por los sistemas del modo desbloqueo, como el anclaje, la igualación de anchura/altura y la dirección de crecimiento. La sincronización de este addon es solo para ajustes que no afectan a la posición, el tamaño ni las anclas."
L["Preset Profile"] = "Plantilla de perfil"
L["Profiles Synced"] = "Perfiles sincronizados"
L["Select Module"] = "Elegir módulo"
L["Spec Macros are currently not supported\nfor non-English clients. Support coming soon!"] = "Las macros por especialización aún no funcionan\nen clientes que no están en inglés. ¡Pronto!"
L["The damage dealer cut of Midnight Lily. A focused, low-clutter layout that keeps your rotation and cooldowns front and center."] = "La versión de daño de Midnight Lily. Una disposición centrada y despejada que deja tu rotación y tus reutilizaciones a la vista."
L["The signature EllesmereUI layout exactly as designed. Vibrant class colors, clear cd tracking, and every module working in harmony."] = "La disposición característica de EllesmereUI tal y como se diseñó. Colores de clase vivos, seguimiento claro de reutilizaciones y todos los módulos funcionando en armonía."
L["This preset"] = "Esta plantilla"
L["Add Module Font"] = "Añadir fuente de módulo"
L["EUI Options Scale"] = "Escala opciones EUI"
L["Export settings for specific addons only. You can choose which addons to include in your exported profile."] = "Exporta los ajustes solo de algunos addons. Puedes elegir qué addons incluir en el perfil exportado."
L["Open it anytime from Global Settings > Patch Notes."] = "Ábrelo cuando quieras desde Ajustes globales > Novedades."
L["What we change:\n\nShadow Quality - Fair (balanced quality/FPS)\nLiquid Detail - Disabled\nParticle Density - Set to Ultra (keeps important spell effects)\nSSAO (Ambient Occlusion) - Disabled\nDepth Effects - Disabled\nCompute Effects - Disabled\nOutline Mode - Disabled\nTexture Resolution - Set to High\nSpell Density - Set to Essential\nProjected Textures - Enabled (needed for ground effects)\nView Distance - Reduced to 1\nEnvironment Detail - Reduced to 1\nGround Clutter - Reduced to 1\nRaid/Dungeon Settings - Uses same settings everywhere\nResample Sharpening - Enabled (crisper image)\nContrast - Boosted by +10 (if currently 55 or below)\nEnable Reverb - Disabled (spell and interrupt audio cues stay crisp)\n\nThese settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Lo que cambiamos:\n\nCalidad de sombras: Medio (equilibrio entre calidad y FPS)\nDetalles de líquidos: desactivado\nDensidad de partículas: Máx. (mantiene los efectos de hechizos importantes)\nSSAO (oclusión ambiental): desactivado\nEfectos de profundidad: desactivado\nEfectos de computación: desactivado\nModo de contorno: desactivado\nResolución de texturas: Alto\nDensidad de hechizos: Esenciales\nTexturas proyectadas: activado (necesario para los efectos en el suelo)\nDistancia de visión: bajada a 1\nDetalle del entorno: bajado a 1\nDetalles del suelo: bajado a 1\nAjustes de banda/mazmorra: los mismos en todas partes\nReajustar nitidez: activado (imagen más nítida)\nContraste: +10 (si ahora está en 55 o menos)\nActivar reverberación: desactivado (los sonidos de hechizos e interrupciones se oyen limpios)\n\nEstos ajustes dan prioridad a los FPS y a la claridad por encima del detalle del entorno. Las texturas se quedan en calidad alta para que tu personaje y el mundo se sigan viendo perfectos."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally ~150 for melee and ~300 for casters. Higher if you have high local ping."] = "Es la ventana de cola de hechizos: evita que puedas encolar demasiados hechizos a la vez, lo que hace que el juego parezca ir con retraso. Lo recomendado suele ser unos 150 para cuerpo a cuerpo y unos 300 para lanzadores de hechizos. Más si tienes mucho ping local."
L["This will not reset addon-specific Quick Setup."] = "Esto no restablece la configuración rápida de cada addon."
L["Your game client language uses a system font automatically.\nFont selection is not available for this locale."] = "El idioma de tu cliente usa una fuente del sistema automáticamente.\nNo se puede elegir fuente en este idioma."
L["EllesmereUI Basics has been split into separate addons. Since you had Basics disabled, Minimap, Friends, and Quest Tracker have been disabled to match. A reload is required to apply this change."] = "EllesmereUI Basics se ha dividido en addons separados. Como tenías Basics desactivado, se han desactivado también Minimapa, Amigos y Seguimiento de misiones. Hay que recargar para aplicar este cambio."
L["Are you sure you want to reset all %s settings to their defaults? This will reload your UI."] = "¿Seguro que quieres volver a poner todos los ajustes de %s como vienen? Se recargará la interfaz."
L["Elements cannot be anchored to\n%s"] = "Los elementos no se pueden anclar a\n%s"
L["This will overwrite %1$s settings on the selected profiles with your current settings. Continue?"] = "Esto sobrescribe los ajustes de %1$s de los perfiles elegidos con tus ajustes actuales. ¿Continuar?"
