L["Remove Advanced Spec"] = "Quitar espec. avanzada"
L["Show Guild Rank"] = "Ver rango hermandad"
L["Show Mount"] = "Ver montura"
L["Show Player Titles"] = "Ver títulos jugador"
L["Tooltip Content"] = "Contenido descr."
L["Top Icon Size"] = "Tam. icono arriba"
L["Combines with conditions: shows on hover only while they pass."] = "Se combina con las condiciones: solo se ve al pasar el ratón mientras se cumplen."
L["Conditions of the same kind are OR'd together; different kinds must all match. Mouseover combines as a hover gate."] = "Las condiciones del mismo tipo se unen con «o»; las de tipos distintos se tienen que cumplir todas. Al pasar el ratón se combina como una condición más."
L["Only while airborne on a skyriding mount."] = "Solo mientras vas en el aire en una montura de surcacielos."
L["Reverse the order of buttons on this bar."] = "Invierte el orden de los botones de esta barra."
L["This option requires a custom glow to be selected"] = "Esta opción necesita elegir un brillo personalizado"
L["Toggles Blizzard's Show Numbers for Cooldowns setting (the countdownForCooldowns CVar) live. This is never saved to EllesmereUI -- it is the same as changing the option in Blizzard's settings."] = "Activa o desactiva al momento el ajuste Mostrar números de reutilización de Blizzard (la variable countdownForCooldowns). Nunca se guarda en EllesmereUI: es igual que cambiar la opción en los ajustes de Blizzard."
L["Mouse Button %d"] = "Botón del ratón %d"
L["Aura Duration Settings"] = "Ajustes duración auras"
L["Enable Cast Timer"] = "Activar tiempo hech."
L["Enable Stacking Nameplates"] = "Activar placas apiladas"
L["Name Only Settings"] = "Ajustes solo nombre"
L["Show All Your Player Debuffs"] = "Ver todos tus perj."
L["Show Tick at Kick Ready Spot"] = "Marca de interrupción lista"
L["Test Spell"] = "Hechizo de prueba"
L["Use Dispel Type Color"] = "Color de disipación"
L["Aura Duration"] = "Duración auras"
L["Disabled when Enemy Name is centered on the health bar due to overlapping text"] = "Desactivado cuando el nombre del enemigo está centrado en la barra de salud, porque los textos se pisarían"
L["Dispel Glow Style"] = "Estilo brillo disipación"
L["Open World Basic Coloring"] = "Colores básicos en el mundo"
L["Pandemic Glow Style"] = "Estilo brillo pandemia"
L["Vibrant"] = "Vivo"
L["Apply this pandemic glow to all CDM bars and tracking bars. A surface that can't show a style uses its closest match."] = "Aplica este brillo de pandemia a todas las barras del CDM y a las barras de seguimiento. Donde no se pueda mostrar un estilo, se usa el más parecido."
L["Controls the highlight shown over a nameplate when you mouse over it. Set to 0 to disable."] = "Controla el resaltado que se ve sobre una placa de nombre al pasar el ratón. Pon 0 para desactivarlo."
L["On quest mobs in the open world, replaces the quest icon with the objective progress (a kill quest shows 0/6, a percentage quest shows 50%). Falls back to the icon when no progress is available. Never shown in instances."] = "En las criaturas de misión del mundo abierto, cambia el icono de misión por el progreso del objetivo (una misión de matar muestra 0/6; una de porcentaje, 50%). Si no hay progreso, usa el icono. Nunca se muestra en instancias."
L["Show the player's title or guild in a smaller line below their name on friendly nameplates."] = "Muestra el título o la hermandad del jugador en una línea más pequeña debajo de su nombre en las placas de nombre amistosas."
L["This option is currently under maintenance"] = "Esta opción está ahora en mantenimiento"
L["This will display ALL of your debuffs on enemy nameplates, rather than only the important ones."] = "Muestra TODOS tus perjuicios en las placas de nombre enemigas, no solo los importantes."
L["When enabled, nameplates stack vertically instead of overlapping."] = "Si lo activas, las placas de nombre se apilan en vertical en lugar de solaparse."
L["Colors the full-size spell icon border with your target border color while the cast bar wrap border is active."] = "Pone el color del borde del objetivo al borde del icono del hechizo a tamaño completo mientras el borde que rodea la barra de hechizos está activo."
L["Disable Show All Enemy Buffs"] = "Desactivar ver todos los benef. enemigos"
L["Dispel Glow may cause a slight loss in performance efficiency. Do you want to enable it?"] = "El brillo de disipación puede bajar un poco el rendimiento. ¿Quieres activarlo?"
L["Applies to: "] = "Se aplica a: "
L["Apply All Settings To"] = "Aplicar todos los ajustes a"
L["Bar Background Color"] = "Color fondo barra"
L["Cast Text"] = "Texto hechizo"
L["Enable Private Auras"] = "Activar auras privadas"
L["Enable Styled Buffs & Debuffs"] = "Benef./perj. con estilo"
L["hide if no target behaves inverted"] = "«ocultar sin objetivo» va al revés"
L["No Border on Debuffs"] = "Perj. sin borde"
L["Power Border Offset"] = "Desp. borde poder"
