L["\n|cff66ccffDrag to reorder.\nRight-click to change action.\nMiddle-click to remove.\nDrop an action here to replace it.|r"] = "\n|cff66ccffArrastra para cambiar el orden.\nClic derecho para cambiar la acción.\nClic central para quitarla.\nSuelta aquí una acción para sustituirla.|r"
L["Wrong Pet (Demo Lock)"] = "Mascota equivocada (Demo)"
L["When on, flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Si lo activas, los recordatorios de frasco, comida y arma siguen saliendo (más apagados) cuando no tienes el objeto en las bolsas, para que repongas.\nSi lo desactivas, no salen si no llevas el objeto."
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire. Build up to 16 menus in Arc, Fan, or Grid layouts, nest menus inside menus, and tune every setting per menu."] = "Mantén pulsado un atajo para abrir un menú de acciones; apunta o mueve la rueda para elegir y suelta para usarla. Crea hasta 16 menús con disposición en arco, abanico o cuadrícula, mete menús dentro de menús y ajusta cada opción por menú."
L["The gap between a nested menu's icons and the entry that opens it."] = "El espacio entre los iconos de un submenú y la entrada que lo abre."
L["Dim Unusable Entries"] = "Atenuar no usables"
L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "Tiñe una entrada que ahora no haría nada: rojo si el objetivo está fuera de alcance, azul si te falta el recurso y gris si el juego no la deja por otro motivo. Solo hechizos y objetos: el juego dice que todos los juguetes no se pueden usar, y si una macro se puede usar depende de lo que haga."
L["How many entries a row of the grid holds. 1 stacks them into a single column; %1$s -- the most slots an action menu can hold -- lays them out in a single row."] = "Cuántas entradas tiene una fila de la cuadrícula. 1 las pone en una sola columna; %1$s (lo máximo que admite un menú de acciones) las pone en una sola fila."
L["Delete %1$s and its contents? Entries in other action menus that open it are removed too, and the menus after it move up one place."] = "¿Borrar %1$s y su contenido? También se quitan las entradas de otros menús de acciones que lo abren, y los menús que van detrás suben un puesto."
L["Keep this menu open when you let go of its keybind.\nPoint at an entry and press the Select Action key to use it.\nPress the menu's own keybind again, or Escape, to close it."] = "Mantiene este menú abierto al soltar su atajo.\nApunta a una entrada y pulsa la tecla Elegir acción para usarla.\nPulsa otra vez el atajo del menú, o Esc, para cerrarlo."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Usa la entrada a la que apuntas mientras un menú está abierto con Abrir y cerrar el menú. Una sola tecla para todos los menús, que solo se usa mientras hay un menú abierto: un botón del ratón sigue haciendo lo de siempre el resto del tiempo.\n\nClic izquierdo para asignar un atajo y luego pulsa cualquier tecla o\nhaz clic con cualquier botón del ratón para usarlo.\nEsc cancela. Clic derecho aquí para quitarlo."
L["Left-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Clic izquierdo para asignar un atajo y luego pulsa cualquier tecla o\nhaz clic con cualquier botón del ratón para usarlo.\nEsc cancela. Clic derecho aquí para quitarlo."
L["Hide entries this character cannot use: another class's specializations and spells, and macros this character does not have. One shared menu then fits every character. The menu editor always shows every entry."] = "Oculta las entradas que este personaje no puede usar: especializaciones y hechizos de otras clases y macros que este personaje no tiene. Así un mismo menú sirve para todos los personajes. El editor de menús siempre muestra todas las entradas."
L["Use a world marker entry again to pick that marker back up. Off places the marker again, at the new position.\nThis does not change the entry that clears all world markers, or the cycling entry."] = "Usa otra vez una entrada de marca del mundo para quitar esa marca. Si lo desactivas, vuelve a poner la marca en la posición nueva.\nNo cambia la entrada que quita todas las marcas del mundo ni la que va cambiándolas."
L["Disable Quickdraw"] = "Desactivar Quickdraw"
L["Adventurer Crest"] = "Blasón de aventurero"
L["Champion Crest"] = "Blasón de campeón"
L["Color Out of Melee Range"] = "Color fuera de c. a c."
L["Hero Crest"] = "Blasón de héroe"
L["Myth Crest"] = "Blasón de mito"
L["Scan all equipped gear costs at the Item Upgrade NPC.\nScans each slot one at a time — this can take up to 10 seconds.\nRequires the Item Upgrade window to be open.\n|cffff6060Item Upgrade window is not open.|r"] = "Busca el coste de todo el equipo puesto en el PNJ de mejora de objetos.\nRevisa cada hueco de uno en uno: puede tardar hasta 10 segundos.\nNecesita que la ventana de mejora de objetos esté abierta.\n|cffff6060La ventana de mejora de objetos no está abierta.|r"
L["Veteran Crest"] = "Blasón de veterano"
L["Background color for both Blizzard tooltips and EllesmereUI's own tooltips"] = "Color de fondo de las descripciones de Blizzard y de las propias de EllesmereUI"
L["Changes the crosshair colour when your current target is out of melee range."] = "Cambia el color de la cruz cuando tu objetivo actual está fuera del alcance cuerpo a cuerpo."
L["Controls when game tooltips appear"] = "Decide cuándo salen las descripciones del juego"
L["Keeps your note text in the Sign Up dialog instead of clearing it each time you open it."] = "Mantiene el texto de tu nota en la ventana de Inscribirse en lugar de borrarlo cada vez que la abres."
L["Makes the game tooltip follow your mouse cursor instead of appearing in the default screen corner. Use the arrows icon to pick the position relative to the cursor and fine-tune the X/Y offset."] = "Hace que la descripción del juego siga al cursor en lugar de salir en la esquina de siempre. Usa el icono de flechas para elegir la posición respecto al cursor y ajustar el desplazamiento X/Y."
L["Refresh using tooltip scan data.\nFor exact costs, use |cffffffff'Update at Upgrader'|r\nwhile at an Item Upgrade NPC."] = "Actualizar con los datos de las descripciones.\nPara ver los costes exactos, usa |cffffffff«Actualizar en el mejorador»|r\ncuando estés con un PNJ de mejora de objetos."
L["Reskins Blizzard tooltips with a dark, minimal style matching the EUI aesthetic. Requires reload to apply."] = "Cambia el aspecto de las descripciones de Blizzard a un estilo oscuro y sencillo como el de EUI. Hay que recargar para aplicarlo."
L["Scan all equipped gear costs at the Item Upgrade NPC.\nScans each slot one at a time — this can take up to 10 seconds.\nRequires the Item Upgrade window to be open."] = "Busca el coste de todo el equipo puesto en el PNJ de mejora de objetos.\nRevisa cada hueco de uno en uno: puede tardar hasta 10 segundos.\nNecesita que la ventana de mejora de objetos esté abierta."
L["This will reset all saved panel positions and reload your UI."] = "Esto restablece todas las posiciones guardadas de los paneles y recarga la interfaz."
L["Learn %d skill%s for %s"] = "Aprender %d técnica%s por %s"
L["Reset %1$s to its default position and reload your UI?"] = "¿Volver a poner %1$s en su posición predeterminada y recargar la interfaz?"
L["Upgradable Items (%d)"] = "Objetos mejorables (%d)"
L["Teleport to %s"] = "Teletransporte a %s"
L["Slowly orbits your action bar buttons around each bar's centre while Party Mode is active. The buttons stay upright, so clicking, cooldowns and keybinds are unaffected. Pauses in combat, where moving a button is blocked."] = "Hace girar despacio los botones de tus barras de acción alrededor del centro de cada barra mientras el modo fiesta está activo. Los botones siguen derechos, así que los clics, las reutilizaciones y los atajos no cambian. Se para en combate, donde no se pueden mover los botones."
L["Shows the Role Check button. Turn it off and the remaining buttons close the gap."] = "Muestra el botón Comprobación de función. Si lo desactivas, los demás botones se juntan."
L["Change Icon"] = "Cambiar icono"
L["Enable Character Sheet"] = "Activar hoja personaje"
L["Enable Great Vault Skin"] = "Aspecto gran cámara"
L["Equipped!"] = "¡Equipado!"
L["New equipment set name:"] = "Nombre del conjunto de equipamiento nuevo:"
L["Reskin Great Vault"] = "Aspecto gran cámara"
L["Saved!"] = "¡Guardado!"
L["Show Calendar Lockouts"] = "Ver registros calendario"
L["Show M+ Score"] = "Ver puntuación M+"
L["Back (Relic)"] = "Espalda (reliquia)"
L["Chest (Relic)"] = "Torso (reliquia)"
L["Spinning Action Bars"] = "Barras de acción girando"
L["Appends the spell or item ID to tooltips. The same setting as Global Settings > Developer."] = "Añade el ID del hechizo o del objeto a las descripciones. Es el mismo ajuste que Ajustes globales > Desarrollador."
L["Applies EllesmereUI theme styling to the character sheet window."] = "Aplica el estilo del tema de EllesmereUI a la ventana de la hoja del personaje."
L["Displays a player's equipped item level on their unit tooltip."] = "Muestra en la descripción de un jugador el nivel de objeto de lo que lleva equipado."
L["Displays a player's Mythic+ score on their unit tooltip, colored by rarity."] = "Muestra en la descripción de un jugador su puntuación de mítica+, con el color de su rareza."
L["Hides the health bar Blizzard shows at the bottom of unit tooltips."] = "Oculta la barra de salud que muestra Blizzard abajo de las descripciones de las unidades."
L["Missing Items:"] = "Faltan objetos:"
L["Recolors headers, arrows, and spell titles in Blizzard tooltips and context menus to match your UI Accent Color."] = "Cambia el color de los títulos, las flechas y los nombres de hechizos de las descripciones y menús de Blizzard a tu color de acento de la interfaz."
L["Reskins Blizzard tooltips, right-click context menus, and popups with a dark, minimal style matching the EUI aesthetic. Requires reload to apply."] = "Cambia el aspecto de las descripciones, los menús del clic derecho y las ventanas emergentes de Blizzard a un estilo oscuro y sencillo como el de EUI. Hay que recargar para aplicarlo."
L["Reskins the ESC / Game Menu with the EUI dark style, matching fonts, and accent-colored title."] = "Cambia el aspecto del menú Esc / de juego al estilo oscuro de EUI, con las fuentes a juego y el título en el color de acento."
L["Reskins the Great Vault window with custom tile backgrounds, progress colors, and completion states."] = "Cambia el aspecto de la ventana de la gran cámara con fondos de casilla propios, colores de progreso y estados de completado."
L["Reskins the LFG/dungeon queue accept popup with the EUI dark style and adds an accept countdown timer bar."] = "Cambia el aspecto de la ventana para aceptar la cola de mazmorra al estilo oscuro de EUI y añade una barra de cuenta atrás para aceptar."
L["Show Detailed Tooltips"] = "Ver descr. detalladas"
L["Show Player Titles in Tooltips"] = "Títulos en las descr."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept."] = "Muestra una barra de cuenta atrás debajo de la ventana para aceptar la cola, con el tiempo que te queda para aceptar."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin."] = "Muestra una barra de cuenta atrás debajo de la ventana para aceptar la cola, con el tiempo que te queda para aceptar. Funciona con o sin el cambio de aspecto."
L["Shows a player's RP title on their unit tooltip."] = "Muestra en la descripción de un jugador su título de rol."

-- == Frases montadas por partes (3) ========================================
L["Shows full spell and ability descriptions in tooltips instead of just the name. Only enforced on login after you toggle this setting."] = "Muestra en las descripciones la explicación completa de los hechizos y facultades en lugar de solo el nombre. Solo se aplica al entrar al juego después de cambiar este ajuste."
L["Shows saved instance lockouts with boss kill progress on the minimap calendar button tooltip."] = "Muestra en la descripción del botón del calendario del minimapa las instancias guardadas con el progreso de jefes muertos."
L["Themed Blizzard frames: Character Sheet, tooltips, menus, popups, Dragon Riding HUD."] = "Ventanas de Blizzard con tema: hoja del personaje, descripciones, menús, ventanas emergentes, indicadores de surcacielos."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, Dragon Riding HUD."] = "Ventanas de Blizzard con tema: aspecto de las ventanas, descripciones, menús, ventanas emergentes, indicadores de surcacielos."
L["Forces which way the default screen-anchored tooltip expands as lines are added. Default lets Blizzard decide from the tooltip's screen position."] = "Fuerza hacia dónde crece la descripción predeterminada anclada a la pantalla cuando se añaden líneas. Predeterminado deja que Blizzard lo decida según dónde esté la descripción en pantalla."
L["Makes the game tooltip follow your mouse cursor instead of showing at its fixed screen position (drag the Tooltip box in Unlock Mode to change that). Use the arrows icon to pick the position relative to the cursor and fine-tune the X/Y offset."] = "Hace que la descripción del juego siga al cursor en lugar de salir en su posición fija de la pantalla (arrastra la caja Descripción en el modo desbloqueo para cambiarla). Usa el icono de flechas para elegir la posición respecto al cursor y ajustar el desplazamiento X/Y."
