L["Always display player coordinates centered below the minimap instead of only on hover."] = "Muestra siempre las coordenadas del jugador centradas debajo del minimapa en lugar de solo al pasar el ratón."
L["Clock in Show Blizzard Elements"] = "Reloj en elementos Blizz"
L["Display the clock inside the minimap instead of above it"] = "Muestra el reloj dentro del minimapa en lugar de encima"
