L["Override the size of ungrouped minimap buttons independently from the interactable button size."] = "Cambia el tamaño de los botones del minimapa separados aparte del tamaño de los botones que se pueden usar."
L["Scales the Friends, Great Vault and M+ Portals hover panels the extra buttons open."] = "Cambia el tamaño de los paneles de amigos, gran cámara y portales de M+ que abren los botones extra al pasar el ratón."
L["Show the expansion landing page (Omnium Folio) button at the bottom-left of the minimap. Use the cog to nudge its position."] = "Muestra el botón de la página de la expansión (Omnium Folio) abajo a la izquierda del minimapa. Usa el engranaje para ajustar su posición."
