L["Scales the tracking blips drawn on the map (herbs, ore, quest dots). The map itself keeps its size; other minimap elements are unaffected."] = "Cambia el tamaño de los puntos de rastreo del mapa (hierbas, menas, puntos de misión). El mapa mantiene su tamaño; los demás elementos del minimapa no cambian."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position. While dragging, buttons snap to nearby buttons and the minimap border; hold Ctrl together with Shift to disable snapping."] = "Si lo activas, haz Mayús + clic en cualquier botón del minimapa (correo, calendario, rastreo, botones de addons) para arrastrarlo a donde quieras. Al arrastrarlos, los botones se pegan a los botones cercanos y al borde del minimapa; mantén Ctrl junto con Mayús para que no se peguen."
L["Allow Chat to be Moved Offscreen"] = "Chat fuera de pantalla"
L["Idle Fade Delay"] = "Retraso atenuar"
L["Idle Fade Strength"] = "Intensidad atenuar"
L["chat tabs border spacing background sidebar friends voice url copy whisper channel abbreviate shortened class color names timestamps timestamp all messages font size bubbles bubble speech balloon nameplate"] = "chat pestañas borde espacio fondo barra lateral amigos voz enlace copiar susurro canal abreviar corto nombres con color de clase hora todos los mensajes tamaño de letra bocadillos bocadillo placa de nombre"
L["Extends the chat background up behind the tabs, and the sidebar to match, for one seamless panel."] = "Extiende el fondo del chat hacia arriba por detrás de las pestañas, y la barra lateral a juego, para tener un solo panel continuo."
L["Your chat position is now controlled by Blizzard Edit Mode.\nPlease adjust its position there."] = "La posición del chat la controla ahora el modo edición de Blizzard.\nAjústala allí."
L["Aligns the tab bar to the outer sidebar edge instead of only the chat panel edge."] = "Alinea la barra de pestañas al borde exterior de la barra lateral en lugar de solo al borde del panel del chat."
L["A UI reload is needed to apply the extended chat background."] = "Hay que recargar la interfaz para aplicar el fondo extendido del chat."
