L["Thank you for helping test EllesmereUI during beta! During testing, many systemic changes were made to build the foundation for a stable, flexible addon going forward.\n\nTo ensure a clean experience for everyone, all settings have been automatically reset. You will need to reconfigure your UI. We apologize for the inconvenience, and appreciate your patience.\n\nPrevious profile exports are no longer compatible and will need to be re-created."] = "¡Gracias por ayudar a probar EllesmereUI durante la beta! Durante las pruebas se hicieron muchos cambios de fondo para construir la base de un addon estable y flexible de cara al futuro.\n\nPara que todo el mundo empiece limpio, todos los ajustes se han restablecido automáticamente. Tendrás que volver a configurar tu interfaz. Sentimos las molestias y te agradecemos la paciencia.\n\nLas exportaciones de perfiles anteriores ya no son compatibles y habrá que volver a crearlas."
