L["Another override group already provides the custom unlock mode for your current spec."] = "Otro grupo de ajustes ya da el modo desbloqueo personalizado para tu especialización actual."
L["Buff Manager Override Active"] = "Gestor de beneficios propio activo"
L["Conditional Overrides: override settings by condition (dungeon, raid, keybind...)"] = "Ajustes condicionales: cambia ajustes según la condición (mazmorra, banda, atajo...)"
L["The active override's custom Buff Manager is bound to this page. Leave the Buff Manager tab to switch to another override."] = "El gestor de beneficios personalizado del ajuste propio activo está unido a esta página. Sal de la pestaña del gestor de beneficios para cambiar a otro ajuste propio."
L["This will create a fully unique Buff Manager for this conditional group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect it."] = "Esto crea un gestor de beneficios totalmente propio para este grupo condicional. Se copian tus ajustes actuales del gestor de beneficios como punto de partida, y los cambios en tu gestor de beneficios predeterminado ya no le afectarán."
L["This will create a fully unique Buff Manager for this override group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect these specs."] = "Esto crea un gestor de beneficios totalmente propio para este grupo de ajustes. Se copian tus ajustes actuales del gestor de beneficios como punto de partida, y los cambios en tu gestor de beneficios predeterminado ya no afectarán a estas especializaciones."
L["12.1 LAUNCH"] = "LANZAMIENTO DE LA 12.1"
L["One video walks you through the most important changes in 12.1 and how to get the most out of EllesmereUI under them. Copy the link and give it a watch before you dive in."] = "Un vídeo te explica los cambios más importantes de la 12.1 y cómo sacarle el máximo partido a EllesmereUI con ellos. Copia el enlace y míralo antes de ponerte."
L["Thank you to all who support EllesmereUI and its incredible support team!"] = "¡Gracias a todos los que apoyan a EllesmereUI y a su increíble equipo de asistencia!"
L["ALL DONORS"] = "TODOS LOS DONANTES"
L["A clean, airy layout with a calm feel and clear information at a glance. Comfortable for long sessions in any content."] = "Una disposición limpia y amplia, con sensación de calma e información clara de un vistazo. Cómoda para sesiones largas en cualquier contenido."
L["A luminous healing setup built around raid frames and crisp readability, keeping your team's health front and center at a glance."] = "Una configuración de sanador luminosa, pensada alrededor de los marcos de banda y con lectura nítida, que deja la salud de tu equipo a la vista de un vistazo."
L["A shadowed, understated layout that keeps the screen quiet and the essentials close. Information appears exactly when you need it."] = "Una disposición sombría y discreta que deja la pantalla tranquila y lo esencial cerca. La información aparece justo cuando la necesitas."
L["The damage and tank cut of Light of Nitex. The same style refocused on your rotation, procs, and cooldowns front and center."] = "La versión de daño y tanque de Light of Nitex. El mismo estilo, centrado en tu rotación, tus procs y tus reutilizaciones."
L["The dark counterpart to Lazar's Dawn. A moody, high-contrast layout that keeps focus locked on the fight."] = "La versión oscura de Lazar's Dawn. Una disposición intensa y de alto contraste que mantiene la atención en el combate."
L["Regular Import"] = "Importación normal"
L["Ultrawide Import"] = "Importación ultrapanorámica"
