L["Show world latency instead of home latency."] = "Muestra la latencia del mundo en lugar de la de casa."
L["Shows item level and secondary stats in the Character button's tooltip."] = "Muestra el nivel de objeto y las estadísticas secundarias en la descripción del botón Personaje."
L["Uses a random hearthstone toy variant each cast."] = "Usa una variante de juguete de piedra de hogar al azar cada vez."
L["Which micro menu buttons this block shows."] = "Qué botones del micromenú muestra este bloque."
L["World Latency"] = "Latencia del mundo"
L["|cFFFFFFFF[|rTravel Cooldowns|cFFFFFFFF]|r"] = "|cFFFFFFFF[|rReutil. de viaje|cFFFFFFFF]|r"
L["|cFFFFFFFFAchievement Points|r"] = "|cFFFFFFFFPuntos de logro|r"
L["|cFFFFFFFFCompanion Level|r"] = "|cFFFFFFFFNivel del compañero|r"
L["|cFFFFFFFFDelver's Journey|r"] = "|cFFFFFFFFViaje del explorador|r"
L["Shows a clickable list of online friends and guildmates in the Social and Guild button tooltips."] = "Muestra en las descripciones de los botones Social y Hermandad una lista con los amigos y compañeros de hermandad conectados que puedes pulsar."
L["Social & Guild Tooltip"] = "Descr. social y hermandad"
L["The ready check prompt with its Yes / No buttons, plus the initiator's response list."] = "La ventana de comprobación de listos con sus botones Sí / No, además de la lista de respuestas de quien la inicia."
L["Hide Portrait"] = "Ocultar retrato"
L["Hides the ready check glyph above the prompt, leaving just the question and the Yes / No buttons. Applies while the Ready Check reskin is enabled."] = "Oculta el símbolo de la comprobación de listos encima de la pregunta y deja solo la pregunta y los botones Sí / No. Se aplica mientras el aspecto de la comprobación de listos esté activado."
L["Squares the extra action and zone ability buttons and gives them a thin black border.\n\nOff by default. The size slider below works whether this is on or off."] = "Hace cuadrados los botones de acción extra y de facultad de zona y les pone un borde negro fino.\n\nDesactivado de forma predeterminada. El control de tamaño de abajo funciona esté activado o no."
L["Reskins the dungeon and battleground queue accept popups with the EUI dark style, and adds an accept countdown timer bar to the dungeon one."] = "Cambia el aspecto de las ventanas para aceptar la cola de mazmorra y de campo de batalla al estilo oscuro de EUI, y añade una barra de cuenta atrás para aceptar a la de mazmorra."
L["Colors the enemy nameplate name text to match the unit's reaction (Hostile or Neutral) instead of the Enemy Name Text color."] = "Pone al texto del nombre de la placa enemiga el color de la reacción de la unidad (hostil o neutral) en lugar del color del texto del nombre enemigo."
L["Player Bar Texture"] = "Textura barra jugador"
L["Focus Bar Texture"] = "Textura barra foco"
L["Target Absorb Style"] = "Estilo absorción objetivo"
L["Player Heal Absorb Style"] = "Estilo abs. sanación jugador"
L["Focus Heal Absorb Style"] = "Estilo abs. sanación foco"
