L["Player Absorb Style"] = "Estilo absorción jugador"
L["Focus Absorb Style"] = "Estilo absorción foco"
L["Target Heal Absorb Style"] = "Estilo abs. sanación objetivo"
L["Outline style override for all Cooldown Manager text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto del gestor de reutilizaciones. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all AuraBuff Reminders text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de los recordatorios de beneficios. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Quality of Life text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de calidad de vida. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Blizzard Skins+ text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de Blizzard Skins+. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Friends List text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de la lista de amigos. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Mythic+ Tools text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de las herramientas de mítica+. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Quest Tracker text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto del seguimiento de misiones. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."

-- == Frases montadas por partes (5) ========================================
L["Outline style override for all Minimap text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto del minimapa. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Chat text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto del chat. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Damage Meters text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de los medidores de daño. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all DataBars text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de las barras de datos. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Unit Frames text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de los marcos de unidad. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Action Bars text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de las barras de acción. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Nameplates text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de las placas de nombre. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Bags text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de las bolsas. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Quickdraw text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de Quickdraw. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Resource & Cast Bars text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de Barras de recursos y de hechizos. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Blizzard Style keeps every EllesmereUI feature and setting; only the art changes. Changing a style reloads the UI."] = "El estilo de Blizzard mantiene todas las funciones y ajustes de EllesmereUI; solo cambia el dibujo. Al cambiar de estilo se recarga la interfaz."
L["Style to apply to every module below."] = "Estilo que se aplica a todos los módulos de abajo."
L["Blizzard's rounded button art with every EllesmereUI bar feature."] = "El dibujo de botones redondeados de Blizzard con todas las funciones de barras de EllesmereUI."
L["Blizzard's frame art, portraits and bar shapes with every EllesmereUI frame feature."] = "El dibujo de marcos, retratos y formas de barra de Blizzard con todas las funciones de marcos de EllesmereUI."
L["Blizzard's health and cast bar art with every EllesmereUI nameplate feature."] = "El dibujo de barras de salud y de hechizos de Blizzard con todas las funciones de placas de nombre de EllesmereUI."
L["Blizzard's rounded cooldown icons with every EllesmereUI icon feature."] = "Los iconos de reutilización redondeados de Blizzard con todas las funciones de iconos de EllesmereUI."
L["Blizzard's buff bar art with every EllesmereUI tracked bar feature."] = "El dibujo de barras de beneficios de Blizzard con todas las funciones de barras seguidas de EllesmereUI."
L["Blizzard's cast bar art with every EllesmereUI cast bar feature."] = "El dibujo de barra de hechizos de Blizzard con todas las funciones de barras de hechizos de EllesmereUI."
L["The personal resource display's bar frame on the health, power and class resource bars, with every EllesmereUI bar feature."] = "El marco de barra de los recursos personales en las barras de salud, poder y recurso de clase, con todas las funciones de barras de EllesmereUI."
L["Blizzard's round minimap and header with every EllesmereUI minimap feature."] = "El minimapa redondo y el título de Blizzard con todas las funciones de minimapa de EllesmereUI."
L["Blizzard's meter window and bar art with every EllesmereUI meter feature."] = "La ventana y el dibujo de barras del medidor de Blizzard con todas las funciones de medidor de EllesmereUI."
L["a Dispel Glow Style"] = "un estilo de brillo de disipación"
L["Color by Type (Magic/Enrage)"] = "Color por tipo (magia/enfurecer)"
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size. bar height and text offset."] = "Muestra una barra de cuenta atrás debajo de la ventana para aceptar la cola, con el tiempo que te queda para aceptar. Funciona con o sin el cambio de aspecto. Usa la muestra de color y el engranaje para elegir el color del texto de la cuenta atrás, el tamaño del texto, la altura de la barra y el desplazamiento del texto."
L["Due to Blizzard API restrictions, Blizzard's native target-of-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Target frame's source -- both Blizzard Default, or both EllesmereUI."] = "Por las restricciones de la API de Blizzard, el objetivo de objetivo propio de Blizzard no se puede ocultar en combate y se verá todo el tiempo que estés en combate. Recomendado: usa el mismo origen que el marco del objetivo (los dos Predeterminado de Blizzard o los dos EllesmereUI)."
L["Due to Blizzard API restrictions, Blizzard's native focus-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Focus frame's source -- both Blizzard Default, or both EllesmereUI."] = "Por las restricciones de la API de Blizzard, el objetivo del foco propio de Blizzard no se puede ocultar en combate y se verá todo el tiempo que estés en combate. Recomendado: usa el mismo origen que el marco del foco (los dos Predeterminado de Blizzard o los dos EllesmereUI)."
L["\"Blizzard Default\" is only available when the Target frame's source is set to Blizzard Default -- the target-of-target then comes from Blizzard's target frame."] = "«Predeterminado de Blizzard» solo está disponible cuando el origen del marco del objetivo está en Predeterminado de Blizzard: el objetivo de objetivo sale entonces del marco del objetivo de Blizzard."
L["\"Blizzard Default\" is only available when the Focus frame's source is set to Blizzard Default -- the focus-target then comes from Blizzard's focus frame."] = "«Predeterminado de Blizzard» solo está disponible cuando el origen del marco del foco está en Predeterminado de Blizzard: el objetivo del foco sale entonces del marco del foco de Blizzard."
L["This client has no Blizzard class resource bar to attach to the frame"] = "Este cliente no tiene barra de recurso de clase de Blizzard que unir al marco"
L["Show raid marker preview"] = "Mostrar la vista previa de la marca de banda"
L["Hide raid marker preview"] = "Ocultar la vista previa de la marca de banda"
L["Show leader indicator preview"] = "Mostrar la vista previa del indicador de líder"
L["Hide leader indicator preview"] = "Ocultar la vista previa del indicador de líder"
L["Show elite/rare indicator preview"] = "Mostrar la vista previa del indicador de élite/raro"
L["Hide elite/rare indicator preview"] = "Ocultar la vista previa del indicador de élite/raro"
L["Show faction indicator preview"] = "Mostrar la vista previa del indicador de facción"
L["Hide faction indicator preview"] = "Ocultar la vista previa del indicador de facción"
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies. Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = "No se puede cambiar. Estas condiciones son compartidas y solo se pueden cambiar cuando no estás editando ningún ajuste propio. Un ajuste propio sustituye por completo el ajuste de visibilidad (nunca, siempre o al pasar el ratón) y no tiene en cuenta nada de lo que hay aquí mientras se aplica. Al pasar el ratón también está bloqueado aquí para este elemento: su forma de mostrarse al pasar el ratón sigue el ajuste compartido, así que un ajuste propio solo podría dejarlo visible."
L["Enable At Stacks"] = "Activar con acumulaciones"
L["Glow at Stacks Comparisons"] = "Comparaciones de brillo con acum."
L["Not available in Buff Missing mode"] = "No disponible en el modo Falta el beneficio"
L["Hide every Cooldown Manager glow while you are out of combat: proc glows, active state, max stacks, buff and pandemic glows, cooldown ready glows and bar glows.\n\nThey come back the moment you enter combat, including a glow that started before the pull.\n\nApplies to every CDM bar and to the Tracking Bars at once. Glows from other EllesmereUI modules are not affected.\n\nThe Bar Glows page keeps its own per-mapping Only In Combat toggle; this one applies on top of it."] = "Oculta todos los brillos del gestor de reutilizaciones mientras estás fuera de combate: brillos de proc, estado activo, acumulaciones máximas, beneficios y pandemia, reutilización lista y brillos de barras.\n\nVuelven en cuanto entras en combate, también un brillo que empezó antes del pull.\n\nSe aplica a la vez a todas las barras del CDM y a las barras de seguimiento. No afecta a los brillos de otros módulos de EllesmereUI.\n\nLa página Brillos de barras tiene su propio interruptor Solo en combate por cada asignación; este se aplica además."
L["Max Duration and Less Common Filters"] = "Duración máx. y filtros"
L["Crosshair Frame Strata"] = "Nivel de capa de la cruz"
L["This element shows as soon as ONE condition matches, and a Hide lane then means show while that condition is false."] = "Este elemento se muestra en cuanto se cumple UNA condición, y una fila Ocultar significa entonces mostrar mientras esa condición no se cumpla."
L["Friend Notifications Skin"] = "Aspecto avisos de amigos"
L["Important Cast Glow Settings"] = "Ajustes brillo importante"
L["Font size."] = "Tamaño de letra."
L["Shift-click a stack in the bags or bank to open a split dialog with an Auto Split button, which splits the stack into empty slots repeatedly until only the chosen amount or less remains. Off uses the default split popup."] = "Mayús + clic en un montón de las bolsas o del banco para abrir una ventana de dividir con un botón División automática, que divide el montón en huecos vacíos una y otra vez hasta que solo quede la cantidad elegida o menos. Desactivado usa la ventana de dividir normal."
L["Restyles Blizzard's on-screen progress bars (event objectives, nameplate counters) to the EUI look. Requires reload to apply.\n\nThese bars are drawn over rather than modified, so if the game ever reports their contents as protected the original bar is shown instead.\n\nUse the cog to set a minimum size, so bars on shrunken nameplates stay readable."] = "Cambia el estilo de las barras de progreso de Blizzard en pantalla (objetivos de eventos, contadores de las placas de nombre) al aspecto de EUI. Hay que recargar para aplicarlo.\n\nEstas barras se dibujan por encima sin modificarlas, así que si el juego dice alguna vez que su contenido está protegido, se muestra la barra original.\n\nUsa el engranaje para poner un tamaño mínimo, para que las barras de las placas de nombre pequeñas se sigan leyendo."
L["NOW ON WOW FOREVER"] = "YA EN WOW FOREVER"
L["Everything from retail, ported to WoW Forever"] = "Todo lo de retail, llevado a WoW Forever"
L["One EllesmereUI: the same install runs on either game"] = "Un solo EllesmereUI: la misma instalación funciona en los dos juegos"
L["Export and import your profiles between the two clients"] = "Exporta e importa tus perfiles entre los dos clientes"
L["ALSO NEW"] = "TAMBIÉN NUEVO"
L["Keep every EllesmereUI feature and setting, with Blizzard's own art. Pick the look per module in Global Settings -> Style."] = "Mantén todas las funciones y ajustes de EllesmereUI con el dibujo propio de Blizzard. Elige el aspecto de cada módulo en Ajustes globales -> Estilo."
L["Themed Blizzard frames: window skins, tooltips, menus, popups."] = "Ventanas de Blizzard con tema: aspecto de las ventanas, descripciones, menús, ventanas emergentes."
L["The current WoW Forever client has a bug that prevents some Action Bars functionality. Bars, buttons and keybinds work; page switching on stance and form changes, conditional bar hiding and empty-slot handling do not. This resolves itself once Blizzard fixes the client."] = "El cliente actual de WoW Forever tiene un error que impide algunas funciones de las barras de acción. Las barras, los botones y los atajos funcionan; el cambio de página al cambiar de actitud o forma, ocultar barras por condiciones y lo de los huecos vacíos no. Se arreglará solo cuando Blizzard corrija el cliente."
L["Stacks the bars upward from the bottom edge instead of down from the top."] = "Apila las barras hacia arriba desde el borde de abajo en lugar de hacia abajo desde arriba."
L["Show Threat Value"] = "Ver valor de amenaza"
L["Show Threat Percent"] = "Ver amenaza (%)"
L["How close each player is to pulling aggro. 100% takes it."] = "Lo cerca que está cada jugador de quitar el aggro. Con el 100% lo quita."
L["Outline style override for all Raid Frames text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de los marcos de banda. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Outline style override for all Forever Essentials text. EUI Global Outline follows the global Outline Mode setting above."] = "Contorno propio para todo el texto de Forever Essentials. El contorno global de EUI sigue el ajuste Modo de contorno de arriba."
L["Use the Tank List"] = "Usar lista de tanques"
L["Use the Healer List"] = "Usar lista de sanadores"
L["Use the DPS List"] = "Usar lista de DPS"
L["PAB: Buff Bar"] = "BAJ: barra de beneficios"
L["PAB: Debuff Bar"] = "BAJ: barra de perjuicios"
L["PAB: External Defensives"] = "BAJ: defensivos externos"
L["PAB: New Buff Bar"] = "BAJ: barra de beneficios nueva"
L["PAB: New Debuff Bar"] = "BAJ: barra de perjuicios nueva"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n1. Disable EllesmereUI Cooldown Manager (button below).\n2. Open Edit Mode from the Game Menu.\n3. Select each Cooldown Manager viewer and set Visibility to Always.\n4. On Tracked Buffs and Tracked Bars, tick Hide When Inactive.\n5. Save the layout and leave Edit Mode.\n6. Re-enable EllesmereUI Cooldown Manager."] = "EllesmereUI no ha podido guardar este cambio en tu diseño del modo edición, así que hay que ponerlo a mano. El gestor de reutilizaciones tiene que estar desactivado mientras lo haces, porque oculta los visores de reutilizaciones de Blizzard y un visor oculto no se puede seleccionar en el modo edición.\n\n1. Desactiva el gestor de reutilizaciones de EllesmereUI (botón de abajo).\n2. Abre el modo edición desde el menú de juego.\n3. Elige cada visor del gestor de reutilizaciones y pon Visibilidad en Siempre.\n4. En Beneficios rastreados y Barras rastreadas, marca Ocultar si no está activo.\n5. Guarda el diseño y sal del modo edición.\n6. Vuelve a activar el gestor de reutilizaciones de EllesmereUI."
L["Buffs & Weapon Enchants"] = "Benef. y encant. de arma"
L["Custom Duration Format"] = "Formato duración propio"
L["Custom duration formats may cause a slight loss in performance efficiency. Do you want to enable them?"] = "Los formatos de duración propios pueden bajar un poco el rendimiento. ¿Quieres activarlos?"
L["Enable External Defensives Frame first"] = "Activa antes el marco de defensivos externos"
L["Enable Styled Buffs & Debuffs first"] = "Activa antes Beneficios/perjuicios con estilo"
L["GCD Bar Settings"] = "Ajustes barra GCD"
L["Recolor the bar while a spell is castable (usable and off cooldown). The first castable spell in the list wins, so order = priority. Overrides threshold coloring while active; an active tracked buff from Buff Colors takes priority.\nFor an ability that turns into another spell while active, enter the original spell's ID: its current form is checked."] = "Cambia el color de la barra mientras un hechizo se puede lanzar (se puede usar y no está en reutilización). Manda el primero de la lista que se pueda lanzar, así que el orden es la prioridad. Mientras está activo manda sobre los colores del umbral; un beneficio seguido activo de Colores de los beneficios tiene prioridad.\nPara una facultad que se convierte en otro hechizo mientras está activa, escribe el ID del hechizo original: se comprueba su forma actual."
L["Show the Main Hand row."] = "Muestra la fila de la mano derecha."
L["Show the Off Hand row while an off-hand weapon is equipped."] = "Muestra la fila de la mano izquierda mientras llevas un arma en la mano izquierda."
L["Show the Ranged row while a ranged weapon is equipped."] = "Muestra la fila de a distancia mientras llevas un arma a distancia."
L["While an on-next-swing attack is queued (Heroic Strike, Cleave, Maul), the Main Hand and Off Hand rows take the queue color and show the attack's name."] = "Mientras hay un ataque de «siguiente golpe» en cola (Heroic Strike, Rajar, Magullar), las filas de la mano derecha y la izquierda toman el color de la cola y muestran el nombre del ataque."
L["No mobility spells known for your current spec yet -- add one below."] = "Aún no conoces hechizos de movilidad en tu especialización actual: añade uno abajo."
L["Refresh using tooltip scan data.\n For exact costs, use |cffffffff'Update at Upgrader'|r\n while at an Item Upgrade NPC."] = "Actualizar con los datos de las descripciones.\n Para ver los costes exactos, usa |cffffffff«Actualizar en el mejorador»|r\n cuando estés con un PNJ de mejora de objetos."
L["Scan all equipped gear costs at the Item Upgrade NPC.\n Scans each slot one at a time — this can take up to 10 seconds.\n Requires the Item Upgrade window to be open."] = "Busca el coste de todo el equipo puesto en el PNJ de mejora de objetos.\n Revisa cada hueco de uno en uno: puede tardar hasta 10 segundos.\n Necesita que la ventana de mejora de objetos esté abierta."
L["Smallest on-screen size a reskinned bar is drawn at.\n\nWidget bars on a nameplate inherit that nameplate's scale, so they come out tiny on small units. Below this size the bar is scaled up instead, text and all.\n\nSet to 0 to mirror Blizzard's size exactly."] = "El tamaño más pequeño en pantalla al que se dibuja una barra con aspecto cambiado.\n\nLas barras de indicadores de una placa de nombre heredan su escala, así que salen diminutas en unidades pequeñas. Por debajo de este tamaño la barra se agranda, también el texto.\n\nPon 0 para usar exactamente el tamaño de Blizzard."
L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Cierra un menú abierto sin usar nada. Esc también lo hace siempre. Una sola tecla para todos los menús, que solo se usa mientras hay un menú abierto: un botón del ratón sigue haciendo lo de siempre el resto del tiempo."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span. A nest reaches over the plain entries it passes, and they only give up their angles while it is open."] = "Hasta dónde puede extender un submenú sus entradas a lo largo del arco. Contenido lo mantiene apartado del submenú siguiente a cada lado, para que dos nunca se dibujen uno encima del otro. Desbordado le deja usar toda la Amplitud máxima del submenú. Un submenú pasa por encima de las entradas normales que cruza, y estas solo ceden su ángulo mientras está abierto."
L["The widest angle a nest's entries may spread over. They stay on one ring for as long as they fit inside it; the rest go onto a second ring further out."] = "El ángulo más ancho que pueden ocupar las entradas de un submenú. Se quedan en un mismo anillo mientras quepan; las demás van a un segundo anillo más alejado."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Usa la entrada a la que apuntas mientras un menú está abierto con Abrir y cerrar el menú. Una sola tecla para todos los menús, que solo se usa mientras hay un menú abierto: un botón del ratón sigue haciendo lo de siempre el resto del tiempo."
L["Show while this condition is false"] = "Mostrar mientras esta condición no se cumpla"
L["This client cannot run the safeguard that stops a drag from casting the spell, so actions stay on key up until Blizzard fixes it."] = "Este cliente no puede usar la protección que impide que arrastrar lance el hechizo, así que las acciones se quedan al soltar la tecla hasta que Blizzard lo arregle."
L["Movable left-aligned distance text for your current target (default 30-35, optional 30+ / 30), colored by yard distance. Off by default; position or Anchor to a unit frame in Unlock Mode."] = "Texto de distancia a tu objetivo actual, alineado a la izquierda y que puedes mover (predeterminado: 30-35; opcional: 30+ / 30), con color según la distancia. Desactivado de forma predeterminada; colócalo o ánclalo a un marco de unidad en el modo desbloqueo."
L["Select which specs you want %s to be assigned to"] = "Elige a qué especializaciones quieres asignar %s"
L["This profile already holds 16 action menus"] = "Este perfil ya tiene 16 menús de acciones"
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span."] = "Hasta dónde puede extender un submenú sus entradas a lo largo del arco. Contenido lo mantiene apartado del submenú siguiente a cada lado, para que dos nunca se dibujen uno encima del otro. Desbordado le deja usar toda la Amplitud máxima del submenú."
