-- == Bloque 29: novedades de la 9.6 (buscador de grupos, Forever, pesca, misiones...) (alvaro1929) ====
L["%d applied"] = "%d solicitudes"
L["%s (e.g. 10-12)"] = "%s (p. ej. 10-12)"
L["A bar at the top of the Dungeons & Raids sidebar counting your Mythic+ Group Finder applications and how they ended, each count inside its part of the bar. Other dungeon difficulties, raids, delves and other groups are not counted."] = "Una barra arriba en el lateral de Mazmorras y bandas que cuenta tus solicitudes de mítica+ del buscador de grupos y cómo acabaron, cada número en su parte de la barra. No cuenta otras dificultades de mazmorra, bandas, profundidades ni otros grupos."
L["A better group finder: narrow the list down to the groups you want and see who is in each one, right in the Dungeons & Raids window."] = "Un buscador de grupos mejor: filtra la lista hasta dejar los grupos que quieres y mira quién hay en cada uno, en la propia ventana de Mazmorras y bandas."
L["A member whose class has one of these spells:"] = "Un miembro cuya clase tenga uno de estos hechizos:"
L["APPLICATIONS"] = "SOLICITUDES"
L["Accepted"] = "Aceptadas"
L["Adds the skill a herb or ore node needs to its tooltip, colored by your chance to raise your skill there."] = "Añade a la descripción de una planta o veta la habilidad que pide, con el color según tu probabilidad de subir la habilidad ahí."
L["Also adds the required skill to herb and ore names on the minimap."] = "También añade la habilidad necesaria a los nombres de plantas y vetas en el minimapa."
