L["Adds Leech, Avoidance and Speed (L, A, S) in smaller letters behind the secondary stats in the gear flyout."] = "Añade Parasitar, Evasión y Velocidad (L, A, S) en letras más pequeñas detrás de las estadísticas secundarias en la lista de equipo."
