L["Shows each item's secondary stats as letters in the gear flyout, largest first (C Crit, H Haste, M Mastery, V Versatility), so items with the same icon are told apart."] = "Muestra las estadísticas secundarias de cada objeto como letras en la lista de equipo, de mayor a menor (C golpe crítico, H celeridad, M maestría, V versatilidad), para distinguir objetos con el mismo icono."
L["Shows each socketed gem's secondary stats as letters on its icon, largest first (C Crit, H Haste, M Mastery, V Versatility)."] = "Muestra las estadísticas secundarias de cada gema engarzada como letras en su icono, de mayor a menor (C golpe crítico, H celeridad, M maestría, V versatilidad)."
L["Socket Panel Settings"] = "Ajustes del panel de ranuras"
L["Stat Letters"] = "Letras estad."
L["Tertiary Stat Letters"] = "Letras estad. terciarias"
L["WoW Forever's frame round the chat panel, input box, tabs and sidebar buttons. Slim Textured uses Blizzard's current art; a style whose art this client lacks draws Slim. Applies after a UI reload."] = "El marco de WoW Forever alrededor del panel de chat, la caja de texto, las pestañas y los botones de la barra lateral. Fino con textura usa el dibujo actual de Blizzard; un estilo cuyo dibujo no tiene este cliente se dibuja Fino. Se aplica tras recargar la interfaz."
L["Glow When Usable"] = "Brillo disponible"
L["this ability"] = "esta habilidad"
L["WoW Forever's frame round the meter windows, the breakdown, Spell History and the Forever Essentials threat meter. Slim Textured uses Blizzard's current art; a style whose art this client lacks draws Slim. Applies after a UI reload."] = "El marco de WoW Forever alrededor de las ventanas del medidor, el detalle, el historial y el medidor de amenaza de Imprescindibles de Forever. Fino con textura usa el dibujo actual de Blizzard; un estilo cuyo dibujo no tiene este cliente se dibuja Fino. Se aplica tras recargar la interfaz."
L["Among a quest's reward choices, a money bag marks the one that sells for most, its count included."] = "Entre las recompensas a elegir de una misión, una bolsa de dinero marca la que se vende más cara, contando su cantidad."
L["Auto Summon Pet"] = "Mascota auto."
L["Auto Uprank Spells"] = "Subir rango auto."
L["Brings back items you middle-clicked away."] = "Recupera los objetos que quitaste con el clic central."
L["Classic Spellbook"] = "Hechizos clásicos"
L["Classic Talents"] = "Talentos clásicos"
L["Clear Excluded Items"] = "Vaciar excluidos"
L["Color Stats"] = "Color estad."
L["Colors each stat name on item tooltips, enchants included, and its number per Number Color."] = "Colorea el nombre de cada estadística en las descripciones de objetos, encantamientos incluidos, y su número según Color número."
L["Crops the icon's edges."] = "Recorta los bordes del icono."
L["Double-Click to Cast"] = "Doble clic para lanzar"
L["Enable Junk Items Window"] = "Ventana de chatarra"
L["Every item you middle-clicked away can show in the Junk Items window again."] = "Todo objeto que quitaste con el clic central puede volver a salir en la ventana de chatarra."
L["Excluded Items"] = "Objetos excluidos"
L["Fade Map While Moving"] = "Atenuar mapa al moverte"
L["Favorites per Character"] = "Favoritas por personaje"
L["Fishing Key"] = "Tecla de pesca"
L["Fishing Sounds"] = "Sonidos de pesca"
L["How many junk stacks the window lists."] = "Cuántos montones de chatarra enseña la ventana."
L["Items Shown"] = "Nº de objetos"
L["Lists white stacks as well as gray ones."] = "Enseña también los montones blancos, además de los grises."
L["Merge Equal Spell Power"] = "Unir poder con hechizos"
L["Most Valuable Reward"] = "Recompensa más valiosa"
L["Number Color"] = "Color número"
L["Price Position"] = "Posición precio"
L["Reveal Unexplored Areas"] = "Ver zonas sin explorar"
L["Reveal Unexplored Areas Settings"] = "Ajustes de zonas sin explorar"
L["Shorten Equip Lines"] = "Acortar líneas Equipar"
L["Shortens Equip: and Set: stat lines on item tooltips to +X Stat."] = "Acorta en las descripciones de objetos las líneas de estadísticas «Equipar:» y «Conjunto:» a «+X estadística»."
L["Show Empty Bag Slots"] = "Ver huecos libres"
L["Show Zone Levels"] = "Ver nivel de zonas"
L["Show the Game Behind the Map"] = "Ver el juego tras el mapa"
L["Shows an icon for your active stance, form, aura or aspect. Hidden while none is active."] = "Muestra un icono de tu actitud, forma, aura o aspecto activos. Se oculta si no hay ninguno."
L["Shows equal spell damage and healing as one Spell Power line."] = "Muestra el daño y la sanación con hechizos iguales como una sola línea de Poder con hechizos."
L["Shows free and total bag slots as the title."] = "Pone de título los huecos de bolsa libres y totales."
L["Shows the level range of the zone you hover on a continent of the world map, under its name, colored by difficulty."] = "Muestra el rango de niveles de la zona que señalas en un continente del mapa del mundo, bajo su nombre, con el color según la dificultad."
L["Shows the parts of the world map you have not explored yet. Use the cog to pick their color."] = "Muestra las partes del mapa del mundo que aún no has explorado. Usa el engranaje para elegir su color."
L["Shows your cheapest junk in a small window."] = "Muestra tu chatarra más barata en una ventana pequeña."
L["Skip Confirmation for White Items"] = "Sin confirmar los blancos"
L["Tints the areas you have not explored yet. White shows them as they are."] = "Tiñe las zonas que aún no has explorado. El blanco las enseña tal cual."
L["Unexplored Color"] = "Color sin explorar"
L["White stacks delete on the first Ctrl + Left Click instead of the second."] = "Los montones blancos se borran con el primer Ctrl + clic izquierdo en vez de con el segundo."
L["0 - no stance / normal form"] = "0 - sin actitud / forma normal"
L["@cursor - ground spell at cursor"] = "@cursor - hechizo de suelo en el cursor"
L["@focus - focus"] = "@focus - foco"
L["@mouseover - under the mouse"] = "@mouseover - bajo el ratón"
L["@pet - pet"] = "@pet - mascota"
L["@pettarget - pet's target"] = "@pettarget - obj. mascota"
L["@player - yourself"] = "@player - tú"
L["@target - target"] = "@target - objetivo"
L["@targettarget - target of target"] = "@targettarget - objetivo del objetivo"
L["Alt is held down."] = "Tienes pulsada Alt."
L["Any modifier key is held down."] = "Tienes pulsada cualquier tecla modificadora."
L["Any text. Everything the builder does not know ends up here, so nothing is lost."] = "Cualquier texto. Todo lo que el editor no conoce acaba aquí, así no se pierde nada."
L["Cancel buff"] = "Cancelar beneficio"
L["Cancel form"] = "Cancelar forma"
L["Cancel targeting"] = "Cancelar selección"
L["Cancels a spell that is waiting for a target (glowing hand or ground circle)."] = "Cancela un hechizo que está esperando objetivo (la mano brillante o el círculo en el suelo)."
L["Cancels the spell you are casting right now. Put it before an interrupt."] = "Cancela el hechizo que estás lanzando ahora mismo. Ponlo antes de una interrupción."
L["Cast sequence"] = "Secuencia de hechizos"
L["Cast spell"] = "Lanzar hechizo"
L["Casts a random spell from the list."] = "Lanza un hechizo al azar de la lista."
L["Casts a spell. With several variants the first one whose conditions match is cast."] = "Lanza un hechizo. Con varias variantes se lanza la primera cuyas condiciones se cumplan."
L["Change action bar page"] = "Cambiar página de la barra"
L["Changes a game setting (CVar), e.g. to mute error sounds."] = "Cambia un ajuste del juego (CVar), p. ej. para silenciar los sonidos de error."
L["Chat message"] = "Mensaje de chat"
L["Clear focus"] = "Quitar foco"
L["Clear target"] = "Quitar objetivo"
L["Clears your focus."] = "Quita tu foco."
L["Clears your target, e.g. only when it is dead: [dead]."] = "Quita tu objetivo, p. ej. solo cuando está muerto: [dead]."
L["Click a button"] = "Pulsar un botón"
L["Console setting"] = "Ajuste de consola"
L["Ctrl is held down."] = "Tienes pulsada Ctrl."
L["Cycles through your party members."] = "Va pasando por los miembros de tu grupo."
L["Cycles through your raid members."] = "Va pasando por los miembros de tu banda."
L["Cycles to the nearest enemy (like Tab)."] = "Pasa al enemigo más cercano (como Tab)."
L["Cycles to the nearest enemy player."] = "Pasa al jugador enemigo más cercano."
L["Cycles to the nearest friendly player."] = "Pasa al jugador amistoso más cercano."
L["Cycles to the nearest friendly unit."] = "Pasa a la unidad amistosa más cercana."
L["Default (current target)"] = "Por defecto (objetivo actual)"
L["Dismount"] = "Desmontar"
L["Each press casts the next spell of the list. reset= sets when it starts over."] = "Cada pulsación lanza el siguiente hechizo de la lista. reset= indica cuándo vuelve a empezar."
L["Emote"] = "Emoción"
L["Ends the macro at this line when the conditions match. All lines below are skipped."] = "Termina la macro en esta línea cuando se cumplen las condiciones. Se saltan todas las líneas de debajo."
L["Equip into slot"] = "Equipar en una casilla"
L["Equip item"] = "Equipar objeto"
L["Equips an item in its default slot."] = "Equipa un objeto en su casilla normal."
L["Equips an item into a specific slot (16 main hand, 17 off hand, 18 ranged, 13/14 trinkets)."] = "Equipa un objeto en una casilla concreta (16 mano derecha, 17 mano izquierda, 18 a distancia, 13/14 abalorios)."
L["Error:"] = "Error:"
L["Follow"] = "Seguir"
L["Follows a player automatically."] = "Sigue a un jugador automáticamente."
L["Free line"] = "Línea libre"
L["Gets off your mount, usually with [mounted]."] = "Te bajas de la montura, normalmente con [mounted]."
L["Goes back to your previous target."] = "Vuelve a tu objetivo anterior."
L["Last enemy"] = "Último enemigo"
L["Last friend"] = "Último amistoso"
