L["Leaves your current shapeshift form (druid forms, Ghost Wolf, Shadowform...)."] = "Sale de tu forma actual (formas de druida, Ghost Wolf, Forma de las Sombras...)."
L["Lua script"] = "Script de Lua"
L["Macros can't be changed in combat."] = "Las macros no se pueden cambiar en combate."
L["Modifier"] = "Modificador"
L["Moves your pet to a spot. Combine it with the target @cursor."] = "Mueve a tu mascota a un sitio. Combínalo con el objetivo @cursor."
L["Name or family, e.g. Imp, Voidwalker, Cat"] = "Nombre o familia, p. ej. Diablillo, Abisario, Gato"
L["No free macro slot"] = "No hay hueco libre para macros"
L["Pet: aggressive"] = "Mascota: agresiva"
L["Pet: attack"] = "Mascota: atacar"
