L["Please enter a name."] = "Escribe un nombre."
L["Presses another button by its frame name, e.g. to trigger an action bar slot."] = "Pulsa otro botón por su nombre de marco, p. ej. para activar una casilla de la barra de acción."
L["Puts a raid marker on your target: 1 star, 2 circle, 3 diamond, 4 triangle, 5 moon, 6 square, 7 cross, 8 skull."] = "Pone una marca de banda en tu objetivo: 1 estrella, 2 círculo, 3 diamante, 4 triángulo, 5 luna, 6 cuadrado, 7 cruz, 8 calavera."
