L["Remembers a unit as focus so you can cast on it with @focus."] = "Guarda una unidad como foco para lanzarle hechizos con @focus."
L["Removes a buff from you, e.g. Ice Block or a speed buff."] = "Te quita un beneficio, p. ej. Ice Block o uno de velocidad."
L["Runs a line of Lua code (same as /run)."] = "Ejecuta una línea de código Lua (igual que /run)."
L["Runs a line of Lua code. Protected actions (spells, targeting) are blocked in combat."] = "Ejecuta una línea de código Lua. Las acciones protegidas (hechizos, cambiar de objetivo) se bloquean en combate."
L["Sends a chat message (say, party, raid, emote...). %t is replaced by your target's name."] = "Envía un mensaje al chat (decir, grupo, banda, emoción...). %t se cambia por el nombre de tu objetivo."
L["Sends your pet to attack your target (or the unit you choose)."] = "Manda a tu mascota a atacar a tu objetivo (o a la unidad que elijas)."
