L["Stop casting"] = "Dejar de lanzar"
L["Stop macro here"] = "Parar la macro aquí"
L["Swap action bar pages"] = "Alternar páginas de barra"
L["Switches autocast for a pet ability on or off."] = "Activa o desactiva el autohechizo de una habilidad de la mascota."
L["Switches your main action bar to another page (like Shift+1 ... 6). Great with modifiers or stances."] = "Cambia tu barra de acción principal a otra página (como Mayús+1 ... 6). Va muy bien con modificadores o actitudes."
L["Takes over the target of another unit or player (e.g. the main tank)."] = "Coge el objetivo de otra unidad o jugador (p. ej. el tanque principal)."
L["Target exact name"] = "Objetivo por nombre exacto"
