L["Targets a unit or the closest match for a name. Leave the name empty and pick e.g. @mouseover."] = "Selecciona una unidad o la que más se parezca a un nombre. Deja el nombre vacío y elige, p. ej., @mouseover."
L["Targets only a unit with exactly this name."] = "Selecciona solo una unidad con exactamente este nombre."
