L["Targets the last friendly unit you had targeted."] = "Selecciona la última unidad amistosa que tuviste de objetivo."
L["The macro is empty."] = "La macro está vacía."
L["The stance or form action bar: warrior 1 Battle, 2 Defensive, 3 Berserker; druid 1 Cat, 3 Bear; rogue 1 Stealth."] = "La barra de actitud o forma: guerrero 1 batalla, 2 defensiva, 3 rabiosa; druida 1 felina, 3 oso; pícaro 1 sigilo."
L["The target can be attacked."] = "Se puede atacar al objetivo."
