L["Toggles your main action bar between two pages."] = "Alterna tu barra de acción principal entre dos páginas."
L["Too long: %1$d / %2$d characters."] = "Demasiado larga: %1$d / %2$d caracteres."
L["Turns off auto-attack, e.g. so you do not break crowd control."] = "Desactiva el ataque automático, p. ej. para no romper un control de masas."
