L["Circle: the round map in WoW Forever's ring. Square: the EllesmereUI square map in a thin bronze frame, with the zone name in its title bar. Applies after a UI reload."] = "Círculo: el mapa redondo en el anillo de WoW Forever. Cuadrado: el mapa cuadrado de EllesmereUI en un marco fino de bronce, con el nombre de la zona en su barra de título. Se aplica tras recargar la interfaz."
L["Forever Circle: the round map in WoW Forever's ring. Forever Square: the EllesmereUI square map in the bronze frame of WoW Forever's windows, with the zone name in its title bar. Applies after a UI reload."] = "Círculo Forever: el mapa redondo en el anillo de WoW Forever. Cuadrado Forever: el mapa cuadrado de EllesmereUI en el marco de bronce de las ventanas de WoW Forever, con el nombre de la zona en su barra de título. Se aplica tras recargar la interfaz."
L["Potion Ready Alert"] = "Aviso poción lista"
L["Potion Ready Alert Settings"] = "Ajustes del aviso de poción lista"
L["Shows on-screen text when a potion you used is off cooldown again. Use the cog to set the text, size and color; use Unlock Mode to reposition the alerts."] = "Muestra un texto en pantalla cuando una poción que usaste vuelve a estar lista. Usa el engranaje para el texto, el tamaño y el color; usa el desbloqueo para mover los avisos."
L["Shows on-screen text while you have unspent talent points. It stays up until you spend them or open your talents, and returns after a level-up. Use the cog to set the text, size and color; use Unlock Mode to reposition the alerts."] = "Muestra un texto en pantalla mientras tengas puntos de talento sin gastar. Se queda hasta que los gastes o abras tus talentos, y vuelve al subir de nivel. Usa el engranaje para el texto, el tamaño y el color; usa el desbloqueo para mover los avisos."
L["Unspent Talents Alert"] = "Aviso de talentos"
L["Unspent Talents Alert Settings"] = "Ajustes del aviso de talentos"
L["/way Command"] = "Comando /way"
