L["Also announces arrival at pins you place."] = "También avisa al llegar a las marcas que pones tú."
L["Enable /way Command"] = "Activar /way"
L["Hand-Placed Pin Arrival"] = "Llegada a marcas propias"
L["Choose which Blizzard elements to hide."] = "Elige qué elementos de Blizzard ocultar."
L["Ignore Low Level Quests"] = "Ignorar misiones bajas"
L["Silences the talking head's voice lines."] = "Silencia las frases habladas del busto parlante."
L["Experimental Quest Tools"] = "Herram. misiones exp."
