L["Loot council voting for your raid, synced over addon messages."] = "Votación de consejo de botín para tu banda, sincronizada con mensajes de addon."
L["Keep Standalone"] = "Mantener aparte"
L["Keeping the standalone leaves this copy idle. You can switch later from the Simple Loot Council page."] = "Si mantienes la copia independiente, esta se queda parada. Puedes cambiar más adelante desde la página de Simple Loot Council."
L["Simple Loot Council did not start: the EllesmereUI module expected the standalone copy to load, and it did not. Please report this; turning SimpleLootCouncil on in the AddOns list works around it."] = "Simple Loot Council no se inició: el módulo de EllesmereUI esperaba que se cargara la copia independiente y no se cargó. Avisa del fallo; activar SimpleLootCouncil en la lista de addons lo soluciona."
L["Simple Loot Council is installed twice, and the standalone copy is the one running. Switch to the EllesmereUI module? It keeps the council, history and settings it already has; the standalone copy's own are left as they are."] = "Simple Loot Council está instalado dos veces y la que funciona es la copia independiente. ¿Pasar al módulo de EllesmereUI? Se queda con el consejo, el historial y los ajustes que ya tiene; los de la copia independiente se dejan como están."
L["Simple Loot Council is installed twice, and the standalone copy is the one running. Switch to the EllesmereUI module? Your council, history and settings carry over."] = "Simple Loot Council está instalado dos veces y la que funciona es la copia independiente. ¿Pasar al módulo de EllesmereUI? Tu consejo, historial y ajustes pasan también."
L["Simple Loot Council: the standalone copy could not be turned off for you. Turn off SimpleLootCouncil in the AddOns list, then reload."] = "Simple Loot Council: no se pudo desactivar por ti la copia independiente. Desactiva SimpleLootCouncil en la lista de addons y recarga."
