L["This action is protected while dev mode (/euidev) is on."] = "Esta acción está protegida mientras el modo desarrollador (/euidev) esté activado."
L["This option does not work with the Gamepad interface style."] = "Esta opción no funciona con el estilo de interfaz de mando."
L["Space between loot rows or Icon Tray tiles. Loot Toast adds room for its decorative frame."] = "Espacio entre filas de botín o casillas de la Bandeja de iconos. Aviso de botín añade espacio para su marco decorativo."
L["Textured Pandemic Ring uses the aura's Border Size."] = "El anillo de pandemia con textura usa el tamaño de borde del aura."
L["This option requires a Pixels or Pixels Textured border above size 0."] = "Esta opción requiere un borde Pixels o Pixels Texturizado de tamaño mayor que 0."
L["This option requires a textured aura Border Style and a Border Size above 0."] = "Esta opción requiere un estilo de borde de aura con textura y un tamaño de borde mayor que 0."
L["This option requires a textured border."] = "Esta opción requiere un borde con textura."
L["This option requires an enabled textured border."] = "Esta opción requiere un borde con textura activado."
L["Show Bars"] = "Ver barras"
L["Adds a copyable Wowhead link to the right-click menu of quests in the quest tracker and quest log."] = "Añade un enlace de Wowhead que se puede copiar al menú contextual de las misiones del seguimiento y del registro de misiones."
L["A bar per group member with their kick's cooldown, read from their talents"] = "Una barra por miembro del grupo con la reutilización de su interrupción, leída de sus talentos"
L["An icon with its cooldown beside the enemy each player kicked"] = "Un icono con su reutilización junto al enemigo al que interrumpió cada jugador"
L["An older SimpleLootCouncil addon is enabled, so the Simple Loot Council module is off until that addon is disabled or updated."] = "Hay un addon SimpleLootCouncil antiguo activado, así que el módulo Simple Loot Council está desactivado hasta que lo desactives o lo actualices."
L["Cannot open options during combat. The Kick Tracker is under Mythic+ Tools in /eui."] = "No se pueden abrir las opciones en combate. El seguimiento de interrupciones está en Herramientas de mítica+, dentro de /eui."
L["Ctrl+C copies the link to the interactive feature spotlight"] = "Ctrl+C copia el enlace a la presentación interactiva de la función"
L["Marked mobs show their kicker's icon before the first kick lands"] = "Los enemigos marcados muestran el icono de quien los interrumpe antes de que llegue la primera interrupción"
L["My Focus Kick is %s"] = "Mi interr. foco: %s"
L["Nameplate Kick Tracker"] = "Interrup. en placas"
L["OLDER STANDALONE ADDON"] = "ADDON ANTIGUO"
L["Space between the elements sharing this slot. Follows the slot's Spacing until you change it."] = "Espacio entre los elementos que comparten esta ranura. Sigue el espaciado de la ranura hasta que lo cambies."
L["The Kick Tracker is under Mythic+ Tools in /eui."] = "El seguimiento de interrupciones está en Herramientas de mítica+, dentro de /eui."
L["Turning it on takes effect immediately, no reload needed. The Kick Tracker is under Mythic+ Tools in /eui."] = "Al activarlo se aplica al instante, sin recargar. El seguimiento de interrupciones está en Herramientas de mítica+, dentro de /eui."
L["Use at your own risk: Blizzard restrictions can keep custom spells from working fully."] = "Úsalo bajo tu responsabilidad: las restricciones de Blizzard pueden impedir que los hechizos personalizados funcionen del todo."
L["Your group's interrupts on the enemy nameplates themselves: who kicked what, who is ready next and where the next kick should land. It keeps working inside Mythic+ keys."] = "Tus interrupciones de grupo en las propias placas de los enemigos: quién interrumpió qué, quién está listo después y dónde debería caer la siguiente interrupción. Sigue funcionando dentro de las llaves de mítica+."

-- == Seguimiento de interrupciones (Kick Tracker) ==========================
L["Kick Tracker"] = "Interrupciones"
L["The dark sweep over the icon that clears as the interrupt comes back."] = "El barrido oscuro sobre el icono, que desaparece según vuelve la interrupción."
L["Class Color Border"] = "Borde color clase"
L["The icon's border in the kicker's class color; black when the game hides the kicker's class."] = "El borde del icono con el color de clase de quien interrumpe; negro si esa persona está oculta."
L["Grey the icon while the kicker's interrupt is on cooldown."] = "Pone el icono en gris mientras la interrupción de esa persona está en reutilización."
L["The interrupt's icon at the end of the row."] = "El icono de la interrupción al final de la fila."
L["The member's name on the row."] = "El nombre del miembro en la fila."
L["Timer"] = "Tiempo"
L["The seconds left on the interrupt, on the right of its row."] = "Los segundos que quedan de la interrupción, a la derecha de su fila."
L["Marker"] = "Marca"
L["The raid marker of the enemy the member interrupted, beside their row while that interrupt is on cooldown."] = "La marca de banda del enemigo al que interrumpió el miembro, junto a su fila mientras esa interrupción está en reutilización."
L["Spec Icon"] = "Icono espec."
L["Kick Icon"] = "Interrupción"
L["Edit Announce Text"] = "Editar anuncio"
L["Sent in party chat at the ready check. {marker} stands for your raid marker. Empty brings the default line back."] = "Se envía al chat de grupo en la comprobación de listos. {marker} es tu marca de banda. Si lo dejas vacío, vuelve la frase por defecto."
L["Enter your announce line..."] = "Escribe tu frase de anuncio..."
L["KICK TRACKER"] = "INTERRUPCIONES"
L["Enable Kick Tracker"] = "Activar interrupciones"
L["Who in the group kicked each enemy and when their interrupt comes back, read from Blizzard's own damage meter (which must be on). Others' cooldowns follow their class, spec and talents, read before a key starts; yours follow your own talents."] = "Quién del grupo interrumpió a cada enemigo y cuándo vuelve su interrupción, leído del medidor de daño de Blizzard (que debe estar activado). Las reutilizaciones de los demás dependen de su clase, especialización y talentos, leídos antes de empezar la llave; la tuya, de tus propios talentos."
L["The tracker runs in Mythic and Mythic+ dungeons and arenas only; untick one to turn it off there."] = "El seguimiento solo funciona en mazmorras míticas y míticas+ y en arenas; desmarca una para excluirla."
L["Focus Announce"] = "Anuncio del foco"
L["Tells the party your focus marker at ready checks."] = "Dice al grupo la marca de tu foco en las comprobaciones de listos."
L["Change the line Focus Announce sends: your own words, with {marker} where your raid marker goes."] = "Cambia la frase que envía Anuncio del foco: con tus propias palabras y {marker} donde va tu marca de banda."
L["NAMEPLATE ICON"] = "ICONO EN PLACAS"
L["Kick icons with their cooldown on the kicked enemies' nameplates."] = "Iconos de interrupción con su reutilización en las placas de los enemigos interrumpidos."
L["The kicker's interrupt icon, their spec icon or their class icon. A kick the tracker cannot place on a member shows no icon."] = "El icono de la interrupción, el de su especialización o el de su clase. Una interrupción que el seguimiento no puede asignar a un miembro no muestra icono."
L["The side of the nameplate the icon sits on."] = "El lado de la placa en el que se coloca el icono."
L["Position Offsets"] = "Desplazamientos"
L["On EllesmereUI nameplates."] = "En las placas de EllesmereUI."
L["On Blizzard's or another addon's nameplates."] = "En las placas de Blizzard o de otro addon."
L["Show Cooldown Timer"] = "Ver tiempo reutil."
L["The seconds left on the kicker's interrupt."] = "Los segundos que quedan de la interrupción."
L["Icon Effects"] = "Efectos icono"
L["The cooldown swipe, a border in the kicker's class color, and greying the icon while the interrupt is on cooldown."] = "El barrido de reutilización, un borde con el color de clase de quien interrumpe y poner el icono en gris mientras la interrupción está en reutilización."
L["Cooldown Timer"] = "Tiempo reutil."
L["Timer Position"] = "Pos. del tiempo"
L["Show Above Overlapping Nameplates"] = "Ver sobre placas solapadas"
L["The icons draw over every other nameplate, so an overlapping plate never hides one. When off, an icon stays inside its own nameplate, behind any plate that covers it."] = "Los iconos se dibujan sobre todas las demás placas, así que una placa solapada nunca oculta ninguno. Desactivado, el icono queda dentro de su propia placa, detrás de cualquier placa que lo cubra."
L["A row per group member with an interrupt: the interrupt's icon, their name on a bar in their class color, and the seconds left while it is on cooldown."] = "Una fila por cada miembro del grupo con interrupción: su icono, su nombre en una barra con su color de clase y los segundos que quedan mientras está en reutilización."
L["Which way the rows stack."] = "En qué sentido se apilan las filas."
L["Behind each row: a darkened version of the member's class color, or one custom color."] = "Detrás de cada fila: una versión oscurecida del color de clase del miembro, o un color propio."
L["Dark Class Color"] = "Color clase oscuro"
L["Display Elements"] = "Elementos a ver"
L["The interrupt's icon, the member's name, the seconds left on the interrupt and the raid marker of the enemy they interrupted."] = "El icono de la interrupción, el nombre del miembro, los segundos que quedan y la marca de banda del enemigo al que interrumpió."
L["Include Yourself"] = "Incluirte a ti"
L["Adds your own row, with its cooldown read from your talents."] = "Tu propia fila, con su reutilización según tus talentos."
L["Element Settings"] = "Ajustes elemento"
L["Kick Tracker Bars"] = "Barras interrup."
L["EllesmereUI:|r Kick Tracker announcement reset. It fires on your next /reload."] = "EllesmereUI:|r Anuncio del seguimiento de interrupciones restablecido. Saldrá en tu próximo /reload."

-- == Kick Tracker: tamaños, texturas y descripción =========================
L["Kick Tracker Timer Size"] = "Tam. tiempo interrup."
L["Kick Tracker Bar Name Size"] = "Tam. nombre barras int."
L["Kick Tracker Bar Timer Size"] = "Tam. tiempo barras int."
L["Kick Tracker Bar Texture"] = "Textura barras interr."
L["Mythic+ timer, Kick Tracker, cast bars and target/focus bars."] = "Cronómetro de mítica+, seguimiento de interrupciones, barras de hechizos y barras de objetivo y foco."
